import os
import re
from ansible.module_utils.basic import AnsibleModule

class Blacklist(object):

    def __init__(self, module, filename, checkmode):
        self.filename = filename
        self.module = module
        self.checkmode = checkmode

    def create_file(self):
        if not self.checkmode and (not os.path.exists(self.filename)):
            open(self.filename, 'a').close()
            return True
        elif self.checkmode and (not os.path.exists(self.filename)):
            self.filename = os.devnull
            return True
        else:
            return False

    def get_pattern(self):
        return '^blacklist\\s*' + self.module + '$'

    def readlines(self):
        f = open(self.filename, 'r')
        lines = f.readlines()
        f.close()
        return lines

    def module_listed(self):
        lines = self.readlines()
        pattern = self.get_pattern()
        for line in lines:
            stripped = line.strip()
            if stripped.startswith('#'):
                continue
            if re.match(pattern, stripped):
                return True
        return False

    def remove_module(self):
        lines = self.readlines()
        pattern = self.get_pattern()
        if self.checkmode:
            f = open(os.devnull, 'w')
        else:
            f = open(self.filename, 'w')
        for line in lines:
            if not re.match(pattern, line.strip()):
                f.write(line)
        f.close()

    def add_module(self):
        if self.checkmode:
            f = open(os.devnull, 'a')
        else:
            f = open(self.filename, 'a')
        f.write('blacklist %s\n' % self.module)
        f.close()

def main():
    module = AnsibleModule(argument_spec=dict(name=dict(type='str', required=True), state=dict(type='str', default='present', choices=['absent', 'present']), blacklist_file=dict(type='str')), supports_check_mode=True)
    args = dict(changed=False, failed=False, name=module.params['name'], state=module.params['state'])
    filename = '/etc/modprobe.d/blacklist-ansible.conf'
    if module.params['blacklist_file']:
        filename = module.params['blacklist_file']
    blacklist = Blacklist(args['name'], filename, module.check_mode)
    if blacklist.create_file():
        args['changed'] = True
    else:
        args['changed'] = False
    if blacklist.module_listed():
        if args['state'] == 'absent':
            blacklist.remove_module()
            args['changed'] = True
    elif args['state'] == 'present':
        blacklist.add_module()
        args['changed'] = True
    module.exit_json(**args)
if __name__ == '__main__':
    main()

"""
    werkzeug.contrib.cache
    ~~~~~~~~~~~~~~~~~~~~~~

    The main problem with dynamic Web sites is, well, they're dynamic.  Each
    time a user requests a page, the webserver executes a lot of code, queries
    the database, renders templates until the visitor gets the page he sees.

    This is a lot more expensive than just loading a file from the file system
    and sending it to the visitor.

    For most Web applications, this overhead isn't a big deal but once it
    becomes, you will be glad to have a cache system in place.

    How Caching Works
    =================

    Caching is pretty simple.  Basically you have a cache object lurking around
    somewhere that is connected to a remote cache or the file system or
    something else.  When the request comes in you check if the current page
    is already in the cache and if so, you're returning it from the cache.
    Otherwise you generate the page and put it into the cache. (Or a fragment
    of the page, you don't have to cache the full thing)

    Here is a simple example of how to cache a sidebar for a template::

        def get_sidebar(user):
            identifier = 'sidebar_for/user%d' % user.id
            value = cache.get(identifier)
            if value is not None:
                return value
            value = generate_sidebar_for(user=user)
            cache.set(identifier, value, timeout=60 * 5)
            return value

    Creating a Cache Object
    =======================

    To create a cache object you just import the cache system of your choice
    from the cache module and instantiate it.  Then you can start working
    with that object:

    >>> from werkzeug.contrib.cache import SimpleCache
    >>> c = SimpleCache()
    >>> c.set("foo", "value")
    >>> c.get("foo")
    'value'
    >>> c.get("missing") is None
    True

    Please keep in mind that you have to create the cache and put it somewhere
    you have access to it (either as a module global you can import or you just
    put it into your WSGI application).

    :copyright: (c) 2013 by the Werkzeug Team, see AUTHORS for more details.
    :license: BSD, see LICENSE for more details.
"""
