import os, re
from pyasm.biz import FileNaming, Project, Snapshot, File
from pyasm.common import TacticException

class FlashFileNaming(FileNaming):

    def add_ending(my, parts, auto_version=False):
        context = my.snapshot.get_value('context')
        version = my.snapshot.get_value('version')
        version = 'v%0.3d' % version
        ext = my.get_ext()
        parts.append(context)
        parts.append(version)
        filename = '_'.join(parts)
        filename = '%s%s' % (filename, ext)
        return filename

    def _get_unique_filename(my):
        filename = my.file_object.get_full_file_name()
        file = File.get_by_filename(filename, skip_id=my.file_object.get_id())
        if file:
            (root, ext) = os.path.splitext(filename)
            parts = [root]
            filename = my.add_ending(parts, auto_version=True)
            return filename
        else:
            return None

    def flash_nat_pause(my):
        return my._get_unique_filename()

    def flash_final_wave(my):
        return my._get_unique_filename()

"""
Simple DOM for both SGML and XML documents.
"""
from __future__ import division
from __future__ import generators
from __future__ import nested_scopes
import transforms

class Container:

    def __init__(self):
        self.children = []

    def add(self, child):
        child.parent = self
        self.children.append(child)

    def extend(self, children):
        for child in children:
            child.parent = self
            self.children.append(child)

class Component:

    def __init__(self):
        self.parent = None

    def index(self):
        if self.parent:
            return self.parent.children.index(self)
        else:
            return 0

    def _line(self, file, line, column):
        self.file = file
        self.line = line
        self.column = column

class DispatchError(Exception):

    def __init__(self, scope, f):
        msg = 'no such attribtue'

class Dispatcher:

    def is_type(self, type):
        cls = self
        while cls != None:
            if cls.type == type:
                return True
            cls = cls.base
        return False

    def dispatch(self, f, attrs=''):
        cls = self
        while cls != None:
            if hasattr(f, cls.type):
                return getattr(f, cls.type)(self)
            else:
                cls = cls.base
        cls = self
        while cls != None:
            if attrs:
                sep = ', '
                if cls.base == None:
                    sep += 'or '
            else:
                sep = ''
            attrs += "%s'%s'" % (sep, cls.type)
            cls = cls.base
        raise AttributeError("'%s' object has no attribute %s" % (f.__class__.__name__, attrs))

class Node(Container, Component, Dispatcher):
    type = 'node'
    base = None

    def __init__(self):
        Container.__init__(self)
        Component.__init__(self)
        self.query = Query([self])

    def __getitem__(self, name):
        for nd in self.query[name]:
            return nd

    def text(self):
        return self.dispatch(transforms.Text())

    def tag(self, name, *attrs, **kwargs):
        t = Tag(name, *attrs, **kwargs)
        self.add(t)
        return t

    def data(self, s):
        d = Data(s)
        self.add(d)
        return d

    def entity(self, s):
        e = Entity(s)
        self.add(e)
        return e

class Tree(Node):
    type = 'tree'
    base = Node

class Tag(Node):
    type = 'tag'
    base = Node

    def __init__(self, _name, *attrs, **kwargs):
        Node.__init__(self)
        self.name = _name
        self.attrs = list(attrs)
        self.attrs.extend(kwargs.items())
        self.singleton = False

    def get_attr(self, name):
        for (k, v) in self.attrs:
            if name == k:
                return v

    def _idx(self, attr):
        idx = 0
        for (k, v) in self.attrs:
            if k == attr:
                return idx
            idx += 1
        return None

    def set_attr(self, name, value):
        idx = self._idx(name)
        if idx is None:
            self.attrs.append((name, value))
        else:
            self.attrs[idx] = (name, value)

    def dispatch(self, f):
        try:
            attr = 'do_' + self.name
            method = getattr(f, attr)
        except AttributeError:
            return Dispatcher.dispatch(self, f, "'%s'" % attr)
        return method(self)

class Leaf(Component, Dispatcher):
    type = 'leaf'
    base = None

    def __init__(self, data):
        assert isinstance(data, basestring)
        self.data = data

class Data(Leaf):
    type = 'data'
    base = Leaf

class Entity(Leaf):
    type = 'entity'
    base = Leaf

class Character(Leaf):
    type = 'character'
    base = Leaf

class Comment(Leaf):
    type = 'comment'
    base = Leaf

class Adder:

    def __add__(self, other):
        return Sum(self, other)

class Sum(Adder):

    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __iter__(self):
        for x in self.left:
            yield x
        for x in self.right:
            yield x

class View(Adder):

    def __init__(self, source):
        self.source = source

class Filter(View):

    def __init__(self, predicate, source):
        View.__init__(self, source)
        self.predicate = predicate

    def __iter__(self):
        for nd in self.source:
            if self.predicate(nd):
                yield nd

class Flatten(View):

    def __iter__(self):
        sources = [iter(self.source)]
        while sources:
            try:
                nd = sources[-1].next()
                if isinstance(nd, Tree):
                    sources.append(iter(nd.children))
                else:
                    yield nd
            except StopIteration:
                sources.pop()

class Children(View):

    def __iter__(self):
        for nd in self.source:
            for child in nd.children:
                yield child

class Attributes(View):

    def __iter__(self):
        for nd in self.source:
            for a in nd.attrs:
                yield a

class Values(View):

    def __iter__(self):
        for (name, value) in self.source:
            yield value

def flatten_path(path):
    if isinstance(path, basestring):
        for part in path.split('/'):
            yield part
    elif callable(path):
        yield path
    else:
        for p in path:
            for fp in flatten_path(p):
                yield fp

class Query(View):

    def __iter__(self):
        for nd in self.source:
            yield nd

    def __getitem__(self, path):
        query = self.source
        for p in flatten_path(path):
            if callable(p):
                select = Query
                pred = p
                source = query
            elif isinstance(p, basestring):
                if p[0] == '@':
                    select = Values
                    pred = lambda x, n=p[1:]: x[0] == n
                    source = Attributes(query)
                elif p[0] == '#':
                    select = Query
                    pred = lambda x, t=p[1:]: x.is_type(t)
                    source = Children(query)
                else:
                    select = Query
                    pred = lambda x, n=p: isinstance(x, Tag) and x.name == n
                    source = Flatten(Children(query))
            else:
                raise ValueError(p)
            query = select(Filter(pred, source))
        return query

import gdb
import os
import re
from linux import modules
if hasattr(gdb, 'Breakpoint'):

    class LoadModuleBreakpoint(gdb.Breakpoint):

        def __init__(self, spec, gdb_command):
            super(LoadModuleBreakpoint, self).__init__(spec, internal=True)
            self.silent = True
            self.gdb_command = gdb_command

        def stop(self):
            module = gdb.parse_and_eval('mod')
            module_name = module['name'].string()
            cmd = self.gdb_command
            cmd.module_files_updated = False
            show_pagination = gdb.execute('show pagination', to_string=True)
            pagination = show_pagination.endswith('on.\n')
            gdb.execute('set pagination off')
            if module_name in cmd.loaded_modules:
                gdb.write("refreshing all symbols to reload module '{0}'\n".format(module_name))
                cmd.load_all_symbols()
            else:
                cmd.load_module_symbols(module)
            gdb.execute('set pagination %s' % ('on' if pagination else 'off'))
            return False

class LxSymbols(gdb.Command):
    """(Re-)load symbols of Linux kernel and currently loaded modules.

The kernel (vmlinux) is taken from the current working directly. Modules (.ko)
are scanned recursively, starting in the same directory. Optionally, the module
search path can be extended by a space separated list of paths passed to the
lx-symbols command."""
    module_paths = []
    module_files = []
    module_files_updated = False
    loaded_modules = []
    breakpoint = None

    def __init__(self):
        super(LxSymbols, self).__init__('lx-symbols', gdb.COMMAND_FILES, gdb.COMPLETE_FILENAME)

    def _update_module_files(self):
        self.module_files = []
        for path in self.module_paths:
            gdb.write('scanning for modules in {0}\n'.format(path))
            for (root, dirs, files) in os.walk(path):
                for name in files:
                    if name.endswith('.ko'):
                        self.module_files.append(root + '/' + name)
        self.module_files_updated = True

    def _get_module_file(self, module_name):
        module_pattern = '.*/{0}\\.ko$'.format(module_name.replace('_', '[_\\-]'))
        for name in self.module_files:
            if re.match(module_pattern, name) and os.path.exists(name):
                return name
        return None

    def _section_arguments(self, module):
        try:
            sect_attrs = module['sect_attrs'].dereference()
        except gdb.error:
            return ''
        attrs = sect_attrs['attrs']
        section_name_to_address = {attrs[n]['name'].string(): attrs[n]['address'] for n in range(int(sect_attrs['nsections']))}
        args = []
        for section_name in ['.data', '.data..read_mostly', '.rodata', '.bss']:
            address = section_name_to_address.get(section_name)
            if address:
                args.append(' -s {name} {addr}'.format(name=section_name, addr=str(address)))
        return ''.join(args)

    def load_module_symbols(self, module):
        module_name = module['name'].string()
        module_addr = str(module['core_layout']['base']).split()[0]
        module_file = self._get_module_file(module_name)
        if not module_file and (not self.module_files_updated):
            self._update_module_files()
            module_file = self._get_module_file(module_name)
        if module_file:
            gdb.write('loading @{addr}: {filename}\n'.format(addr=module_addr, filename=module_file))
            cmdline = 'add-symbol-file {filename} {addr}{sections}'.format(filename=module_file, addr=module_addr, sections=self._section_arguments(module))
            gdb.execute(cmdline, to_string=True)
            if module_name not in self.loaded_modules:
                self.loaded_modules.append(module_name)
        else:
            gdb.write("no module object found for '{0}'\n".format(module_name))

    def load_all_symbols(self):
        gdb.write('loading vmlinux\n')
        saved_states = []
        if hasattr(gdb, 'breakpoints') and (not gdb.breakpoints() is None):
            for bp in gdb.breakpoints():
                saved_states.append({'breakpoint': bp, 'enabled': bp.enabled})
        gdb.execute('symbol-file', to_string=True)
        gdb.execute('symbol-file vmlinux')
        self.loaded_modules = []
        module_list = modules.module_list()
        if not module_list:
            gdb.write('no modules found\n')
        else:
            [self.load_module_symbols(module) for module in module_list]
        for saved_state in saved_states:
            saved_state['breakpoint'].enabled = saved_state['enabled']

    def invoke(self, arg, from_tty):
        self.module_paths = arg.split()
        self.module_paths.append(os.getcwd())
        self.module_files = []
        self.module_files_updated = False
        self.load_all_symbols()
        if hasattr(gdb, 'Breakpoint'):
            if self.breakpoint is not None:
                self.breakpoint.delete()
                self.breakpoint = None
            self.breakpoint = LoadModuleBreakpoint('kernel/module.c:do_init_module', self)
        else:
            gdb.write('Note: symbol update on module loading not supported with this gdb version\n')
LxSymbols()

