"""Documentation Flask Blueprint."""
import os
from flask import render_template, current_app, abort, url_for, Blueprint
from flask.helpers import send_from_directory
from werkzeug.utils import cached_property, import_string
from sphinx.websupport import WebSupport
from sphinx.websupport.errors import DocumentNotFoundError
from invenio.base.globals import cfg
from invenio.base.i18n import _
from flask.ext.breadcrumbs import default_breadcrumb_root, register_breadcrumb, current_breadcrumbs
from flask.ext.menu import register_menu

class DocsBlueprint(Blueprint):
    """Wrap blueprint with Sphinx ``WebSupport``."""

    @cached_property
    def documentation_package(self):
        """Return documentation package."""
        try:
            invenio_docs = import_string(cfg['DOCUMENTATION_PACKAGE'])
        except ImportError:
            import docs as invenio_docs
        return invenio_docs

    @cached_property
    def support(self):
        """Return an instance of Sphinx ``WebSupport``."""
        builddir = os.path.abspath(os.path.join(current_app.instance_path, 'docs'))
        return WebSupport(srcdir=self.documentation_package.__path__[0], builddir=builddir, staticroot=os.path.join(blueprint.url_prefix, 'static'), docroot=blueprint.url_prefix)

    def send_static_file(self, filename):
        """Return static file."""
        try:
            return super(self.__class__, self).send_static_file(filename)
        except:
            cache_timeout = self.get_send_file_max_age(filename)
            return send_from_directory(os.path.join(current_app.instance_path, 'docs', 'static'), filename, cache_timeout=cache_timeout)
blueprint = DocsBlueprint('documentation', __name__, url_prefix='/documentation', template_folder='templates', static_folder='static')
default_breadcrumb_root(blueprint, '.documentation')

@blueprint.route('/', strict_slashes=True)
@blueprint.route('/<path:docname>')
@register_menu(blueprint, 'main.documentation', _('Help'), order=99)
@register_breadcrumb(blueprint, '.', _('Help'))
def index(docname=None):
    """Render documentation page."""
    try:
        document = blueprint.support.get_document(docname or cfg['DOCUMENTATION_INDEX'])
    except DocumentNotFoundError:
        abort(404)
    additional_breadcrumbs = [{'text': document['title'], 'url': url_for('.index', docname=docname)}]
    return render_template('documentation/index.html', document=document, breadcrumbs=current_breadcrumbs + additional_breadcrumbs)

from __future__ import unicode_literals
from guessit import Guess
from guessit.transfo import SingleNodeGuesser
from guessit.patterns import weak_episode_rexps
import re
import logging
log = logging.getLogger(__name__)

def guess_weak_episodes_rexps(string, node):
    if 'episodeNumber' in node.root.info:
        return (None, None)
    for (rexp, span_adjust) in weak_episode_rexps:
        match = re.search(rexp, string, re.IGNORECASE)
        if match:
            metadata = match.groupdict()
            span = (match.start() + span_adjust[0], match.end() + span_adjust[1])
            epnum = int(metadata['episodeNumber'])
            if epnum > 100:
                (season, epnum) = (epnum // 100, epnum % 100)
                if season > 25:
                    continue
                return (Guess({'season': season, 'episodeNumber': epnum}, confidence=0.6), span)
            else:
                return (Guess(metadata, confidence=0.3), span)
    return (None, None)
guess_weak_episodes_rexps.use_node = True

def process(mtree):
    SingleNodeGuesser(guess_weak_episodes_rexps, 0.6, log).process(mtree)

