class CPUSample:

    def __init__(self, time, user, sys, io=0.0, swap=0.0):
        self.time = time
        self.user = user
        self.sys = sys
        self.io = io
        self.swap = swap

    @property
    def cpu(self):
        return self.user + self.sys

    def __str__(self):
