def get_schema_facts(cursor, schema=''):
    facts = {}
    cursor.execute("\n        select schema_name, schema_owner, create_time\n        from schemata\n        where not is_system_schema and schema_name not in ('public')\n        and (? = '' or schema_name ilike ?)\n    ", schema, schema)
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            facts[row.schema_name.lower()] = {'name': row.schema_name, 'owner': row.schema_owner, 'create_time': str(row.create_time), 'usage_roles': [], 'create_roles': []}
    cursor.execute("\n        select g.object_name as schema_name, r.name as role_name,\n        lower(g.privileges_description) privileges_description\n        from roles r join grants g\n        on g.grantee = r.name and g.object_type='SCHEMA'\n        and g.privileges_description like '%USAGE%'\n        and g.grantee not in ('public', 'dbadmin')\n        and (? = '' or g.object_name ilike ?)\n    ", schema, schema)
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            schema_key = row.schema_name.lower()
            if 'create' in row.privileges_description:
                facts[schema_key]['create_roles'].append(row.role_name)
            else:
                facts[schema_key]['usage_roles'].append(row.role_name)
    return facts

def get_user_facts(cursor, user=''):
    facts = {}
    cursor.execute("\n        select u.user_name, u.is_locked, u.lock_time,\n        p.password, p.acctexpired as is_expired,\n        u.profile_name, u.resource_pool,\n        u.all_roles, u.default_roles\n        from users u join password_auditor p on p.user_id = u.user_id\n        where not u.is_super_user\n        and (? = '' or u.user_name ilike ?)\n     ", user, user)
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            user_key = row.user_name.lower()
            facts[user_key] = {'name': row.user_name, 'locked': str(row.is_locked), 'password': row.password, 'expired': str(row.is_expired), 'profile': row.profile_name, 'resource_pool': row.resource_pool, 'roles': [], 'default_roles': []}
            if row.is_locked:
                facts[user_key]['locked_time'] = str(row.lock_time)
            if row.all_roles:
                facts[user_key]['roles'] = row.all_roles.replace(' ', '').split(',')
            if row.default_roles:
                facts[user_key]['default_roles'] = row.default_roles.replace(' ', '').split(',')
    return facts

def get_role_facts(cursor, role=''):
    facts = {}
    cursor.execute("\n        select r.name, r.assigned_roles\n        from roles r\n        where (? = '' or r.name ilike ?)\n    ", role, role)
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            role_key = row.name.lower()
            facts[role_key] = {'name': row.name, 'assigned_roles': []}
            if row.assigned_roles:
                facts[role_key]['assigned_roles'] = row.assigned_roles.replace(' ', '').split(',')
    return facts

def get_configuration_facts(cursor, parameter=''):
    facts = {}
    cursor.execute("\n        select c.parameter_name, c.current_value, c.default_value\n        from configuration_parameters c\n        where c.node_name = 'ALL'\n        and (? = '' or c.parameter_name ilike ?)\n    ", parameter, parameter)
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            facts[row.parameter_name.lower()] = {'parameter_name': row.parameter_name, 'current_value': row.current_value, 'default_value': row.default_value}
    return facts

def get_node_facts(cursor, schema=''):
    facts = {}
    cursor.execute('\n        select node_name, node_address, export_address, node_state, node_type,\n            catalog_path\n        from nodes\n    ')
    while True:
        rows = cursor.fetchmany(100)
        if not rows:
            break
        for row in rows:
            facts[row.node_address] = {'node_name': row.node_name, 'export_address': row.export_address, 'node_state': row.node_state, 'node_type': row.node_type, 'catalog_path': row.catalog_path}
    return facts

def main():
    module = AnsibleModule(argument_spec=dict(cluster=dict(default='localhost'), port=dict(default='5433'), db=dict(default=None), login_user=dict(default='dbadmin'), login_password=dict(default=None)), supports_check_mode=True)
    if not pyodbc_found:
        module.fail_json(msg='The python pyodbc module is required.')
    db = ''
    if module.params['db']:
        db = module.params['db']
    try:
        dsn = 'Driver=Vertica;Server=%s;Port=%s;Database=%s;User=%s;Password=%s;ConnectionLoadBalance=%s' % (module.params['cluster'], module.params['port'], db, module.params['login_user'], module.params['login_password'], 'true')
        db_conn = pyodbc.connect(dsn, autocommit=True)
        cursor = db_conn.cursor()
    except Exception:
        e = get_exception()
        module.fail_json(msg='Unable to connect to database: %s.' % str(e))
    try:
        schema_facts = get_schema_facts(cursor)
        user_facts = get_user_facts(cursor)
        role_facts = get_role_facts(cursor)
        configuration_facts = get_configuration_facts(cursor)
        node_facts = get_node_facts(cursor)
        module.exit_json(changed=False, ansible_facts={'vertica_schemas': schema_facts, 'vertica_users': user_facts, 'vertica_roles': role_facts, 'vertica_configuration': configuration_facts, 'vertica_nodes': node_facts})
    except NotSupportedError:
        e = get_exception()
        module.fail_json(msg=str(e))
    except SystemExit:
        raise
    except Exception:
        e = get_exception()
        module.fail_json(msg=e)
if __name__ == '__main__':
    main()

