mapfile = open(sys.argv[2], 'w')

def dodot(xyz, k):
    mapfile.write('%f %f %f %d\n' % (xyz[0], xyz[1], xyz[2], k))

def getmedian(s):
    items = s.split()
    j = -1
    for i in range(len(items)):
        if items[i] == 'median':
            j = i
    if j == -1:
        return 0
    return abs(float(items[j + 2]))
try:
    outersf = float(sys.argv[3])
except:
    outersf = 1.0
print('Scale factor is', outersf)
for g in gf:
    mapfile.write('\n\n')
    o = g.translation
    try:
        sf = pow(getmedian(g.intensity_info), 0.3333) * outersf
    except:
        sf = outersf
    try:
        k = int(g.npks)
    except:
        k = 1
    for u in g.ubi:
        dodot(o, k)
        dodot(o + u * sf, int(g.npks))
    for u in g.ubi:
        dodot(o, k)
        dodot(o - u * sf, int(g.npks))
mapfile.close()
