class crm_ais(crm_lha):
    """
    The crm version 3 cluster manager class.
    It implements the things we need to talk to and manipulate
    crm clusters running on top of openais
    """

    def __init__(self, Environment, randseed=None, name=None):
        if not name:
            name = 'crm-ais'
        crm_lha.__init__(self, Environment, randseed=randseed, name=name)
        self.fullcomplist = {}
        self.templates = PatternSelector(self.name)

    def NodeUUID(self, node):
        return node

    def ais_components(self, extra={}):
        complist = []
        if not len(self.fullcomplist.keys()):
            for c in ['cib', 'lrmd', 'crmd', 'attrd']:
                self.fullcomplist[c] = Process(self, c, pats=self.templates.get_component(self.name, c), badnews_ignore=self.templates.get_component(self.name, '%s-ignore' % c), common_ignore=self.templates.get_component(self.name, 'common-ignore'))
            self.fullcomplist['pengine'] = Process(self, 'pengine', dc_pats=self.templates.get_component(self.name, 'pengine'), badnews_ignore=self.templates.get_component(self.name, 'pengine-ignore'), common_ignore=self.templates.get_component(self.name, 'common-ignore'))
            self.fullcomplist['stonith-ng'] = Process(self, 'stonith-ng', process='stonithd', pats=self.templates.get_component(self.name, 'stonith'), badnews_ignore=self.templates.get_component(self.name, 'stonith-ignore'), common_ignore=self.templates.get_component(self.name, 'common-ignore'))
            self.fullcomplist.update(extra)
        vgrind = self.Env['valgrind-procs'].split()
        for key in list(self.fullcomplist.keys()):
            if self.Env['valgrind-tests']:
                if key in vgrind:
                    self.log('Filtering %s from the component list as it is being profiled by valgrind' % key)
                    continue
            if key == 'stonith-ng' and (not self.Env['DoFencing']):
                continue
            complist.append(self.fullcomplist[key])
        return complist

class crm_cs_v0(crm_ais):
    """
    The crm version 3 cluster manager class.
    It implements the things we need to talk to and manipulate

    crm clusters running against version 0 of our plugin
    """

    def __init__(self, Environment, randseed=None, name=None):
        if not name:
            name = 'crm-plugin-v0'
        crm_ais.__init__(self, Environment, randseed=randseed, name=name)

    def Components(self):
        extra = {}
        extra['corosync'] = Process(self, 'corosync', pats=self.templates.get_component(self.name, 'corosync'), badnews_ignore=self.templates.get_component(self.name, 'corosync-ignore'), common_ignore=self.templates.get_component(self.name, 'common-ignore'))
        return self.ais_components(extra=extra)

