        self._find_within(ancestor_selector + ' .action-more').click()
        EmptyPromise(lambda : self._is_element_visible(ancestor_selector + ' .actions-dropdown'), 'Secondary action menu opened').fulfill()
        yield
        if self._is_element_visible(ancestor_selector + ' .actions-dropdown'):
            self._find_within(ancestor_selector + ' .action-more').click()
            EmptyPromise(lambda : not self._is_element_visible(ancestor_selector + ' .actions-dropdown'), 'Secondary action menu closed').fulfill()

