class YeditException(Exception):
    """ Exception class for Yedit """
    pass

class Yedit(object):
    """ Class to modify yaml files """
    re_valid_key = '(((\\[-?\\d+\\])|([0-9a-zA-Z%s/_-]+)).?)+$'
    re_key = '(?:\\[(-?\\d+)\\])|([0-9a-zA-Z{}/_-]+)'
    com_sep = set(['.', '#', '|', ':'])

    def __init__(self, filename=None, content=None, content_type='yaml', separator='.', backup=False):
        self.content = content
        self._separator = separator
        self.filename = filename
        self.__yaml_dict = content
        self.content_type = content_type
        self.backup = backup
        self.load(content_type=self.content_type)
        if self.__yaml_dict is None:
            self.__yaml_dict = {}

    @property
    def separator(self):
        """ getter method for separator """
        return self._separator

    @separator.setter
    def separator(self, inc_sep):
        """ setter method for separator """
        self._separator = inc_sep

    @property
    def yaml_dict(self):
        """ getter method for yaml_dict """
        return self.__yaml_dict

    @yaml_dict.setter
    def yaml_dict(self, value):
        """ setter method for yaml_dict """
        self.__yaml_dict = value

    @staticmethod
    def parse_key(key, sep='.'):
        """parse the key allowing the appropriate separator"""
        common_separators = list(Yedit.com_sep - set([sep]))
        return re.findall(Yedit.re_key.format(''.join(common_separators)), key)

    @staticmethod
    def valid_key(key, sep='.'):
        """validate the incoming key"""
        common_separators = list(Yedit.com_sep - set([sep]))
        if not re.match(Yedit.re_valid_key.format(''.join(common_separators)), key):
            return False
        return True

    @staticmethod
    def remove_entry(data, key, sep='.'):
        """ remove data at location key """
        if key == '' and isinstance(data, dict):
            data.clear()
            return True
        elif key == '' and isinstance(data, list):
            del data[:]
            return True
        if not (key and Yedit.valid_key(key, sep)) and isinstance(data, (list, dict)):
            return None
        key_indexes = Yedit.parse_key(key, sep)
        for (arr_ind, dict_key) in key_indexes[:-1]:
            if dict_key and isinstance(data, dict):
                data = data.get(dict_key)
            elif arr_ind and isinstance(data, list) and (int(arr_ind) <= len(data) - 1):
                data = data[int(arr_ind)]
            else:
                return None
        if key_indexes[-1][0]:
            if isinstance(data, list) and int(key_indexes[-1][0]) <= len(data) - 1:
                del data[int(key_indexes[-1][0])]
                return True
        elif key_indexes[-1][1]:
            if isinstance(data, dict):
                del data[key_indexes[-1][1]]
                return True

    @staticmethod
    def add_entry(data, key, item=None, sep='.'):
        """ Get an item from a dictionary with key notation a.b.c
            d = {'a': {'b': 'c'}}}
            key = a#b
            return c
        """
        if key == '':
            pass
        elif not (key and Yedit.valid_key(key, sep)) and isinstance(data, (list, dict)):
            return None
        key_indexes = Yedit.parse_key(key, sep)
        for (arr_ind, dict_key) in key_indexes[:-1]:
            if dict_key:
                if isinstance(data, dict) and dict_key in data and data[dict_key]:
                    data = data[dict_key]
                    continue
                elif data and (not isinstance(data, dict)):
                    raise YeditException('Unexpected item type found while going through key ' + 'path: {} (at key: {})'.format(key, dict_key))
                data[dict_key] = {}
                data = data[dict_key]
            elif arr_ind and isinstance(data, list) and (int(arr_ind) <= len(data) - 1):
                data = data[int(arr_ind)]
            else:
                raise YeditException('Unexpected item type found while going through key path: {}'.format(key))
        if key == '':
            data = item
        elif key_indexes[-1][0] and isinstance(data, list) and (int(key_indexes[-1][0]) <= len(data) - 1):
            data[int(key_indexes[-1][0])] = item
        elif key_indexes[-1][1] and isinstance(data, dict):
            data[key_indexes[-1][1]] = item
        else:
            raise YeditException('Error adding to object at path: {}'.format(key))
        return data

    @staticmethod
    def get_entry(data, key, sep='.'):
        """ Get an item from a dictionary with key notation a.b.c
            d = {'a': {'b': 'c'}}}
            key = a.b
            return c
        """
        if key == '':
            pass
        elif not (key and Yedit.valid_key(key, sep)) and isinstance(data, (list, dict)):
            return None
        key_indexes = Yedit.parse_key(key, sep)
        for (arr_ind, dict_key) in key_indexes:
            if dict_key and isinstance(data, dict):
                data = data.get(dict_key)
            elif arr_ind and isinstance(data, list) and (int(arr_ind) <= len(data) - 1):
                data = data[int(arr_ind)]
            else:
                return None
        return data

    @staticmethod
    def _write(filename, contents):
        """ Actually write the file contents to disk. This helps with mocking. """
        tmp_filename = filename + '.yedit'
        with open(tmp_filename, 'w') as yfd:
            yfd.write(contents)
        os.rename(tmp_filename, filename)

    def write(self):
        """ write to file """
        if not self.filename:
            raise YeditException('Please specify a filename.')
        if self.backup and self.file_exists():
            shutil.copy(self.filename, self.filename + '.orig')
        try:
            self.yaml_dict.fa.set_block_style()
        except AttributeError:
            pass
        try:
            Yedit._write(self.filename, yaml.dump(self.yaml_dict, Dumper=yaml.RoundTripDumper))
        except AttributeError:
            Yedit._write(self.filename, yaml.safe_dump(self.yaml_dict, default_flow_style=False))
        return (True, self.yaml_dict)

    def read(self):
        """ read from file """
        if self.filename is None or not self.file_exists():
            return None
        contents = None
        with open(self.filename) as yfd:
            contents = yfd.read()
        return contents

    def file_exists(self):
        """ return whether file exists """
        if os.path.exists(self.filename):
            return True
        return False

    def load(self, content_type='yaml'):
        """ return yaml file """
        contents = self.read()
        if not contents and (not self.content):
            return None
        if self.content:
            if isinstance(self.content, dict):
                self.yaml_dict = self.content
                return self.yaml_dict
            elif isinstance(self.content, str):
                contents = self.content
        try:
            if content_type == 'yaml' and contents:
                try:
                    self.yaml_dict.fa.set_block_style()
                except AttributeError:
                    pass
                try:
                    self.yaml_dict = yaml.safe_load(contents, yaml.RoundTripLoader)
                except AttributeError:
                    self.yaml_dict = yaml.safe_load(contents)
                try:
                    self.yaml_dict.fa.set_block_style()
                except AttributeError:
                    pass
            elif content_type == 'json' and contents:
                self.yaml_dict = json.loads(contents)
        except yaml.YAMLError as err:
            raise YeditException('Problem with loading yaml file. {}'.format(err))
        return self.yaml_dict

    def get(self, key):
        """ get a specified key"""
        try:
            entry = Yedit.get_entry(self.yaml_dict, key, self.separator)
        except KeyError:
            entry = None
        return entry

    def pop(self, path, key_or_item):
        """ remove a key, value pair from a dict or an item for a list"""
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if entry is None:
            return (False, self.yaml_dict)
        if isinstance(entry, dict):
            if key_or_item in entry:
                entry.pop(key_or_item)
                return (True, self.yaml_dict)
            return (False, self.yaml_dict)
        elif isinstance(entry, list):
            ind = None
            try:
                ind = entry.index(key_or_item)
            except ValueError:
                return (False, self.yaml_dict)
            entry.pop(ind)
            return (True, self.yaml_dict)
        return (False, self.yaml_dict)

    def delete(self, path):
        """ remove path from a dict"""
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if entry is None:
            return (False, self.yaml_dict)
        result = Yedit.remove_entry(self.yaml_dict, path, self.separator)
        if not result:
            return (False, self.yaml_dict)
        return (True, self.yaml_dict)

    def exists(self, path, value):
        """ check if value exists at path"""
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if isinstance(entry, list):
            if value in entry:
                return True
            return False
        elif isinstance(entry, dict):
            if isinstance(value, dict):
                rval = False
                for (key, val) in value.items():
                    if entry[key] != val:
                        rval = False
                        break
                else:
                    rval = True
                return rval
            return value in entry
        return entry == value

    def append(self, path, value):
        """append value to a list"""
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if entry is None:
            self.put(path, [])
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        if not isinstance(entry, list):
            return (False, self.yaml_dict)
        entry.append(value)
        return (True, self.yaml_dict)

    def update(self, path, value, index=None, curr_value=None):
        """ put path, value into a dict """
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if isinstance(entry, dict):
            if not isinstance(value, dict):
                raise YeditException('Cannot replace key, value entry in dict with non-dict type. ' + 'value=[{}] type=[{}]'.format(value, type(value)))
            entry.update(value)
            return (True, self.yaml_dict)
        elif isinstance(entry, list):
            ind = None
            if curr_value:
                try:
                    ind = entry.index(curr_value)
                except ValueError:
                    return (False, self.yaml_dict)
            elif index is not None:
                ind = index
            if ind is not None and entry[ind] != value:
                entry[ind] = value
                return (True, self.yaml_dict)
            try:
                ind = entry.index(value)
            except ValueError:
                entry.append(value)
                return (True, self.yaml_dict)
            if ind is not None:
                return (False, self.yaml_dict)
        return (False, self.yaml_dict)

    def put(self, path, value):
        """ put path, value into a dict """
        try:
            entry = Yedit.get_entry(self.yaml_dict, path, self.separator)
        except KeyError:
            entry = None
        if entry == value:
            return (False, self.yaml_dict)
        try:
            tmp_copy = yaml.load(yaml.round_trip_dump(self.yaml_dict, default_flow_style=False), yaml.RoundTripLoader)
        except AttributeError:
            tmp_copy = copy.deepcopy(self.yaml_dict)
        try:
            tmp_copy.fa.set_block_style()
        except AttributeError:
            pass
        result = Yedit.add_entry(tmp_copy, path, value, self.separator)
        if result is None:
            return (False, self.yaml_dict)
        if path == '':
            if isinstance(result, list) or isinstance(result, dict):
                self.yaml_dict = result
                return (True, self.yaml_dict)
            return (False, self.yaml_dict)
        self.yaml_dict = tmp_copy
        return (True, self.yaml_dict)

    def create(self, path, value):
        """ create a yaml file """
        if not self.file_exists():
            try:
                tmp_copy = yaml.load(yaml.round_trip_dump(self.yaml_dict, default_flow_style=False), yaml.RoundTripLoader)
            except AttributeError:
                tmp_copy = copy.deepcopy(self.yaml_dict)
            try:
                tmp_copy.fa.set_block_style()
            except AttributeError:
                pass
            result = Yedit.add_entry(tmp_copy, path, value, self.separator)
            if result is not None:
                self.yaml_dict = tmp_copy
                return (True, self.yaml_dict)
        return (False, self.yaml_dict)

    @staticmethod
    def get_curr_value(invalue, val_type):
        """return the current value"""
        if invalue is None:
            return None
        curr_value = invalue
        if val_type == 'yaml':
            curr_value = yaml.load(invalue)
        elif val_type == 'json':
            curr_value = json.loads(invalue)
        return curr_value

    @staticmethod
    def parse_value(inc_value, vtype=''):
        """determine value type passed"""
        true_bools = ['y', 'Y', 'yes', 'Yes', 'YES', 'true', 'True', 'TRUE', 'on', 'On', 'ON']
        false_bools = ['n', 'N', 'no', 'No', 'NO', 'false', 'False', 'FALSE', 'off', 'Off', 'OFF']
        if isinstance(inc_value, str) and 'bool' in vtype:
            if inc_value not in true_bools and inc_value not in false_bools:
                raise YeditException('Not a boolean type. str=[{}] vtype=[{}]'.format(inc_value, vtype))
        elif isinstance(inc_value, bool) and 'str' in vtype:
            inc_value = str(inc_value)
        if isinstance(inc_value, str) and inc_value == '':
            pass
        elif isinstance(inc_value, str) and 'str' not in vtype:
            try:
                inc_value = yaml.safe_load(inc_value)
            except Exception:
                raise YeditException('Could not determine type of incoming value. ' + 'value=[{}] vtype=[{}]'.format(type(inc_value), vtype))
        return inc_value

    @staticmethod
    def process_edits(edits, yamlfile):
        """run through a list of edits and process them one-by-one"""
        results = []
        for edit in edits:
            value = Yedit.parse_value(edit['value'], edit.get('value_type', ''))
            if edit.get('action') == 'update':
                curr_value = Yedit.get_curr_value(Yedit.parse_value(edit.get('curr_value')), edit.get('curr_value_format'))
                rval = yamlfile.update(edit['key'], value, edit.get('index'), curr_value)
            elif edit.get('action') == 'append':
                rval = yamlfile.append(edit['key'], value)
            else:
                rval = yamlfile.put(edit['key'], value)
            if rval[0]:
                results.append({'key': edit['key'], 'edit': rval[1]})
        return {'changed': len(results) > 0, 'results': results}

    @staticmethod
    def run_ansible(params):
        """perform the idempotent crud operations"""
        yamlfile = Yedit(filename=params['src'], backup=params['backup'], separator=params['separator'])
        state = params['state']
        if params['src']:
            rval = yamlfile.load()
            if yamlfile.yaml_dict is None and state != 'present':
                return {'failed': True, 'msg': 'Error opening file [{}].  Verify that the '.format(params['src']) + 'file exists, that it is has correct permissions, and is valid yaml.'}
        if state == 'list':
            if params['content']:
                content = Yedit.parse_value(params['content'], params['content_type'])
                yamlfile.yaml_dict = content
            if params['key']:
                rval = yamlfile.get(params['key']) or {}
            return {'changed': False, 'result': rval, 'state': state}
        elif state == 'absent':
            if params['content']:
                content = Yedit.parse_value(params['content'], params['content_type'])
                yamlfile.yaml_dict = content
            if params['update']:
                rval = yamlfile.pop(params['key'], params['value'])
            else:
                rval = yamlfile.delete(params['key'])
            if rval[0] and params['src']:
                yamlfile.write()
            return {'changed': rval[0], 'result': rval[1], 'state': state}
        elif state == 'present':
            if params['content']:
                content = Yedit.parse_value(params['content'], params['content_type'])
                if yamlfile.yaml_dict == content and params['value'] is None:
                    return {'changed': False, 'result': yamlfile.yaml_dict, 'state': state}
                yamlfile.yaml_dict = content
            edits = []
            _edit = {}
            if params['value'] is not None:
                _edit['value'] = params['value']
                _edit['value_type'] = params['value_type']
                _edit['key'] = params['key']
                if params['update']:
                    _edit['action'] = 'update'
                    _edit['curr_value'] = params['curr_value']
                    _edit['curr_value_format'] = params['curr_value_format']
                    _edit['index'] = params['index']
                elif params['append']:
                    _edit['action'] = 'append'
                edits.append(_edit)
            elif params['edits'] is not None:
                edits = params['edits']
            if edits:
                results = Yedit.process_edits(edits, yamlfile)
                if results['changed'] and params['src']:
                    yamlfile.write()
                return {'changed': results['changed'], 'result': results['results'], 'state': state}
            if params['src']:
                rval = yamlfile.write()
                return {'changed': rval[0], 'result': rval[1], 'state': state}
            return {'changed': False, 'result': yamlfile.yaml_dict, 'state': state}
        return {'failed': True, 'msg': 'Unkown state passed'}

class OpenShiftCLIError(Exception):
    """Exception class for openshiftcli"""
    pass
ADDITIONAL_PATH_LOOKUPS = ['/usr/local/bin', os.path.expanduser('~/bin')]

def locate_oc_binary():
    """ Find and return oc binary file """
    paths = os.environ.get('PATH', os.defpath).split(os.pathsep) + ADDITIONAL_PATH_LOOKUPS
    oc_binary = 'oc'
    try:
        which_result = shutil.which(oc_binary, path=os.pathsep.join(paths))
        if which_result is not None:
            oc_binary = which_result
    except AttributeError:
        for path in paths:
            if os.path.exists(os.path.join(path, oc_binary)):
                oc_binary = os.path.join(path, oc_binary)
                break
    return oc_binary

class OpenShiftCLI(object):
    """ Class to wrap the command line tools """

    def __init__(self, namespace, kubeconfig='/etc/origin/master/admin.kubeconfig', verbose=False, all_namespaces=False):
        """ Constructor for OpenshiftCLI """
        self.namespace = namespace
        self.verbose = verbose
        self.kubeconfig = Utils.create_tmpfile_copy(kubeconfig)
        self.all_namespaces = all_namespaces
        self.oc_binary = locate_oc_binary()

    def _replace_content(self, resource, rname, content, force=False, sep='.'):
        """ replace the current object with the content """
        res = self._get(resource, rname)
        if not res['results']:
            return res
        fname = Utils.create_tmpfile(rname + '-')
        yed = Yedit(fname, res['results'][0], separator=sep)
        changes = []
        for (key, value) in content.items():
            changes.append(yed.put(key, value))
        if any([change[0] for change in changes]):
            yed.write()
            atexit.register(Utils.cleanup, [fname])
            return self._replace(fname, force)
        return {'returncode': 0, 'updated': False}

    def _replace(self, fname, force=False):
        """replace the current object with oc replace"""
        yed = Yedit(fname)
        results = yed.delete('metadata.resourceVersion')
        if results[0]:
            yed.write()
        cmd = ['replace', '-f', fname]
        if force:
            cmd.append('--force')
        return self.openshift_cmd(cmd)

    def _create_from_content(self, rname, content):
        """create a temporary file and then call oc create on it"""
        fname = Utils.create_tmpfile(rname + '-')
        yed = Yedit(fname, content=content)
        yed.write()
        atexit.register(Utils.cleanup, [fname])
        return self._create(fname)

    def _create(self, fname):
        """call oc create on a filename"""
        return self.openshift_cmd(['create', '-f', fname])

    def _delete(self, resource, name=None, selector=None):
        """call oc delete on a resource"""
        cmd = ['delete', resource]
        if selector is not None:
            cmd.append('--selector={}'.format(selector))
        elif name is not None:
            cmd.append(name)
        else:
            raise OpenShiftCLIError('Either name or selector is required when calling delete.')
        return self.openshift_cmd(cmd)

    def _process(self, template_name, create=False, params=None, template_data=None):
        """process a template

           template_name: the name of the template to process
           create: whether to send to oc create after processing
           params: the parameters for the template
           template_data: the incoming template's data; instead of a file
        """
        cmd = ['process']
        if template_data:
            cmd.extend(['-f', '-'])
        else:
            cmd.append(template_name)
        if params:
            param_str = ['{}={}'.format(key, str(value).replace("'", '"')) for (key, value) in params.items()]
            cmd.append('-v')
            cmd.extend(param_str)
        results = self.openshift_cmd(cmd, output=True, input_data=template_data)
        if results['returncode'] != 0 or not create:
            return results
        fname = Utils.create_tmpfile(template_name + '-')
        yed = Yedit(fname, results['results'])
        yed.write()
        atexit.register(Utils.cleanup, [fname])
        return self.openshift_cmd(['create', '-f', fname])

    def _get(self, resource, name=None, selector=None):
        """return a resource by name """
        cmd = ['get', resource]
        if selector is not None:
            cmd.append('--selector={}'.format(selector))
        elif name is not None:
            cmd.append(name)
        cmd.extend(['-o', 'json'])
        rval = self.openshift_cmd(cmd, output=True)
        if 'items' in rval:
            rval['results'] = rval['items']
        elif not isinstance(rval['results'], list):
            rval['results'] = [rval['results']]
        return rval

    def _schedulable(self, node=None, selector=None, schedulable=True):
        """ perform oadm manage-node scheduable """
        cmd = ['manage-node']
        if node:
            cmd.extend(node)
        else:
            cmd.append('--selector={}'.format(selector))
        cmd.append('--schedulable={}'.format(schedulable))
        return self.openshift_cmd(cmd, oadm=True, output=True, output_type='raw')

    def _list_pods(self, node=None, selector=None, pod_selector=None):
        """ perform oadm list pods

            node: the node in which to list pods
            selector: the label selector filter if provided
            pod_selector: the pod selector filter if provided
        """
        cmd = ['manage-node']
        if node:
            cmd.extend(node)
        else:
            cmd.append('--selector={}'.format(selector))
        if pod_selector:
            cmd.append('--pod-selector={}'.format(pod_selector))
        cmd.extend(['--list-pods', '-o', 'json'])
        return self.openshift_cmd(cmd, oadm=True, output=True, output_type='raw')

    def _evacuate(self, node=None, selector=None, pod_selector=None, dry_run=False, grace_period=None, force=False):
        """ perform oadm manage-node evacuate """
        cmd = ['manage-node']
        if node:
            cmd.extend(node)
        else:
            cmd.append('--selector={}'.format(selector))
        if dry_run:
            cmd.append('--dry-run')
        if pod_selector:
            cmd.append('--pod-selector={}'.format(pod_selector))
        if grace_period:
            cmd.append('--grace-period={}'.format(int(grace_period)))
        if force:
            cmd.append('--force')
        cmd.append('--evacuate')
        return self.openshift_cmd(cmd, oadm=True, output=True, output_type='raw')

    def _version(self):
        """ return the openshift version"""
        return self.openshift_cmd(['version'], output=True, output_type='raw')

    def _import_image(self, url=None, name=None, tag=None):
        """ perform image import """
        cmd = ['import-image']
        image = '{0}'.format(name)
        if tag:
            image += ':{0}'.format(tag)
        cmd.append(image)
        if url:
            cmd.append('--from={0}/{1}'.format(url, image))
        cmd.append('-n{0}'.format(self.namespace))
        cmd.append('--confirm')
        return self.openshift_cmd(cmd)

    def _run(self, cmds, input_data):
        """ Actually executes the command. This makes mocking easier. """
        curr_env = os.environ.copy()
        curr_env.update({'KUBECONFIG': self.kubeconfig})
        proc = subprocess.Popen(cmds, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=curr_env)
        (stdout, stderr) = proc.communicate(input_data)
        return (proc.returncode, stdout.decode('utf-8'), stderr.decode('utf-8'))

    def openshift_cmd(self, cmd, oadm=False, output=False, output_type='json', input_data=None):
        """Base command for oc """
        cmds = [self.oc_binary]
        if oadm:
            cmds.append('adm')
        cmds.extend(cmd)
        if self.all_namespaces:
            cmds.extend(['--all-namespaces'])
        elif self.namespace is not None and self.namespace.lower() not in ['none', 'emtpy']:
            cmds.extend(['-n', self.namespace])
        if self.verbose:
            print(' '.join(cmds))
        try:
            (returncode, stdout, stderr) = self._run(cmds, input_data)
        except OSError as ex:
            (returncode, stdout, stderr) = (1, '', 'Failed to execute {}: {}'.format(subprocess.list2cmdline(cmds), ex))
        rval = {'returncode': returncode, 'cmd': ' '.join(cmds)}
        if output_type == 'json':
            rval['results'] = {}
            if output and stdout:
                try:
                    rval['results'] = json.loads(stdout)
                except ValueError as verr:
                    if 'No JSON object could be decoded' in verr.args:
                        rval['err'] = verr.args
        elif output_type == 'raw':
            rval['results'] = stdout if output else ''
        if self.verbose:
            print('STDOUT: {0}'.format(stdout))
            print('STDERR: {0}'.format(stderr))
        if 'err' in rval or returncode != 0:
            rval.update({'stderr': stderr, 'stdout': stdout})
        return rval

class Utils(object):
    """ utilities for openshiftcli modules """

    @staticmethod
    def _write(filename, contents):
        """ Actually write the file contents to disk. This helps with mocking. """
        with open(filename, 'w') as sfd:
            sfd.write(contents)

    @staticmethod
    def create_tmp_file_from_contents(rname, data, ftype='yaml'):
        """ create a file in tmp with name and contents"""
        tmp = Utils.create_tmpfile(prefix=rname)
        if ftype == 'yaml':
            if hasattr(yaml, 'RoundTripDumper'):
                Utils._write(tmp, yaml.dump(data, Dumper=yaml.RoundTripDumper))
            else:
                Utils._write(tmp, yaml.safe_dump(data, default_flow_style=False))
        elif ftype == 'json':
            Utils._write(tmp, json.dumps(data))
        else:
            Utils._write(tmp, data)
        atexit.register(Utils.cleanup, [tmp])
        return tmp

    @staticmethod
    def create_tmpfile_copy(inc_file):
        """create a temporary copy of a file"""
        tmpfile = Utils.create_tmpfile('lib_openshift-')
        Utils._write(tmpfile, open(inc_file).read())
        atexit.register(Utils.cleanup, [tmpfile])
        return tmpfile

    @staticmethod
    def create_tmpfile(prefix='tmp'):
        """ Generates and returns a temporary file name """
        with tempfile.NamedTemporaryFile(prefix=prefix, delete=False) as tmp:
            return tmp.name

    @staticmethod
    def create_tmp_files_from_contents(content, content_type=None):
        """Turn an array of dict: filename, content into a files array"""
        if not isinstance(content, list):
            content = [content]
        files = []
        for item in content:
            path = Utils.create_tmp_file_from_contents(item['path'] + '-', item['data'], ftype=content_type)
            files.append({'name': os.path.basename(item['path']), 'path': path})
        return files

    @staticmethod
    def cleanup(files):
        """Clean up on exit """
        for sfile in files:
            if os.path.exists(sfile):
                if os.path.isdir(sfile):
                    shutil.rmtree(sfile)
                elif os.path.isfile(sfile):
                    os.remove(sfile)

    @staticmethod
    def exists(results, _name):
        """ Check to see if the results include the name """
        if not results:
            return False
        if Utils.find_result(results, _name):
            return True
        return False

    @staticmethod
    def find_result(results, _name):
        """ Find the specified result by name"""
        rval = None
        for result in results:
            if 'metadata' in result and result['metadata']['name'] == _name:
                rval = result
                break
        return rval

    @staticmethod
    def get_resource_file(sfile, sfile_type='yaml'):
        """ return the service file """
        contents = None
        with open(sfile) as sfd:
            contents = sfd.read()
        if sfile_type == 'yaml':
            if hasattr(yaml, 'RoundTripLoader'):
                contents = yaml.load(contents, yaml.RoundTripLoader)
            else:
                contents = yaml.safe_load(contents)
        elif sfile_type == 'json':
            contents = json.loads(contents)
        return contents

    @staticmethod
    def filter_versions(stdout):
        """ filter the oc version output """
        version_dict = {}
        version_search = ['oc', 'openshift', 'kubernetes']
        for line in stdout.strip().split('\n'):
            for term in version_search:
                if not line:
                    continue
                if line.startswith(term):
                    version_dict[term] = line.split()[-1]
        if 'openshift' not in version_dict:
            version_dict['openshift'] = version_dict['oc']
        return version_dict

    @staticmethod
    def add_custom_versions(versions):
        """ create custom versions strings """
        versions_dict = {}
        for (tech, version) in versions.items():
            if '-' in version:
                version = version.split('-')[0]
            if version.startswith('v'):
                versions_dict[tech + '_numeric'] = version[1:].split('+')[0]
                versions_dict[tech + '_short'] = version[1:4]
        return versions_dict

    @staticmethod
    def openshift_installed():
        """ check if openshift is installed """
        import rpm
        transaction_set = rpm.TransactionSet()
        rpmquery = transaction_set.dbMatch('name', 'atomic-openshift')
        return rpmquery.count() > 0

    @staticmethod
    def check_def_equal(user_def, result_def, skip_keys=None, debug=False):
        """ Given a user defined definition, compare it with the results given back by our query.  """
        skip = ['metadata', 'status']
        if skip_keys:
            skip.extend(skip_keys)
        for (key, value) in result_def.items():
            if key in skip:
                continue
            if isinstance(value, list):
                if key not in user_def:
                    if debug:
                        print('User data does not have key [%s]' % key)
                        print('User data: %s' % user_def)
                    return False
                if not isinstance(user_def[key], list):
                    if debug:
                        print('user_def[key] is not a list key=[%s] user_def[key]=%s' % (key, user_def[key]))
                    return False
                if len(user_def[key]) != len(value):
                    if debug:
                        print('List lengths are not equal.')
                        print('key=[%s]: user_def[%s] != value[%s]' % (key, len(user_def[key]), len(value)))
                        print('user_def: %s' % user_def[key])
                        print('value: %s' % value)
                    return False
                for values in zip(user_def[key], value):
                    if isinstance(values[0], dict) and isinstance(values[1], dict):
                        if debug:
                            print('sending list - list')
                            print(type(values[0]))
                            print(type(values[1]))
                        result = Utils.check_def_equal(values[0], values[1], skip_keys=skip_keys, debug=debug)
                        if not result:
                            print('list compare returned false')
                            return False
                    elif value != user_def[key]:
                        if debug:
                            print('value should be identical')
                            print(user_def[key])
                            print(value)
                        return False
            elif isinstance(value, dict):
                if key not in user_def:
                    if debug:
                        print('user_def does not have key [%s]' % key)
                    return False
                if not isinstance(user_def[key], dict):
                    if debug:
                        print('dict returned false: not instance of dict')
                    return False
                api_values = set(value.keys()) - set(skip)
                user_values = set(user_def[key].keys()) - set(skip)
                if api_values != user_values:
                    if debug:
                        print('keys are not equal in dict')
                        print(user_values)
                        print(api_values)
                    return False
                result = Utils.check_def_equal(user_def[key], value, skip_keys=skip_keys, debug=debug)
                if not result:
                    if debug:
                        print('dict returned false')
                        print(result)
                    return False
            elif key not in user_def or value != user_def[key]:
                if debug:
                    print('value not equal; user_def does not have key')
                    print(key)
                    print(value)
                    if key in user_def:
                        print(user_def[key])
                return False
        if debug:
            print('returning true')
        return True

class OpenShiftCLIConfig(object):
    """Generic Config"""

    def __init__(self, rname, namespace, kubeconfig, options):
        self.kubeconfig = kubeconfig
        self.name = rname
        self.namespace = namespace
        self._options = options

    @property
    def config_options(self):
        """ return config options """
        return self._options

    def to_option_list(self, ascommalist=''):
        """return all options as a string
           if ascommalist is set to the name of a key, and
           the value of that key is a dict, format the dict
           as a list of comma delimited key=value pairs"""
        return self.stringify(ascommalist)

    def stringify(self, ascommalist=''):
        """ return the options hash as cli params in a string
            if ascommalist is set to the name of a key, and
            the value of that key is a dict, format the dict
            as a list of comma delimited key=value pairs """
        rval = []
        for key in sorted(self.config_options.keys()):
            data = self.config_options[key]
            if data['include'] and (data['value'] or isinstance(data['value'], int)):
                if key == ascommalist:
                    val = ','.join(['{}={}'.format(kk, vv) for (kk, vv) in sorted(data['value'].items())])
                else:
                    val = data['value']
                rval.append('--{}={}'.format(key.replace('_', '-'), val))
        return rval

class OCLabel(OpenShiftCLI):
    """ Class to wrap the oc command line tools """

    def __init__(self, name, namespace, kind, kubeconfig, labels=None, selector=None, verbose=False):
        """ Constructor for OCLabel """
        super(OCLabel, self).__init__(namespace, kubeconfig=kubeconfig, verbose=verbose)
        self.name = name
        self.kind = kind
        self.labels = labels
        self._curr_labels = None
        self.selector = selector

    @property
    def current_labels(self):
        """property for the current labels"""
        if self._curr_labels is None:
            results = self.get()
            self._curr_labels = results['labels']
        return self._curr_labels

    @current_labels.setter
    def current_labels(self, data):
        """property setter for current labels"""
        self._curr_labels = data

    def compare_labels(self, host_labels):
        """ compare incoming labels against current labels"""
        for label in self.labels:
            if label['key'] not in host_labels or label['value'] != host_labels[label['key']]:
                return False
        return True

    def all_user_labels_exist(self):
        """ return whether all the labels already exist """
        for current_host_labels in self.current_labels:
            rbool = self.compare_labels(current_host_labels)
            if not rbool:
                return False
        return True

    def any_label_exists(self):
        """ return whether any single label already exists """
        for current_host_labels in self.current_labels:
            for label in self.labels:
                if label['key'] in current_host_labels:
                    return True
        return False

    def get_user_keys(self):
        """ go through list of user key:values and return all keys """
        user_keys = []
        for label in self.labels:
            user_keys.append(label['key'])
        return user_keys

    def get_current_label_keys(self):
        """ collect all the current label keys """
        current_label_keys = []
        for current_host_labels in self.current_labels:
            for key in current_host_labels.keys():
                current_label_keys.append(key)
        return list(set(current_label_keys))

    def get_extra_current_labels(self):
        """ return list of labels that are currently stored, but aren't
            in user-provided list """
        extra_labels = []
        user_label_keys = self.get_user_keys()
        current_label_keys = self.get_current_label_keys()
        for current_key in current_label_keys:
            if current_key not in user_label_keys:
                extra_labels.append(current_key)
        return extra_labels

    def extra_current_labels(self):
        """ return whether there are labels currently stored that user
            hasn't directly provided """
        extra_labels = self.get_extra_current_labels()
        if len(extra_labels) > 0:
            return True
        return False

    def replace(self):
        """ replace currently stored labels with user provided labels """
        cmd = self.cmd_template()
        extra_labels = self.get_extra_current_labels()
        if len(extra_labels) > 0:
            for label in extra_labels:
                cmd.append('{}-'.format(label))
        if len(self.labels) > 0:
            for label in self.labels:
                cmd.append('{}={}'.format(label['key'], label['value']))
        cmd.append('--overwrite')
        return self.openshift_cmd(cmd)

    def get(self):
        """return label information """
        result_dict = {}
        label_list = []
        if self.name:
            result = self._get(resource=self.kind, name=self.name, selector=self.selector)
            if result['results'][0] and 'labels' in result['results'][0]['metadata']:
                label_list.append(result['results'][0]['metadata']['labels'])
            else:
                label_list.append({})
        else:
            result = self._get(resource=self.kind, selector=self.selector)
            for item in result['results'][0]['items']:
                if 'labels' in item['metadata']:
                    label_list.append(item['metadata']['labels'])
                else:
                    label_list.append({})
        self.current_labels = label_list
        result_dict['labels'] = self.current_labels
        result_dict['item_count'] = len(self.current_labels)
        result['results'] = result_dict
        return result

    def cmd_template(self):
        """ boilerplate oc command for modifying lables on this object """
        cmd = ['label', self.kind]
        if self.selector:
            cmd.extend(['--selector', self.selector])
        elif self.name:
            cmd.extend([self.name])
        return cmd

    def add(self):
        """ add labels """
        cmd = self.cmd_template()
        for label in self.labels:
            cmd.append('{}={}'.format(label['key'], label['value']))
        cmd.append('--overwrite')
        return self.openshift_cmd(cmd)

    def delete(self):
        """delete the labels"""
        cmd = self.cmd_template()
        for label in self.labels:
            cmd.append('{}-'.format(label['key']))
        return self.openshift_cmd(cmd)

    @staticmethod
    def run_ansible(params, check_mode=False):
        """ run the idempotent ansible code

            prams comes from the ansible portion of this module
            check_mode: does the module support check mode. (module.check_mode)
        """
        oc_label = OCLabel(params['name'], params['namespace'], params['kind'], params['kubeconfig'], params['labels'], params['selector'], verbose=params['debug'])
        state = params['state']
        name = params['name']
        selector = params['selector']
        api_rval = oc_label.get()
        if state == 'list':
            return {'changed': False, 'results': api_rval['results'], 'state': 'list'}
        if state == 'add':
            if not (name or selector):
                return {'failed': True, 'msg': "Param 'name' or 'selector' is required if state == 'add'"}
            if not oc_label.all_user_labels_exist():
                if check_mode:
                    return {'changed': False, 'msg': 'Would have performed an addition.'}
                api_rval = oc_label.add()
                if api_rval['returncode'] != 0:
                    return {'failed': True, 'msg': api_rval}
                return {'changed': True, 'results': api_rval, 'state': 'add'}
            return {'changed': False, 'state': 'add'}
        if state == 'absent':
            if not (name or selector):
                return {'failed': True, 'msg': "Param 'name' or 'selector' is required if state == 'absent'"}
            if oc_label.any_label_exists():
                if check_mode:
                    return {'changed': False, 'msg': 'Would have performed a delete.'}
                api_rval = oc_label.delete()
                if api_rval['returncode'] != 0:
                    return {'failed': True, 'msg': api_rval}
                return {'changed': True, 'results': api_rval, 'state': 'absent'}
            return {'changed': False, 'state': 'absent'}
        if state == 'present':
            if not (name or selector):
                return {'failed': True, 'msg': "Param 'name' or 'selector' is required if state == 'present'"}
            if not oc_label.all_user_labels_exist() or oc_label.extra_current_labels():
                if check_mode:
                    return {'changed': False, 'msg': 'Would have made changes.'}
                api_rval = oc_label.replace()
                if api_rval['returncode'] != 0:
                    return {'failed': True, 'msg': api_rval}
                api_rval = oc_label.get()
                if api_rval['returncode'] != 0:
                    return {'failed': True, 'msg': api_rval}
                return {'changed': True, 'results': api_rval, 'state': 'present'}
            return {'changed': False, 'results': api_rval, 'state': 'present'}
        return {'failed': True, 'changed': False, 'results': 'Unknown state passed. %s' % state, 'state': 'unknown'}

def main():
    """ ansible oc module for labels """
    module = AnsibleModule(argument_spec=dict(kubeconfig=dict(default='/etc/origin/master/admin.kubeconfig', type='str'), state=dict(default='present', type='str', choices=['present', 'absent', 'list', 'add']), debug=dict(default=False, type='bool'), kind=dict(default='node', type='str', choices=['node', 'pod', 'namespace']), name=dict(default=None, type='str'), namespace=dict(default=None, type='str'), labels=dict(default=None, type='list'), selector=dict(default=None, type='str')), supports_check_mode=True, mutually_exclusive=['name', 'selector'])
    results = OCLabel.run_ansible(module.params, module.check_mode)
    if 'failed' in results:
        module.fail_json(**results)
    module.exit_json(**results)
if __name__ == '__main__':
    main()

