class calendar_alarm_manager(osv.AbstractModel):
    _name = 'calendar.alarm_manager'

    def get_next_potential_limit_alarm(self, cr, uid, seconds, notif=True, mail=True, partner_id=None, context=None):
        res = {}
        base_request = "\n                    SELECT\n                        cal.id,\n                        cal.start - interval '1' minute  * calcul_delta.max_delta AS first_alarm,\n                        CASE\n                            WHEN cal.recurrency THEN cal.final_date - interval '1' minute  * calcul_delta.min_delta\n                            ELSE cal.stop - interval '1' minute  * calcul_delta.min_delta\n                        END as last_alarm,\n                        cal.start as first_event_date,\n                        CASE\n                            WHEN cal.recurrency THEN cal.final_date\n                            ELSE cal.stop\n                        END as last_event_date,\n                        calcul_delta.min_delta,\n                        calcul_delta.max_delta,\n                        cal.rrule AS rule\n                    FROM\n                        calendar_event AS cal\n                        RIGHT JOIN\n                            (\n                                SELECT\n                                    rel.calendar_event_id, max(alarm.duration_minutes) AS max_delta,min(alarm.duration_minutes) AS min_delta\n                                FROM\n                                    calendar_alarm_calendar_event_rel AS rel\n                                        LEFT JOIN calendar_alarm AS alarm ON alarm.id = rel.calendar_alarm_id\n                                WHERE alarm.type in %s\n                                GROUP BY rel.calendar_event_id\n                            ) AS calcul_delta ON calcul_delta.calendar_event_id = cal.id\n             "
        filter_user = '\n                RIGHT JOIN calendar_event_res_partner_rel AS part_rel ON part_rel.calendar_event_id = cal.id\n                    AND part_rel.res_partner_id = %s\n        '
        type_to_read = ()
        if notif:
            type_to_read += ('notification',)
        if mail:
            type_to_read += ('email',)
        tuple_params = (type_to_read,)
        if partner_id:
            base_request += filter_user
            tuple_params += (partner_id,)
        tuple_params += (seconds,)
        cr.execute("SELECT *\n                        FROM ( %s WHERE cal.active = True ) AS ALL_EVENTS\n                       WHERE ALL_EVENTS.first_alarm < (now() at time zone 'utc' + interval '%%s' second )\n                         AND ALL_EVENTS.last_event_date > (now() at time zone 'utc')\n                   " % base_request, tuple_params)
        for (event_id, first_alarm, last_alarm, first_meeting, last_meeting, min_duration, max_duration, rule) in cr.fetchall():
            res[event_id] = {'event_id': event_id, 'first_alarm': first_alarm, 'last_alarm': last_alarm, 'first_meeting': first_meeting, 'last_meeting': last_meeting, 'min_duration': min_duration, 'max_duration': max_duration, 'rrule': rule}
        return res

    def do_check_alarm_for_one_date(self, cr, uid, one_date, event, event_maxdelta, in_the_next_X_seconds, after=False, notif=True, mail=True, missing=False, context=None):
        res = []
        alarm_type = []
        if notif:
            alarm_type.append('notification')
        if mail:
            alarm_type.append('email')
        if one_date - timedelta(minutes=missing and 0 or event_maxdelta) < datetime.now() + timedelta(seconds=in_the_next_X_seconds):
            for alarm in event.alarm_ids:
                if alarm.type in alarm_type and one_date - timedelta(minutes=missing and 0 or alarm.duration_minutes) < datetime.now() + timedelta(seconds=in_the_next_X_seconds) and (not after or one_date - timedelta(minutes=alarm.duration_minutes) > openerp.fields.Datetime.from_string(after)):
                    alert = {'alarm_id': alarm.id, 'event_id': event.id, 'notify_at': one_date - timedelta(minutes=alarm.duration_minutes)}
                    res.append(alert)
        return res

    def get_next_mail(self, cr, uid, context=None):
        now = openerp.fields.Datetime.to_string(datetime.now())
        icp = self.pool['ir.config_parameter']
        last_notif_mail = icp.get_param(cr, SUPERUSER_ID, 'calendar.last_notif_mail', default=False) or now
        try:
            cron = self.pool['ir.model.data'].get_object(cr, uid, 'calendar', 'ir_cron_scheduler_alarm', context=context)
        except ValueError:
            _logger.error('Cron for ' + self._name + ' can not be identified !')
            return False
        interval_to_second = {'weeks': 7 * 24 * 60 * 60, 'days': 24 * 60 * 60, 'hours': 60 * 60, 'minutes': 60, 'seconds': 1}
        if cron.interval_type not in interval_to_second.keys():
            _logger.error('Cron delay can not be computed !')
            return False
        cron_interval = cron.interval_number * interval_to_second[cron.interval_type]
        all_events = self.get_next_potential_limit_alarm(cr, uid, cron_interval, notif=False, context=context)
        for curEvent in self.pool.get('calendar.event').browse(cr, uid, all_events.keys(), context=context):
            max_delta = all_events[curEvent.id]['max_duration']
            if curEvent.recurrency:
                at_least_one = False
                last_found = False
                for one_date in self.pool.get('calendar.event').get_recurrent_date_by_event(cr, uid, curEvent, context=context):
                    in_date_format = one_date.replace(tzinfo=None)
                    last_found = self.do_check_alarm_for_one_date(cr, uid, in_date_format, curEvent, max_delta, 0, after=last_notif_mail, notif=False, missing=True, context=context)
                    for alert in last_found:
                        self.do_mail_reminder(cr, uid, alert, context=context)
                        at_least_one = True
                    if at_least_one and (not last_found):
                        break
            else:
                in_date_format = datetime.strptime(curEvent.start, DEFAULT_SERVER_DATETIME_FORMAT)
                last_found = self.do_check_alarm_for_one_date(cr, uid, in_date_format, curEvent, max_delta, 0, after=last_notif_mail, notif=False, missing=True, context=context)
                for alert in last_found:
                    self.do_mail_reminder(cr, uid, alert, context=context)
        icp.set_param(cr, SUPERUSER_ID, 'calendar.last_notif_mail', now)

    def get_next_notif(self, cr, uid, context=None):
        ajax_check_every_seconds = 300
        partner = self.pool['res.users'].read(cr, SUPERUSER_ID, uid, ['partner_id', 'calendar_last_notif_ack'], context=context)
        all_notif = []
        if not partner:
            return []
        all_events = self.get_next_potential_limit_alarm(cr, uid, ajax_check_every_seconds, partner_id=partner['partner_id'][0], mail=False, context=context)
        for event in all_events:
            max_delta = all_events[event]['max_duration']
            curEvent = self.pool.get('calendar.event').browse(cr, uid, event, context=context)
            if curEvent.recurrency:
                bFound = False
                LastFound = False
                for one_date in self.pool.get('calendar.event').get_recurrent_date_by_event(cr, uid, curEvent, context=context):
                    in_date_format = one_date.replace(tzinfo=None)
                    LastFound = self.do_check_alarm_for_one_date(cr, uid, in_date_format, curEvent, max_delta, ajax_check_every_seconds, after=partner['calendar_last_notif_ack'], mail=False, context=context)
                    if LastFound:
                        for alert in LastFound:
                            all_notif.append(self.do_notif_reminder(cr, uid, alert, context=context))
                        if not bFound:
                            bFound = True
                    if bFound and (not LastFound):
                        break
            else:
                in_date_format = datetime.strptime(curEvent.start, DEFAULT_SERVER_DATETIME_FORMAT)
                LastFound = self.do_check_alarm_for_one_date(cr, uid, in_date_format, curEvent, max_delta, ajax_check_every_seconds, after=partner['calendar_last_notif_ack'], mail=False, context=context)
                if LastFound:
                    for alert in LastFound:
                        all_notif.append(self.do_notif_reminder(cr, uid, alert, context=context))
        return all_notif

    def do_mail_reminder(self, cr, uid, alert, context=None):
        if context is None:
            context = {}
        res = False
        event = self.pool['calendar.event'].browse(cr, uid, alert['event_id'], context=context)
        alarm = self.pool['calendar.alarm'].browse(cr, uid, alert['alarm_id'], context=context)
        if alarm.type == 'email':
            res = self.pool['calendar.attendee']._send_mail_to_attendees(cr, uid, [att.id for att in event.attendee_ids], email_from=event.user_id.partner_id.email, template_xmlid='calendar_template_meeting_reminder', force=True, context=context)
        return res

    def do_notif_reminder(self, cr, uid, alert, context=None):
        alarm = self.pool['calendar.alarm'].browse(cr, uid, alert['alarm_id'], context=context)
        event = self.pool['calendar.event'].browse(cr, uid, alert['event_id'], context=context)
        if alarm.type == 'notification':
            message = event.display_time
            delta = alert['notify_at'] - datetime.now()
            delta = delta.seconds + delta.days * 3600 * 24
            return {'event_id': event.id, 'title': event.name, 'message': message, 'timer': delta, 'notify_at': alert['notify_at'].strftime(DEFAULT_SERVER_DATETIME_FORMAT)}

