class FunctionTests(SimpleTestCase):

    def test_truncate(self):
        uri = 'http://31characteruri.com/test/'
        self.assertEqual(len(uri), 31)
        self.assertEqual(urlizetrunc(uri, 31), '<a href="http://31characteruri.com/test/" rel="nofollow">http://31characteruri.com/test/</a>')
        self.assertEqual(urlizetrunc(uri, 30), '<a href="http://31characteruri.com/test/" rel="nofollow">http://31characteruri.com/t...</a>')
        self.assertEqual(urlizetrunc(uri, 2), '<a href="http://31characteruri.com/test/" rel="nofollow">...</a>')

    def test_overtruncate(self):
        self.assertEqual(urlizetrunc('http://short.com/', 20), '<a href="http://short.com/" rel="nofollow">http://short.com/</a>')

    def test_query_string(self):
        self.assertEqual(urlizetrunc('http://www.google.co.uk/search?hl=en&q=some+long+url&btnG=Search&meta=', 20), '<a href="http://www.google.co.uk/search?hl=en&amp;q=some+long+url&amp;btnG=Search&amp;meta=" rel="nofollow">http://www.google...</a>')

    def test_non_string_input(self):
        self.assertEqual(urlizetrunc(123, 1), '123')

    def test_autoescape(self):
        self.assertEqual(urlizetrunc('foo<a href=" google.com ">bar</a>buz', 10), 'foo&lt;a href=&quot; <a href="http://google.com" rel="nofollow">google.com</a> &quot;&gt;bar&lt;/a&gt;buz')

    def test_autoescape_off(self):
        self.assertEqual(urlizetrunc('foo<a href=" google.com ">bar</a>buz', 9, autoescape=False), 'foo<a href=" <a href="http://google.com" rel="nofollow">google...</a> ">bar</a>buz')

