    config = get_config(module)
    return {'hostname': parse_hostname(config), 'domain_name': parse_domain_name(config), 'domain_list': re.findall('^ip domain-list (\\S+)', config, re.M), 'lookup_source': parse_lookup_source(config), 'name_servers': parse_name_servers(config)}

def map_params_to_obj(module):
    obj = {'hostname': module.params['hostname'], 'domain_name': module.params['domain_name'], 'domain_list': module.params['domain_list']}
    lookup_source = ComplexList(dict(interface=dict(key=True), vrf=dict()), module)
