    for (arg, cast) in [('lookup_source', lookup_source), ('name_servers', name_servers)]:
        if module.params[arg] is not None:
            obj[arg] = cast(module.params[arg])
        else:
            obj[arg] = None
    return obj

def main():
    """ main entry point for module execution
    """
    argument_spec = dict(hostname=dict(), domain_name=dict(), domain_list=dict(type='list', aliases=['domain_search']), lookup_source=dict(type='list'), name_servers=dict(type='list'), state=dict(default='present', choices=['present', 'absent']))
    argument_spec.update(eos_argument_spec)
    module = AnsibleModule(argument_spec=argument_spec, supports_check_mode=True)
    result = {'changed': False}
    want = map_params_to_obj(module)
    have = map_config_to_obj(module)
