from django.forms import models as model_forms
from django.core.exceptions import ImproperlyConfigured
from django.http import HttpResponseRedirect
from django.views.generic.base import TemplateResponseMixin, View
from django.views.generic.detail import SingleObjectMixin, SingleObjectTemplateResponseMixin, BaseDetailView

class FormMixin(object):
    """
    A mixin that provides a way to show and handle a form in a request.
    """
    initial = {}
    form_class = None
    success_url = None

    def get_initial(self):
        """
        Returns the initial data to use for forms on this view.
        """
        return self.initial

    def get_form_class(self):
        """
        Returns the form class to use in this view
        """
        return self.form_class

    def get_form(self, form_class):
        """
        Returns an instance of the form to be used in this view.
        """
        return form_class(**self.get_form_kwargs())

    def get_form_kwargs(self):
        """
        Returns the keyword arguments for instanciating the form.
        """
        kwargs = {'initial': self.get_initial()}
        if self.request.method in ('POST', 'PUT'):
            kwargs.update({'data': self.request.POST, 'files': self.request.FILES})
        return kwargs

    def get_context_data(self, **kwargs):
        return kwargs

    def get_success_url(self):
        if self.success_url:
            url = self.success_url
        else:
            raise ImproperlyConfigured('No URL to redirect to. Provide a success_url.')
        return url

    def form_valid(self, form):
        return HttpResponseRedirect(self.get_success_url())

    def form_invalid(self, form):
        return self.render_to_response(self.get_context_data(form=form))

class ModelFormMixin(FormMixin, SingleObjectMixin):
    """
    A mixin that provides a way to show and handle a modelform in a request.
    """

    def get_form_class(self):
        """
        Returns the form class to use in this view
        """
        if self.form_class:
            return self.form_class
        else:
            if self.model is not None:
                model = self.model
            elif hasattr(self, 'object') and self.object is not None:
                model = self.object.__class__
            else:
                model = self.get_queryset().model
            return model_forms.modelform_factory(model)

    def get_form_kwargs(self):
        """
        Returns the keyword arguments for instanciating the form.
        """
        kwargs = super(ModelFormMixin, self).get_form_kwargs()
        kwargs.update({'instance': self.object})
        return kwargs

    def get_success_url(self):
        if self.success_url:
            url = self.success_url % self.object.__dict__
        else:
            try:
                url = self.object.get_absolute_url()
            except AttributeError:
                raise ImproperlyConfigured('No URL to redirect to.  Either provide a url or define a get_absolute_url method on the Model.')
        return url

    def form_valid(self, form):
        self.object = form.save()
        return super(ModelFormMixin, self).form_valid(form)

    def get_context_data(self, **kwargs):
        context = kwargs
        if self.object:
            context['object'] = self.object
            context_object_name = self.get_context_object_name(self.object)
            if context_object_name:
                context[context_object_name] = self.object
        return context

class ProcessFormView(View):
    """
    A mixin that processes a form on POST.
    """

    def get(self, request, *args, **kwargs):
        form_class = self.get_form_class()
        form = self.get_form(form_class)
        return self.render_to_response(self.get_context_data(form=form))

    def post(self, request, *args, **kwargs):
        form_class = self.get_form_class()
        form = self.get_form(form_class)
        if form.is_valid():
            return self.form_valid(form)
        else:
            return self.form_invalid(form)

    def put(self, *args, **kwargs):
        return self.post(*args, **kwargs)

class BaseFormView(FormMixin, ProcessFormView):
    """
    A base view for displaying a form
    """

class FormView(TemplateResponseMixin, BaseFormView):
    """
    A view for displaying a form, and rendering a template response.
    """

class BaseCreateView(ModelFormMixin, ProcessFormView):
    """
    Base view for creating an new object instance.

    Using this base class requires subclassing to provide a response mixin.
    """

    def get(self, request, *args, **kwargs):
        self.object = None
        return super(BaseCreateView, self).get(request, *args, **kwargs)

    def post(self, request, *args, **kwargs):
        self.object = None
        return super(BaseCreateView, self).post(request, *args, **kwargs)

class CreateView(SingleObjectTemplateResponseMixin, BaseCreateView):
    """
    View for creating an new object instance,
    with a response rendered by template.
    """
    template_name_suffix = '_form'

class BaseUpdateView(ModelFormMixin, ProcessFormView):
    """
    Base view for updating an existing object.

    Using this base class requires subclassing to provide a response mixin.
    """

    def get(self, request, *args, **kwargs):
        self.object = self.get_object()
        return super(BaseUpdateView, self).get(request, *args, **kwargs)

    def post(self, request, *args, **kwargs):
        self.object = self.get_object()
        return super(BaseUpdateView, self).post(request, *args, **kwargs)

class UpdateView(SingleObjectTemplateResponseMixin, BaseUpdateView):
    """
    View for updating an object,
    with a response rendered by template..
    """
    template_name_suffix = '_form'

class DeletionMixin(object):
    """
    A mixin providing the ability to delete objects
    """
    success_url = None

    def delete(self, request, *args, **kwargs):
        self.object = self.get_object()
        self.object.delete()
        return HttpResponseRedirect(self.get_success_url())

    def post(self, *args, **kwargs):
        return self.delete(*args, **kwargs)

    def get_success_url(self):
        if self.success_url:
            return self.success_url
        else:
            raise ImproperlyConfigured('No URL to redirect to. Provide a success_url.')

class BaseDeleteView(DeletionMixin, BaseDetailView):
    """
    Base view for deleting an object.

    Using this base class requires subclassing to provide a response mixin.
    """

class DeleteView(SingleObjectTemplateResponseMixin, BaseDeleteView):
    """
    View for deleting an object retrieved with `self.get_object()`,
    with a response rendered by template.
    """
    template_name_suffix = '_confirm_delete'

import collections
import threading
import grpc
from grpc import _common
from grpc._cython import cygrpc

class AuthMetadataContext(collections.namedtuple('AuthMetadataContext', ('service_url', 'method_name')), grpc.AuthMetadataContext):
    pass

class AuthMetadataPluginCallback(grpc.AuthMetadataContext):

    def __init__(self, callback):
        self._callback = callback

    def __call__(self, metadata, error):
        self._callback(metadata, error)

class _WrappedCygrpcCallback(object):

    def __init__(self, cygrpc_callback):
        self.is_called = False
        self.error = None
        self.is_called_lock = threading.Lock()
        self.cygrpc_callback = cygrpc_callback

    def _invoke_failure(self, error):
        self.cygrpc_callback(_common.EMPTY_METADATA, cygrpc.StatusCode.internal, _common.encode(str(error)))

    def _invoke_success(self, metadata):
        try:
            cygrpc_metadata = _common.to_cygrpc_metadata(metadata)
        except Exception as exception:
            self._invoke_failure(exception)
            return
        self.cygrpc_callback(cygrpc_metadata, cygrpc.StatusCode.ok, b'')

    def __call__(self, metadata, error):
        with self.is_called_lock:
            if self.is_called:
                raise RuntimeError('callback should only ever be invoked once')
            if self.error:
                self._invoke_failure(self.error)
                return
            self.is_called = True
        if error is None:
            self._invoke_success(metadata)
        else:
            self._invoke_failure(error)

    def notify_failure(self, error):
        with self.is_called_lock:
            if not self.is_called:
                self.error = error

class _WrappedPlugin(object):

    def __init__(self, plugin):
        self.plugin = plugin

    def __call__(self, context, cygrpc_callback):
        wrapped_cygrpc_callback = _WrappedCygrpcCallback(cygrpc_callback)
        wrapped_context = AuthMetadataContext(_common.decode(context.service_url), _common.decode(context.method_name))
        try:
            self.plugin(wrapped_context, AuthMetadataPluginCallback(wrapped_cygrpc_callback))
        except Exception as error:
            wrapped_cygrpc_callback.notify_failure(error)
            raise

def call_credentials_metadata_plugin(plugin, name):
    """
  Args:
    plugin: A callable accepting a grpc.AuthMetadataContext
      object and a callback (itself accepting a list of metadata key/value
      2-tuples and a None-able exception value). The callback must be eventually
      called, but need not be called in plugin's invocation.
      plugin's invocation must be non-blocking.
  """
    return cygrpc.call_credentials_metadata_plugin(cygrpc.CredentialsMetadataPlugin(_WrappedPlugin(plugin), _common.encode(name)))

from __future__ import unicode_literals
from django.apps import apps
from django.core import checks
from django.core.checks.registry import registry
from django.core.management.base import BaseCommand, CommandError

class Command(BaseCommand):
    help = 'Checks the entire Django project for potential problems.'
    requires_system_checks = False

    def add_arguments(self, parser):
        parser.add_argument('args', metavar='app_label', nargs='*')
        parser.add_argument('--tag', '-t', action='append', dest='tags', help='Run only checks labeled with given tag.')
        parser.add_argument('--list-tags', action='store_true', dest='list_tags', help='List available tags.')
        parser.add_argument('--deploy', action='store_true', dest='deploy', help='Check deployment settings.')

    def handle(self, *app_labels, **options):
        include_deployment_checks = options['deploy']
        if options.get('list_tags'):
            self.stdout.write('\n'.join(sorted(registry.tags_available(include_deployment_checks))))
            return
        if app_labels:
            app_configs = [apps.get_app_config(app_label) for app_label in app_labels]
        else:
            app_configs = None
        tags = options.get('tags')
        if tags:
            try:
                invalid_tag = next((tag for tag in tags if not checks.tag_exists(tag, include_deployment_checks)))
            except StopIteration:
                pass
            else:
                raise CommandError('There is no system check with the "%s" tag.' % invalid_tag)
        self.check(app_configs=app_configs, tags=tags, display_num_errors=True, include_deployment_checks=include_deployment_checks)

import datetime
from email.utils import formatdate
import time
from django.conf import settings
from django.core.exceptions import MiddlewareNotUsed
from django_statsd.middleware import GraphiteRequestTimingMiddleware

class CacheMiddleware(object):

    def process_response(self, request, response):
        cache = request.method != 'POST' and response.status_code != 404 and ('Cache-Control' not in response)
        if cache:
            d = datetime.datetime.now() + datetime.timedelta(minutes=10)
            stamp = time.mktime(d.timetuple())
            response['Cache-Control'] = 'max-age=600'
            response['Expires'] = formatdate(timeval=stamp, localtime=False, usegmt=True)
        return response

class MozorgRequestTimingMiddleware(GraphiteRequestTimingMiddleware):

    def process_view(self, request, view, view_args, view_kwargs):
        if hasattr(view, 'page_name'):
            request._view_module = 'page'
            request._view_name = view.page_name.replace('/', '.')
            request._start_time = time.time()
        else:
            f = super(MozorgRequestTimingMiddleware, self)
            f.process_view(request, view, view_args, view_kwargs)

class ClacksOverheadMiddleware(object):

    @staticmethod
    def process_response(request, response):
        if response.status_code == 200:
            response['X-Clacks-Overhead'] = 'GNU Terry Pratchett'
        return response

class HostnameMiddleware(object):

    def __init__(self):
        if not settings.ENABLE_HOSTNAME_MIDDLEWARE:
            raise MiddlewareNotUsed
        values = [getattr(settings, x) for x in ['HOSTNAME', 'DEIS_APP', 'DEIS_DOMAIN']]
        self.backend_server = '.'.join((x for x in values if x))

    def process_response(self, request, response):
        response['X-Backend-Server'] = self.backend_server
        return response

class VaryNoCacheMiddleware(object):

    def __init__(self):
        if not settings.ENABLE_VARY_NOCACHE_MIDDLEWARE:
            raise MiddlewareNotUsed

    @staticmethod
    def process_response(request, response):
        if 'vary' in response:
            path = request.path
            if path != '/' and (not any((path.startswith(x) for x in settings.VARY_NOCACHE_EXEMPT_URL_PREFIXES))):
                del response['vary']
                del response['expires']
                response['Cache-Control'] = 'max-age=0'
        return response

