def _classify_point(re, im):
    """Return the half-axis (or origin) on which (re, im) point is located. """
    if not re and (not im):
        return OO
    if not re:
        if im > 0:
            return A2
        else:
            return A4
    elif not im:
        if re > 0:
            return A1
        else:
            return A3

def _intervals_to_quadrants(intervals, f1, f2, s, t, F):
    """Generate a sequence of extended quadrants from a list of critical points. """
    if not intervals:
        return []
    Q = []
    if not f1:
        ((a, b), _, _) = intervals[0]
        if a == b == s:
            if len(intervals) == 1:
                if dup_eval(f2, t, F) > 0:
                    return [OO, A2]
                else:
                    return [OO, A4]
            else:
                ((a, _), _, _) = intervals[1]
                if dup_eval(f2, (s + a) / 2, F) > 0:
                    Q.extend([OO, A2])
                    f2_sgn = +1
                else:
                    Q.extend([OO, A4])
                    f2_sgn = -1
                intervals = intervals[1:]
        elif dup_eval(f2, s, F) > 0:
            Q.append(A2)
            f2_sgn = +1
        else:
            Q.append(A4)
            f2_sgn = -1
        for ((a, _), indices, _) in intervals:
            Q.append(OO)
            if indices[1] % 2 == 1:
                f2_sgn = -f2_sgn
            if a != t:
                if f2_sgn > 0:
                    Q.append(A2)
                else:
                    Q.append(A4)
        return Q
    if not f2:
        ((a, b), _, _) = intervals[0]
        if a == b == s:
            if len(intervals) == 1:
                if dup_eval(f1, t, F) > 0:
                    return [OO, A1]
                else:
                    return [OO, A3]
            else:
                ((a, _), _, _) = intervals[1]
                if dup_eval(f1, (s + a) / 2, F) > 0:
                    Q.extend([OO, A1])
                    f1_sgn = +1
                else:
                    Q.extend([OO, A3])
                    f1_sgn = -1
                intervals = intervals[1:]
        elif dup_eval(f1, s, F) > 0:
            Q.append(A1)
            f1_sgn = +1
        else:
            Q.append(A3)
            f1_sgn = -1
        for ((a, _), indices, _) in intervals:
            Q.append(OO)
            if indices[0] % 2 == 1:
                f1_sgn = -f1_sgn
            if a != t:
                if f1_sgn > 0:
                    Q.append(A1)
                else:
                    Q.append(A3)
        return Q
    re = dup_eval(f1, s, F)
    im = dup_eval(f2, s, F)
    if not re or not im:
        Q.append(_classify_point(re, im))
        if len(intervals) == 1:
            re = dup_eval(f1, t, F)
            im = dup_eval(f2, t, F)
        else:
            ((a, _), _, _) = intervals[1]
            re = dup_eval(f1, (s + a) / 2, F)
            im = dup_eval(f2, (s + a) / 2, F)
        intervals = intervals[1:]
    if re > 0:
        f1_sgn = +1
    else:
        f1_sgn = -1
    if im > 0:
        f2_sgn = +1
    else:
        f2_sgn = -1
    sgn = {(+1, +1): Q1, (-1, +1): Q2, (-1, -1): Q3, (+1, -1): Q4}
    Q.append(sgn[f1_sgn, f2_sgn])
    for ((a, b), indices, _) in intervals:
        if a == b:
            re = dup_eval(f1, a, F)
            im = dup_eval(f2, a, F)
            cls = _classify_point(re, im)
            if cls is not None:
                Q.append(cls)
        if 0 in indices:
            if indices[0] % 2 == 1:
                f1_sgn = -f1_sgn
        if 1 in indices:
            if indices[1] % 2 == 1:
                f2_sgn = -f2_sgn
        if not (a == b and b == t):
            Q.append(sgn[f1_sgn, f2_sgn])
    return Q

def _traverse_quadrants(Q_L1, Q_L2, Q_L3, Q_L4, exclude=None):
    """Transform sequences of quadrants to a sequence of rules. """
    if exclude is True:
        edges = [1, 1, 0, 0]
        corners = {(0, 1): 1, (1, 2): 1, (2, 3): 0, (3, 0): 1}
    else:
        edges = [0, 0, 0, 0]
        corners = {(0, 1): 0, (1, 2): 0, (2, 3): 0, (3, 0): 0}
    if exclude is not None and exclude is not True:
        exclude = set(exclude)
        for (i, edge) in enumerate(['S', 'E', 'N', 'W']):
            if edge in exclude:
                edges[i] = 1
        for (i, corner) in enumerate(['SW', 'SE', 'NE', 'NW']):
            if corner in exclude:
                corners[(i - 1) % 4, i] = 1
    (QQ, rules) = ([Q_L1, Q_L2, Q_L3, Q_L4], [])
    for (i, Q) in enumerate(QQ):
        if not Q:
            continue
        if Q[-1] == OO:
            Q = Q[:-1]
        if Q[0] == OO:
            (j, Q) = ((i - 1) % 4, Q[1:])
            qq = (QQ[j][-2], OO, Q[0])
            if qq in _rules_ambiguous:
                rules.append((_rules_ambiguous[qq], corners[j, i]))
            else:
                raise NotImplementedError('3 element rule (corner): ' + str(qq))
        (q1, k) = (Q[0], 1)
        while k < len(Q):
            (q2, k) = (Q[k], k + 1)
            if q2 != OO:
                qq = (q1, q2)
                if qq in _rules_simple:
                    rules.append((_rules_simple[qq], 0))
                elif qq in _rules_ambiguous:
                    rules.append((_rules_ambiguous[qq], edges[i]))
                else:
                    raise NotImplementedError('2 element rule (inside): ' + str(qq))
            else:
                (qq, k) = ((q1, q2, Q[k]), k + 1)
                if qq in _rules_ambiguous:
                    rules.append((_rules_ambiguous[qq], edges[i]))
                else:
                    raise NotImplementedError('3 element rule (edge): ' + str(qq))
            q1 = qq[-1]
    return rules

def _reverse_intervals(intervals):
    """Reverse intervals for traversal from right to left and from top to bottom. """
    return [((b, a), indices, f) for ((a, b), indices, f) in reversed(intervals)]

def _winding_number(T, field):
    """Compute the winding number of the input polynomial, i.e. the number of roots. """
    return int(sum([field(*_values[t][i]) for (t, i) in T]) / field(2))

