def _enquote_executable(executable):
    if ' ' in executable:
        if executable.startswith('/usr/bin/env '):
            (env, _executable) = executable.split(' ', 1)
            if ' ' in _executable and (not _executable.startswith('"')):
                executable = '%s "%s"' % (env, _executable)
        elif not executable.startswith('"'):
            executable = '"%s"' % executable
    return executable

class ScriptMaker(object):
    """
    A class to copy or create scripts from source scripts or callable
    specifications.
    """
    script_template = SCRIPT_TEMPLATE
    executable = None

    def __init__(self, source_dir, target_dir, add_launchers=True, dry_run=False, fileop=None):
        self.source_dir = source_dir
        self.target_dir = target_dir
        self.add_launchers = add_launchers
        self.force = False
        self.clobber = False
        self.set_mode = os.name == 'posix' or (os.name == 'java' and os._name == 'posix')
        self.variants = set(('', 'X.Y'))
        self._fileop = fileop or FileOperator(dry_run)
        self._is_nt = os.name == 'nt' or (os.name == 'java' and os._name == 'nt')

    def _get_alternate_executable(self, executable, options):
        if options.get('gui', False) and self._is_nt:
            (dn, fn) = os.path.split(executable)
            fn = fn.replace('python', 'pythonw')
            executable = os.path.join(dn, fn)
        return executable
    if sys.platform.startswith('java'):

        def _is_shell(self, executable):
            """
            Determine if the specified executable is a script
            (contains a #! line)
            """
            try:
                with open(executable) as fp:
                    return fp.read(2) == '#!'
            except (OSError, IOError):
                logger.warning('Failed to open %s', executable)
                return False

        def _fix_jython_executable(self, executable):
            if self._is_shell(executable):
                import java
                if java.lang.System.getProperty('os.name') == 'Linux':
                    return executable
            elif executable.lower().endswith('jython.exe'):
                return executable
            return '/usr/bin/env %s' % executable

    def _build_shebang(self, executable, post_interp):
        """
        Build a shebang line. In the simple case (on Windows, or a shebang line
        which is not too long or contains spaces) use a simple formulation for
        the shebang. Otherwise, use /bin/sh as the executable, with a contrived
        shebang which allows the script to run either under Python or sh, using
        suitable quoting. Thanks to Harald Nordgren for his input.

        See also: http://www.in-ulm.de/~mascheck/various/shebang/#length
                  https://hg.mozilla.org/mozilla-central/file/tip/mach
        """
        if os.name != 'posix':
            simple_shebang = True
        else:
            shebang_length = len(executable) + len(post_interp) + 3
            if sys.platform == 'darwin':
                max_shebang_length = 512
            else:
                max_shebang_length = 127
            simple_shebang = b' ' not in executable and shebang_length <= max_shebang_length
        if simple_shebang:
            result = b'#!' + executable + post_interp + b'\n'
        else:
            result = b'#!/bin/sh\n'
            result += b"'''exec' " + executable + post_interp + b' "$0" "$@"\n'
            result += b"' '''"
        return result

    def _get_shebang(self, encoding, post_interp=b'', options=None):
        enquote = True
        if self.executable:
            executable = self.executable
            enquote = False
        elif not sysconfig.is_python_build():
            executable = get_executable()
        elif in_venv():
            executable = os.path.join(sysconfig.get_path('scripts'), 'python%s' % sysconfig.get_config_var('EXE'))
        else:
            executable = os.path.join(sysconfig.get_config_var('BINDIR'), 'python%s%s' % (sysconfig.get_config_var('VERSION'), sysconfig.get_config_var('EXE')))
        if options:
            executable = self._get_alternate_executable(executable, options)
        if sys.platform.startswith('java'):
            executable = self._fix_jython_executable(executable)
        if enquote:
            executable = _enquote_executable(executable)
        executable = executable.encode('utf-8')
        if sys.platform == 'cli' and '-X:Frames' not in post_interp and ('-X:FullFrames' not in post_interp):
            post_interp += b' -X:Frames'
        shebang = self._build_shebang(executable, post_interp)
        try:
            shebang.decode('utf-8')
        except UnicodeDecodeError:
            raise ValueError('The shebang (%r) is not decodable from utf-8' % shebang)
        if encoding != 'utf-8':
            try:
                shebang.decode(encoding)
            except UnicodeDecodeError:
                raise ValueError('The shebang (%r) is not decodable from the script encoding (%r)' % (shebang, encoding))
        return shebang

    def _get_script_text(self, entry):
        return self.script_template % dict(module=entry.prefix, import_name=entry.suffix.split('.')[0], func=entry.suffix)
    manifest = _DEFAULT_MANIFEST

    def get_manifest(self, exename):
        base = os.path.basename(exename)
        return self.manifest % base

    def _write_script(self, names, shebang, script_bytes, filenames, ext):
        use_launcher = self.add_launchers and self._is_nt
        linesep = os.linesep.encode('utf-8')
        if not shebang.endswith(linesep):
            shebang += linesep
        if not use_launcher:
            script_bytes = shebang + script_bytes
        else:
            if ext == 'py':
                launcher = self._get_launcher('t')
            else:
                launcher = self._get_launcher('w')
            stream = BytesIO()
            with ZipFile(stream, 'w') as zf:
                zf.writestr('__main__.py', script_bytes)
            zip_data = stream.getvalue()
            script_bytes = launcher + shebang + zip_data
        for name in names:
            outname = os.path.join(self.target_dir, name)
            if use_launcher:
                (n, e) = os.path.splitext(outname)
                if e.startswith('.py'):
                    outname = n
                outname = '%s.exe' % outname
                try:
                    self._fileop.write_binary_file(outname, script_bytes)
                except Exception:
                    logger.warning('Failed to write executable - trying to use .deleteme logic')
                    dfname = '%s.deleteme' % outname
                    if os.path.exists(dfname):
                        os.remove(dfname)
                    os.rename(outname, dfname)
                    self._fileop.write_binary_file(outname, script_bytes)
                    logger.debug('Able to replace executable using .deleteme logic')
                    try:
                        os.remove(dfname)
                    except Exception:
                        pass
            else:
                if self._is_nt and (not outname.endswith('.' + ext)):
                    outname = '%s.%s' % (outname, ext)
                if os.path.exists(outname) and (not self.clobber):
                    logger.warning('Skipping existing file %s', outname)
                    continue
                self._fileop.write_binary_file(outname, script_bytes)
                if self.set_mode:
                    self._fileop.set_executable_mode([outname])
            filenames.append(outname)

    def _make_script(self, entry, filenames, options=None):
        post_interp = b''
        if options:
            args = options.get('interpreter_args', [])
            if args:
                args = ' %s' % ' '.join(args)
                post_interp = args.encode('utf-8')
        shebang = self._get_shebang('utf-8', post_interp, options=options)
        script = self._get_script_text(entry).encode('utf-8')
        name = entry.name
        scriptnames = set()
        if '' in self.variants:
            scriptnames.add(name)
        if 'X' in self.variants:
            scriptnames.add('%s%s' % (name, sys.version_info[0]))
        if 'X.Y' in self.variants:
            scriptnames.add('%s-%s.%s' % (name, sys.version_info[0], sys.version_info[1]))
        if options and options.get('gui', False):
            ext = 'pyw'
        else:
            ext = 'py'
        self._write_script(scriptnames, shebang, script, filenames, ext)

    def _copy_script(self, script, filenames):
        adjust = False
        script = os.path.join(self.source_dir, convert_path(script))
        outname = os.path.join(self.target_dir, os.path.basename(script))
        if not self.force and (not self._fileop.newer(script, outname)):
            logger.debug('not copying %s (up-to-date)', script)
            return
        try:
            f = open(script, 'rb')
        except IOError:
            if not self.dry_run:
                raise
            f = None
        else:
            first_line = f.readline()
            if not first_line:
                logger.warning('%s: %s is an empty file (skipping)', self.get_command_name(), script)
                return
            match = FIRST_LINE_RE.match(first_line.replace(b'\r\n', b'\n'))
            if match:
                adjust = True
                post_interp = match.group(1) or b''
        if not adjust:
            if f:
                f.close()
            self._fileop.copy_file(script, outname)
            if self.set_mode:
                self._fileop.set_executable_mode([outname])
            filenames.append(outname)
        else:
            logger.info('copying and adjusting %s -> %s', script, self.target_dir)
            if not self._fileop.dry_run:
                (encoding, lines) = detect_encoding(f.readline)
                f.seek(0)
                shebang = self._get_shebang(encoding, post_interp)
                if b'pythonw' in first_line:
                    ext = 'pyw'
                else:
                    ext = 'py'
                n = os.path.basename(outname)
                self._write_script([n], shebang, f.read(), filenames, ext)
            if f:
                f.close()

    @property
    def dry_run(self):
        return self._fileop.dry_run

    @dry_run.setter
    def dry_run(self, value):
        self._fileop.dry_run = value
    if os.name == 'nt' or (os.name == 'java' and os._name == 'nt'):

        def _get_launcher(self, kind):
            if struct.calcsize('P') == 8:
                bits = '64'
            else:
                bits = '32'
            name = '%s%s.exe' % (kind, bits)
            distlib_package = __name__.rsplit('.', 1)[0]
            resource = finder(distlib_package).find(name)
            if not resource:
                msg = 'Unable to find resource %s in package %s' % (name, distlib_package)
                raise ValueError(msg)
            return resource.bytes

    def make(self, specification, options=None):
        """
        Make a script.

        :param specification: The specification, which is either a valid export
                              entry specification (to make a script from a
                              callable) or a filename (to make a script by
                              copying from a source location).
        :param options: A dictionary of options controlling script generation.
        :return: A list of all absolute pathnames written to.
        """
        filenames = []
        entry = get_export_entry(specification)
        if entry is None:
            self._copy_script(specification, filenames)
        else:
            self._make_script(entry, filenames, options=options)
        return filenames

    def make_multiple(self, specifications, options=None):
        """
        Take a list of specifications and make scripts from them,
        :param specifications: A list of specifications.
        :return: A list of all absolute pathnames written to,
        """
        filenames = []
        for specification in specifications:
            filenames.extend(self.make(specification, options))
        return filenames

from dopamine.adapters import Adapter
import numpy as np

class Explorer(Adapter):
    inConditions = {}
    outConditions = {}

    def __init__(self):
        Adapter.__init__(self)
        self.active = True

    def applyAction(self, action):
        """ apply transformations to action and return it. """
        if self.active:
            action = self._explore(action)
            self.experiment.agent.action = action
        return action

    def _explore(self, action):
        return action

class DecayExplorer(Explorer):
    finalFactor = 0.001

    def __init__(self, epsilon, episodeCount=None, actionCount=None):
        """ DecayExplorer is an explorer base class that has exploration decay, i.e.
            the amount of exploration weakens exponentially over time. epsilon is the
            initial parameter (can mean different things for different explorers), 
            which reduced over time. if episodeCount is given, epsilon reduces to 
            1/1000 of the initial value in the given number of episodes. if actionCount
            is given, epsilon reduces to 1/1000 of the initial value in the given 
            number of actions executed. actionCount takes priority if both values
            are given. In either case, after epsilon is 1/1000 of its initial value,
            exploration automatically deactivates.
        """
        Explorer.__init__(self)
        self.episodeCount = episodeCount
        self.actionCount = actionCount
        self.epsilon = epsilon
        self.initialEpsilon = epsilon
        if self.episodeCount:
            self.decay = np.power(self.finalFactor, 1.0 / self.episodeCount)
        if self.actionCount:
            self.decay = np.power(self.finalFactor, 1.0 / self.actionCount)
            self.episodeCount = None

    def resetExploration(self):
        self.epsilon = self.initialEpsilon

    def applyAction(self, action):
        action = Explorer.applyAction(self, action)
        if self.actionCount and self.active:
            self.epsilon *= self.decay
        if self.epsilon <= self.initialEpsilon * self.finalFactor:
            self.active = False
        return action

    def applyEpisodeFinished(self, episodeFinished):
        if episodeFinished and self.episodeCount and self.active:
            self.epsilon *= self.decay
        return episodeFinished

