from openerp.osv import osv

class pos_confirm(osv.osv_memory):
    _name = 'pos.confirm'
    _description = 'Post POS Journal Entries'

    def action_confirm(self, cr, uid, ids, context=None):
        order_obj = self.pool.get('pos.order')
        ids = order_obj.search(cr, uid, [('state', '=', 'paid')], context=context)
        for order in order_obj.browse(cr, uid, ids, context=context):
            todo = True
            for line in order.statement_ids:
                if line.statement_id.state != 'confirm':
                    todo = False
                    break
            if todo:
                order.signal_workflow('done')
        ids = order_obj.search(cr, uid, [('state', '=', 'invoiced'), ('invoice_id.state', '=', 'open')], context=context)
        for order in order_obj.browse(cr, uid, ids, context=context):
            invoice = order.invoice_id
            data_lines = [x.id for x in invoice.move_id.line_id if x.account_id.id == invoice.account_id.id]
            for st in order.statement_ids:
                for move in st.move_ids:
                    data_lines += [x.id for x in move.line_id if x.account_id.id == invoice.account_id.id]
                    self.pool.get('account.move.line').reconcile(cr, uid, data_lines, context=context)
        return {}

""" Checks that reversed() receive proper argument """
from collections import deque
__revision__ = 0

class GoodReversed(object):
    """ Implements __reversed__ """

    def __reversed__(self):
        return [1, 2, 3]

class SecondGoodReversed(object):
    """ Implements __len__ and __getitem__ """

    def __len__(self):
        return 3

    def __getitem__(self, index):
        return index

class BadReversed(object):
    """ implements only len() """

    def __len__(self):
        return 3

class SecondBadReversed(object):
    """ implements only __getitem__ """

    def __getitem__(self, index):
        return index

class ThirdBadReversed(dict):
    """ dict subclass """

def uninferable(seq):
    """ This can't be infered at this moment,
    make sure we don't have a false positive.
    """
    return reversed(seq)

def test(path):
    """ test function """
    seq = reversed()
    seq = reversed(None)
    seq = reversed([1, 2, 3])
    seq = reversed((1, 2, 3))
    seq = reversed(set())
    seq = reversed({'a': 1, 'b': 2})
    seq = reversed(iter([1, 2, 3]))
    seq = reversed(GoodReversed())
    seq = reversed(SecondGoodReversed())
    seq = reversed(BadReversed())
    seq = reversed(SecondBadReversed())
    seq = reversed(range(100))
    seq = reversed(ThirdBadReversed())
    seq = reversed(lambda : None)
    seq = reversed(deque([]))
    seq = reversed('123')
    seq = uninferable([1, 2, 3])
    seq = reversed(path.split('/'))
    return seq

def test_dict_ancestor_and_reversed():
    """Don't emit for subclasses of dict, with __reversed__ implemented."""
    from collections import OrderedDict

    class Child(dict):

        def __reversed__(self):
            return reversed(range(10))
    seq = reversed(OrderedDict())
    return (reversed(Child()), seq)

import torch
import torch.nn as nn
from zoo.automl.model.base_pytorch_model import PytorchBaseModel, PYTORCH_REGRESSION_LOSS_MAP
import numpy as np

class LSTMSeq2Seq(nn.Module):

    def __init__(self, input_feature_num, future_seq_len, output_feature_num, lstm_hidden_dim=128, lstm_layer_num=2, dropout=0.25, teacher_forcing=False):
        super(LSTMSeq2Seq, self).__init__()
        self.lstm_encoder = nn.LSTM(input_size=input_feature_num, hidden_size=lstm_hidden_dim, num_layers=lstm_layer_num, dropout=dropout, batch_first=True)
        self.lstm_decoder = nn.LSTM(input_size=output_feature_num, hidden_size=lstm_hidden_dim, num_layers=lstm_layer_num, dropout=dropout, batch_first=True)
        self.fc = nn.Linear(in_features=lstm_hidden_dim, out_features=output_feature_num)
        self.future_seq_len = future_seq_len
        self.output_feature_num = output_feature_num
        self.teacher_forcing = teacher_forcing

    def forward(self, input_seq, target_seq=None):
        (x, (hidden, cell)) = self.lstm_encoder(input_seq)
        decoder_input = input_seq[:, -1, :self.output_feature_num]
        decoder_input = decoder_input.unsqueeze(1)
        decoder_output = []
        for i in range(self.future_seq_len):
            (decoder_output_step, (hidden, cell)) = self.lstm_decoder(decoder_input, (hidden, cell))
            out_step = self.fc(decoder_output_step)
            decoder_output.append(out_step)
            if not self.teacher_forcing or target_seq is None:
                decoder_input = out_step
            else:
                decoder_input = target_seq[:, i:i + 1, :]
        decoder_output = torch.cat(decoder_output, dim=1)
        return decoder_output

def model_creator(config):
    return LSTMSeq2Seq(input_feature_num=config['input_feature_num'], output_feature_num=config['output_feature_num'], future_seq_len=config['future_seq_len'], lstm_hidden_dim=config.get('lstm_hidden_dim', 128), lstm_layer_num=config.get('lstm_layer_num', 2), dropout=config.get('dropout', 0.25), teacher_forcing=config.get('teacher_forcing', False))

def optimizer_creator(model, config):
    return getattr(torch.optim, config.get('optim', 'Adam'))(model.parameters(), lr=config.get('lr', 0.001))

def loss_creator(config):
    loss_name = config.get('loss', 'mse')
    if loss_name in PYTORCH_REGRESSION_LOSS_MAP:
        loss_name = PYTORCH_REGRESSION_LOSS_MAP[loss_name]
    else:
        raise RuntimeError(f'Got "{loss_name}" for loss name,                           where "mse", "mae" or "huber_loss" is expected')
    return getattr(torch.nn, loss_name)()

class Seq2SeqPytorch(PytorchBaseModel):

    def __init__(self, check_optional_config=False):
        super().__init__(model_creator=model_creator, optimizer_creator=optimizer_creator, loss_creator=loss_creator, check_optional_config=check_optional_config)

    def _input_check(self, x, y):
        if len(x.shape) < 3:
            raise RuntimeError(f'Invalid data x with {len(x.shape)} dim where 3 dim is required.')
        if len(y.shape) < 3:
            raise RuntimeError(f'Invalid data y with {len(y.shape)} dim where 3 dim is required.')
        if y.shape[-1] > x.shape[-1]:
            raise RuntimeError(f'output dim should not larger than input dim,                                while we get {y.shape[-1]} > {x.shape[-1]}.')

    def _forward(self, x, y):
        self._input_check(x, y)
        return self.model(x, y)

    def _get_required_parameters(self):
        return {'input_feature_num', 'future_seq_len', 'output_feature_num'}

    def _get_optional_parameters(self):
        return {'lstm_hidden_dim', 'lstm_layer_num', 'teacher_forcing'} | super()._get_optional_parameters()

