import re
from urllib import robotparser
from urllib.parse import urljoin
from downloader import Downloader

def get_robots_parser(robots_url):
    rp = robotparser.RobotFileParser()
    rp.set_url(robots_url)
    rp.read()
    return rp

def get_links(html):
    webpage_regex = re.compile('<a[^>]+href=["\'](.*?)["\']', re.IGNORECASE)
    return webpage_regex.findall(html)

def link_crawler(start_url, link_regex, robots_url=None, user_agent='wswp', proxies=None, delay=3, max_depth=4, num_retries=2, cache={}, scraper_callback=None):
    crawl_queue = [start_url]
    seen = {}
    if not robots_url:
        robots_url = '{}/robots.txt'.format(start_url)
    rp = get_robots_parser(robots_url)
    D = Downloader(delay=delay, user_agent=user_agent, proxies=proxies, cache=cache)
    while crawl_queue:
        url = crawl_queue.pop()
        if rp.can_fetch(user_agent, url):
            depth = seen.get(url, 0)
            if depth == max_depth:
                print('Skipping %s due to depth' % url)
                continue
            html = D(url, num_retries=num_retries)
            if not html:
                continue
            if scraper_callback:
                links = scraper_callback(url, html) or []
            else:
                links = []
            for link in get_links(html) + links:
                if re.match(link_regex, link):
                    abs_link = urljoin(start_url, link)
                    if abs_link not in seen:
                        seen[abs_link] = depth + 1
                        crawl_queue.append(abs_link)
        else:
            print('Blocked by robots.txt:', url)

"""
SchedulerOptions monitors a local .json file for changes and loads
it if needed. This file is converted to a data structure and passed
into the filtering and weighing functions which can use it for
dynamic configuration.
"""
import datetime
import os
from oslo_config import cfg
from oslo_log import log
from oslo_serialization import jsonutils
from oslo_utils import timeutils
scheduler_json_config_location_opt = cfg.StrOpt('scheduler_json_config_location', default='', help='Absolute path to scheduler configuration JSON file.')
CONF = cfg.CONF
CONF.register_opt(scheduler_json_config_location_opt)
LOG = log.getLogger(__name__)

class SchedulerOptions(object):
    """Monitor and load local .json file for filtering and weighing.

    SchedulerOptions monitors a local .json file for changes and loads it
    if needed. This file is converted to a data structure and passed into
    the filtering and weighing functions which can use it for dynamic
    configuration.
    """

    def __init__(self):
        super(SchedulerOptions, self).__init__()
        self.data = {}
        self.last_modified = None
        self.last_checked = None

    def _get_file_handle(self, filename):
        """Get file handle. Broken out for testing."""
        return open(filename)

    def _get_file_timestamp(self, filename):
        """Get the last modified datetime. Broken out for testing."""
        try:
            return os.path.getmtime(filename)
        except os.error:
            LOG.exception('Could not stat scheduler options file %(filename)s.', {'filename': filename})
            raise

    def _load_file(self, handle):
        """Decode the JSON file. Broken out for testing."""
        try:
            return jsonutils.load(handle)
        except ValueError:
            LOG.exception('Could not decode scheduler options.')
            return {}

    def _get_time_now(self):
        """Get current UTC. Broken out for testing."""
        return timeutils.utcnow()

    def get_configuration(self, filename=None):
        """Check the json file for changes and load it if needed."""
        if not filename:
            filename = CONF.scheduler_json_config_location
        if not filename:
            return self.data
        if self.last_checked:
            now = self._get_time_now()
            if now - self.last_checked < datetime.timedelta(minutes=5):
                return self.data
        last_modified = self._get_file_timestamp(filename)
        if not last_modified or not self.last_modified or last_modified > self.last_modified:
            self.data = self._load_file(self._get_file_handle(filename))
            self.last_modified = last_modified
        if not self.data:
            self.data = {}
        return self.data

import os
import re
import warnings
from ctypes import c_char_p
from django.contrib.gis.geoip.libgeoip import GEOIP_SETTINGS
from django.contrib.gis.geoip.prototypes import GeoIP_country_code_by_addr, GeoIP_country_code_by_name, GeoIP_country_name_by_addr, GeoIP_country_name_by_name, GeoIP_database_info, GeoIP_delete, GeoIP_lib_version, GeoIP_open, GeoIP_record_by_addr, GeoIP_record_by_name
from django.core.validators import ipv4_re
from django.utils import six
from django.utils.deprecation import RemovedInDjango20Warning
from django.utils.encoding import force_bytes, force_text
free_regex = re.compile('^GEO-\\d{3}FREE')
lite_regex = re.compile('^GEO-\\d{3}LITE')

class GeoIPException(Exception):
    pass

class GeoIP(object):
    GEOIP_STANDARD = 0
    GEOIP_MEMORY_CACHE = 1
    GEOIP_CHECK_CACHE = 2
    GEOIP_INDEX_CACHE = 4
    GEOIP_MMAP_CACHE = 8
    cache_options = {opt: None for opt in (0, 1, 2, 4, 8)}
    _city_file = ''
    _country_file = ''
    _city = None
    _country = None

    def __init__(self, path=None, cache=0, country=None, city=None):
        """
        Initializes the GeoIP object, no parameters are required to use default
        settings.  Keyword arguments may be passed in to customize the locations
        of the GeoIP data sets.

        * path: Base directory to where GeoIP data is located or the full path
            to where the city or country data files (*.dat) are located.
            Assumes that both the city and country data sets are located in
            this directory; overrides the GEOIP_PATH settings attribute.

        * cache: The cache settings when opening up the GeoIP datasets,
            and may be an integer in (0, 1, 2, 4, 8) corresponding to
            the GEOIP_STANDARD, GEOIP_MEMORY_CACHE, GEOIP_CHECK_CACHE,
            GEOIP_INDEX_CACHE, and GEOIP_MMAP_CACHE, `GeoIPOptions` C API
            settings,  respectively.  Defaults to 0, meaning that the data is read
            from the disk.

        * country: The name of the GeoIP country data file.  Defaults to
            'GeoIP.dat'; overrides the GEOIP_COUNTRY settings attribute.

        * city: The name of the GeoIP city data file.  Defaults to
            'GeoLiteCity.dat'; overrides the GEOIP_CITY settings attribute.
        """
        warnings.warn('django.contrib.gis.geoip is deprecated in favor of django.contrib.gis.geoip2 and the MaxMind GeoLite2 database format.', RemovedInDjango20Warning, 2)
        if cache in self.cache_options:
            self._cache = cache
        else:
            raise GeoIPException('Invalid GeoIP caching option: %s' % cache)
        if not path:
            path = GEOIP_SETTINGS.get('GEOIP_PATH')
            if not path:
                raise GeoIPException('GeoIP path must be provided via parameter or the GEOIP_PATH setting.')
        if not isinstance(path, six.string_types):
            raise TypeError('Invalid path type: %s' % type(path).__name__)
        if os.path.isdir(path):
            country_db = os.path.join(path, country or GEOIP_SETTINGS.get('GEOIP_COUNTRY', 'GeoIP.dat'))
            if os.path.isfile(country_db):
                self._country = GeoIP_open(force_bytes(country_db), cache)
                self._country_file = country_db
            city_db = os.path.join(path, city or GEOIP_SETTINGS.get('GEOIP_CITY', 'GeoLiteCity.dat'))
            if os.path.isfile(city_db):
                self._city = GeoIP_open(force_bytes(city_db), cache)
                self._city_file = city_db
        elif os.path.isfile(path):
            ptr = GeoIP_open(force_bytes(path), cache)
            info = GeoIP_database_info(ptr)
            if lite_regex.match(info):
                self._city = ptr
                self._city_file = path
            elif free_regex.match(info):
                self._country = ptr
                self._country_file = path
            else:
                raise GeoIPException('Unable to recognize database edition: %s' % info)
        else:
            raise GeoIPException('GeoIP path must be a valid file or directory.')

    def __del__(self):
        if GeoIP_delete is None:
            return
        if self._country:
            GeoIP_delete(self._country)
        if self._city:
            GeoIP_delete(self._city)

    def __repr__(self):
        version = ''
        if GeoIP_lib_version is not None:
            version += ' [v%s]' % force_text(GeoIP_lib_version())
        return '<%(cls)s%(version)s _country_file="%(country)s", _city_file="%(city)s">' % {'cls': self.__class__.__name__, 'version': version, 'country': self._country_file, 'city': self._city_file}

    def _check_query(self, query, country=False, city=False, city_or_country=False):
        """Helper routine for checking the query and database availability."""
        if not isinstance(query, six.string_types):
            raise TypeError('GeoIP query must be a string, not type %s' % type(query).__name__)
        if city_or_country and (not (self._country or self._city)):
            raise GeoIPException('Invalid GeoIP country and city data files.')
        elif country and (not self._country):
            raise GeoIPException('Invalid GeoIP country data file: %s' % self._country_file)
        elif city and (not self._city):
            raise GeoIPException('Invalid GeoIP city data file: %s' % self._city_file)
        return force_bytes(query)

    def city(self, query):
        """
        Returns a dictionary of city information for the given IP address or
        Fully Qualified Domain Name (FQDN).  Some information in the dictionary
        may be undefined (None).
        """
        enc_query = self._check_query(query, city=True)
        if ipv4_re.match(query):
            return GeoIP_record_by_addr(self._city, c_char_p(enc_query))
        else:
            return GeoIP_record_by_name(self._city, c_char_p(enc_query))

    def country_code(self, query):
        """Returns the country code for the given IP Address or FQDN."""
        enc_query = self._check_query(query, city_or_country=True)
        if self._country:
            if ipv4_re.match(query):
                return GeoIP_country_code_by_addr(self._country, enc_query)
            else:
                return GeoIP_country_code_by_name(self._country, enc_query)
        else:
            return self.city(query)['country_code']

    def country_name(self, query):
        """Returns the country name for the given IP Address or FQDN."""
        enc_query = self._check_query(query, city_or_country=True)
        if self._country:
            if ipv4_re.match(query):
                return GeoIP_country_name_by_addr(self._country, enc_query)
            else:
                return GeoIP_country_name_by_name(self._country, enc_query)
        else:
            return self.city(query)['country_name']

    def country(self, query):
        """
        Returns a dictionary with the country code and name when given an
        IP address or a Fully Qualified Domain Name (FQDN).  For example, both
        '24.124.1.80' and 'djangoproject.com' are valid parameters.
        """
        return {'country_code': self.country_code(query), 'country_name': self.country_name(query)}

    def coords(self, query, ordering=('longitude', 'latitude')):
        cdict = self.city(query)
        if cdict is None:
            return None
        else:
            return tuple((cdict[o] for o in ordering))

    def lon_lat(self, query):
        """Returns a tuple of the (longitude, latitude) for the given query."""
        return self.coords(query)

    def lat_lon(self, query):
        """Returns a tuple of the (latitude, longitude) for the given query."""
        return self.coords(query, ('latitude', 'longitude'))

    def geos(self, query):
        """Returns a GEOS Point object for the given query."""
        ll = self.lon_lat(query)
        if ll:
            from django.contrib.gis.geos import Point
            return Point(ll, srid=4326)
        else:
            return None

    @property
    def country_info(self):
        """Returns information about the GeoIP country database."""
        if self._country is None:
            ci = 'No GeoIP Country data in "%s"' % self._country_file
        else:
            ci = GeoIP_database_info(self._country)
        return ci

    @property
    def city_info(self):
        """Returns information about the GeoIP city database."""
        if self._city is None:
            ci = 'No GeoIP City data in "%s"' % self._city_file
        else:
            ci = GeoIP_database_info(self._city)
        return ci

    @property
    def info(self):
        """Returns information about the GeoIP library and databases in use."""
        info = ''
        if GeoIP_lib_version:
            info += 'GeoIP Library:\n\t%s\n' % GeoIP_lib_version()
        return info + 'Country:\n\t%s\nCity:\n\t%s' % (self.country_info, self.city_info)

    @classmethod
    def open(cls, full_path, cache):
        return GeoIP(full_path, cache)

    def _rec_by_arg(self, arg):
        if self._city:
            return self.city(arg)
        else:
            return self.country(arg)
    region_by_addr = city
    region_by_name = city
    record_by_addr = _rec_by_arg
    record_by_name = _rec_by_arg
    country_code_by_addr = country_code
    country_code_by_name = country_code
    country_name_by_addr = country_name
    country_name_by_name = country_name

from django.conf import settings
from django.test import TestCase
from django.test.utils import override_settings
import track.tracker as tracker
from track.backends import BaseBackend
SIMPLE_SETTINGS = {'default': {'ENGINE': 'track.tests.test_tracker.DummyBackend', 'OPTIONS': {'flag': True}}}
MULTI_SETTINGS = {'first': {'ENGINE': 'track.tests.test_tracker.DummyBackend'}, 'second': {'ENGINE': 'track.tests.test_tracker.DummyBackend'}}

class TestTrackerInstantiation(TestCase):
    """Test that a helper function can instantiate backends from their name."""

    def setUp(self):
        super(TestTrackerInstantiation, self).setUp()
        self.get_backend = tracker._instantiate_backend_from_name

    def test_instatiate_backend(self):
        name = 'track.tests.test_tracker.DummyBackend'
        options = {'flag': True}
        backend = self.get_backend(name, options)
        self.assertIsInstance(backend, DummyBackend)
        self.assertTrue(backend.flag)

    def test_instatiate_backends_with_invalid_values(self):

        def get_invalid_backend(name, parameters):
            return self.get_backend(name, parameters)
        options = {}
        name = 'track.backends.logger'
        self.assertRaises(ValueError, get_invalid_backend, name, options)
        name = 'track.backends.logger.Foo'
        self.assertRaises(ValueError, get_invalid_backend, name, options)
        name = 'this.package.does.not.exists'
        self.assertRaises(ValueError, get_invalid_backend, name, options)
        name = 'unittest.TestCase'
        self.assertRaises(ValueError, get_invalid_backend, name, options)

class TestTrackerDjangoInstantiation(TestCase):
    """Test if backends are initialized properly from Django settings."""

    @override_settings(TRACKING_BACKENDS=SIMPLE_SETTINGS)
    def test_django_simple_settings(self):
        """Test configuration of a simple backend"""
        backends = self._reload_backends()
        self.assertEqual(len(backends), 1)
        tracker.send({})
        self.assertEqual(backends.values()[0].count, 1)

    @override_settings(TRACKING_BACKENDS=MULTI_SETTINGS)
    def test_django_multi_settings(self):
        """Test if multiple backends can be configured properly."""
        backends = self._reload_backends().values()
        self.assertEqual(len(backends), 2)
        event_count = 10
        for _ in xrange(event_count):
            tracker.send({})
        self.assertEqual(backends[0].count, event_count)
        self.assertEqual(backends[1].count, event_count)

    @override_settings(TRACKING_BACKENDS=MULTI_SETTINGS)
    def test_django_remove_settings(self):
        """Test if a backend can be remove by setting it to None."""
        settings.TRACKING_BACKENDS.update({'second': None})
        backends = self._reload_backends()
        self.assertEqual(len(backends), 1)

    def _reload_backends(self):
        tracker._initialize_backends_from_django_settings()
        return tracker.backends

class DummyBackend(BaseBackend):

    def __init__(self, **options):
        super(DummyBackend, self).__init__(**options)
        self.flag = options.get('flag', False)
        self.count = 0

    def send(self, event):
        self.count += 1

import yaml
import random
import roslib

class Fluent(yaml.YAMLObject):
    yaml_tag = '!Fluent'

    def __setstate__(self, state):
        """
        PyYaml does not call __init__. this is an init replacement.
        """
        self.properties = []
        self.Class_Instance = state['Class_Instance']
        if type(self.Class_Instance[0]) == type(False):
            self.Class_Instance[0] = '"On"'
        if self.Class_Instance[0] == 'On':
            self.Class_Instance[0] = '"On"'
        self.StartTime = state['StartTime']
        self.FinishTime = state['FinishTime']
        for preProp in state['Properties']:
            self.properties.append(Property(preProp[0], preProp[1], preProp[2]))

    def toYamlString(self, line_break='\n'):
        yString = ''
        yString += '!Fluent' + line_break
        yString += '{:<16} {:<20}'.format('Class_Instance: ', '[' + self.Class_Instance[0] + ', ' + self.Class_Instance[1] + ']') + line_break
        yString += '{:<16} {:<20}'.format('StartTime: ', str(self.StartTime)) + line_break
        yString += '{:<16} {:<20}'.format('FinishTime: ', str(self.FinishTime)) + line_break
        if len(self.properties) > 0:
            yString += 'Properties:' + line_break
            for prop in self.properties:
                yString += prop.toYamlString()
        else:
            yString += 'Properties: []' + line_break
        return yString

    def __str__(self):
        return self.toYamlString()

class Property:

    def __init__(self, role_type, filler_type, role_filler):
        self.role_type = role_type
        self.filler_type = filler_type
        self.role_filler = role_filler
        for (key, value) in self.__dict__.items():
            if type(value) == type(False):
                setattr(self, key, 'On')

    def toYamlString(self, line_break='\n'):
        return '  -  [{}, {}, {}]'.format(self.role_type, '"' + self.filler_type + '"', self.role_filler) + line_break

    def __str__(self):
        return self.toYamlString()

class FluentPoseModification(Fluent):
    yaml_tag = '!FluentPoseModification'
    GROUP_CHOICE_MAP = {}

    def __setstate__(self, state):
        """
        PyYaml does not call __init__. this is an init replacement.
        """
        if not FluentPoseModification.GROUP_CHOICE_MAP.has_key(state['Group']):
            choice = random.randint(0, state['Choices'] - 1)
            FluentPoseModification.GROUP_CHOICE_MAP[state['Group']] = choice
        self.choice = FluentPoseModification.GROUP_CHOICE_MAP[state['Group']]
        self.Instance = state['Instance']
        self.Modifications = state['Modifications']
        self.Attachments = state['Attachments']

    def getMod(self, propertyString):
        for mod in self.Modifications:
            if mod[0] == propertyString:
                return mod[1][self.choice]
        return 0
if __name__ == '__main__':
    initialPath = roslib.packages.get_pkg_dir('race_static_knowledge') + '/data/race_initial_knowledge.yaml'
    spawnPath = roslib.packages.get_pkg_dir('race_simulation_run') + '/data/spawn_objects.yaml'
    replacementsPath = roslib.packages.get_pkg_dir('race_simulation_run') + '/data/replace.yaml'
    tempFilePath = roslib.packages.get_pkg_dir('race_simulation_run') + '/data/output.yaml'
    fluents = []
    with open(initialPath) as f:
        for fluent in yaml.load_all(f):
            fluents.append(fluent)
    with open(spawnPath) as f:
        for fluent in yaml.load_all(f):
            fluents.append(fluent)
    fluentPoseModifications = []
    with open(replacementsPath) as f:
