from django import template
from djangosaml2.conf import config_settings_loader
register = template.Library()

class IdPListNode(template.Node):

    def __init__(self, variable_name):
        self.variable_name = variable_name

    def render(self, context):
        conf = config_settings_loader()
        context[self.variable_name] = conf.idps()
        return ''

@register.tag
def idplist(parser, token):
    try:
        (tag_name, as_part, variable) = token.split_contents()
    except ValueError:
        raise template.TemplateSyntaxError('%r tag requires two arguments' % token.contents.split()[0])
    if not as_part == 'as':
        raise template.TemplateSyntaxError('%r tag first argument must be the literal "as"' % tag_name)
    return IdPListNode(variable)

import unittest, sys
from ctypes.test import need_symbol

class SimpleTypesTestCase(unittest.TestCase):

    def setUp(self):
        import ctypes
        try:
            from _ctypes import set_conversion_mode
        except ImportError:
            pass
        else:
            self.prev_conv_mode = set_conversion_mode('ascii', 'strict')

    def tearDown(self):
        try:
            from _ctypes import set_conversion_mode
        except ImportError:
            pass
        else:
            set_conversion_mode(*self.prev_conv_mode)

    def test_subclasses(self):
        from ctypes import c_void_p, c_char_p

        class CVOIDP(c_void_p):

            def from_param(cls, value):
                return value * 2
            from_param = classmethod(from_param)

        class CCHARP(c_char_p):

            def from_param(cls, value):
                return value * 4
            from_param = classmethod(from_param)
        self.assertEqual(CVOIDP.from_param('abc'), 'abcabc')
        self.assertEqual(CCHARP.from_param('abc'), 'abcabcabcabc')

    @need_symbol('c_wchar_p')
    def test_subclasses_c_wchar_p(self):
        from ctypes import c_wchar_p

        class CWCHARP(c_wchar_p):

            def from_param(cls, value):
                return value * 3
            from_param = classmethod(from_param)
        self.assertEqual(CWCHARP.from_param('abc'), 'abcabcabc')

    def test_cstrings(self):
        from ctypes import c_char_p, byref
        s = b'123'
        self.assertIs(c_char_p.from_param(s)._obj, s)
        self.assertEqual(c_char_p.from_param(b'123')._obj, b'123')
        self.assertRaises(TypeError, c_char_p.from_param, '123ÿ')
        self.assertRaises(TypeError, c_char_p.from_param, 42)
        a = c_char_p(b'123')
        self.assertIs(c_char_p.from_param(a), a)

    @need_symbol('c_wchar_p')
    def test_cw_strings(self):
        from ctypes import byref, c_wchar_p
        c_wchar_p.from_param('123')
        self.assertRaises(TypeError, c_wchar_p.from_param, 42)
        self.assertRaises(TypeError, c_wchar_p.from_param, b'123\xff')
        pa = c_wchar_p.from_param(c_wchar_p('123'))
        self.assertEqual(type(pa), c_wchar_p)

    def test_int_pointers(self):
        from ctypes import c_short, c_uint, c_int, c_long, POINTER, pointer
        LPINT = POINTER(c_int)
        x = LPINT.from_param(pointer(c_int(42)))
        self.assertEqual(x.contents.value, 42)
        self.assertEqual(LPINT(c_int(42)).contents.value, 42)
        self.assertEqual(LPINT.from_param(None), None)
        if c_int != c_long:
            self.assertRaises(TypeError, LPINT.from_param, pointer(c_long(42)))
        self.assertRaises(TypeError, LPINT.from_param, pointer(c_uint(42)))
        self.assertRaises(TypeError, LPINT.from_param, pointer(c_short(42)))

    def test_byref_pointer(self):
        from ctypes import c_short, c_uint, c_int, c_long, pointer, POINTER, byref
        LPINT = POINTER(c_int)
        LPINT.from_param(byref(c_int(42)))
        self.assertRaises(TypeError, LPINT.from_param, byref(c_short(22)))
        if c_int != c_long:
            self.assertRaises(TypeError, LPINT.from_param, byref(c_long(22)))
        self.assertRaises(TypeError, LPINT.from_param, byref(c_uint(22)))

    def test_byref_pointerpointer(self):
        from ctypes import c_short, c_uint, c_int, c_long, pointer, POINTER, byref
        LPLPINT = POINTER(POINTER(c_int))
        LPLPINT.from_param(byref(pointer(c_int(42))))
        self.assertRaises(TypeError, LPLPINT.from_param, byref(pointer(c_short(22))))
        if c_int != c_long:
            self.assertRaises(TypeError, LPLPINT.from_param, byref(pointer(c_long(22))))
        self.assertRaises(TypeError, LPLPINT.from_param, byref(pointer(c_uint(22))))

    def test_array_pointers(self):
        from ctypes import c_short, c_uint, c_int, c_long, POINTER
        INTARRAY = c_int * 3
        ia = INTARRAY()
        self.assertEqual(len(ia), 3)
        self.assertEqual([ia[i] for i in range(3)], [0, 0, 0])
        LPINT = POINTER(c_int)
        LPINT.from_param((c_int * 3)())
        self.assertRaises(TypeError, LPINT.from_param, c_short * 3)
        self.assertRaises(TypeError, LPINT.from_param, c_long * 3)
        self.assertRaises(TypeError, LPINT.from_param, c_uint * 3)

    def test_noctypes_argtype(self):
        import _ctypes_test
        from ctypes import CDLL, c_void_p, ArgumentError
        func = CDLL(_ctypes_test.__file__)._testfunc_p_p
        func.restype = c_void_p
        self.assertRaises(TypeError, setattr, func, 'argtypes', (object,))

        class Adapter(object):

            def from_param(cls, obj):
                return None
        func.argtypes = (Adapter(),)
        self.assertEqual(func(None), None)
        self.assertEqual(func(object()), None)

        class Adapter(object):

            def from_param(cls, obj):
                return obj
        func.argtypes = (Adapter(),)
        self.assertRaises(ArgumentError, func, object())
        self.assertEqual(func(c_void_p(42)), 42)

        class Adapter(object):

            def from_param(cls, obj):
                raise ValueError(obj)
        func.argtypes = (Adapter(),)
        self.assertRaises(ArgumentError, func, 99)
