import re
from ansible.module_utils.shell import CliBase
from ansible.module_utils.network import register_transport, to_list, Command
from ansible.module_utils.netcfg import NetworkConfig, ConfigLine

def get_config(module):
    contents = module.params['config']
    if not contents:
        contents = module.config.get_config()
        module.params['config'] = contents
        return NetworkConfig(indent=1, contents=contents[0])
    else:
        return NetworkConfig(indent=1, contents=contents)

def get_sublevel_config(running_config, module):
    contents = list()
    current_config_contents = list()
    obj = running_config.get_object(module.params['parents'])
    if obj:
        contents = obj.children
    contents[:0] = module.params['parents']
    indent = 0
    for c in contents:
        if isinstance(c, str):
            current_config_contents.append(c.rjust(len(c) + indent, ' '))
        if isinstance(c, ConfigLine):
            current_config_contents.append(c.raw)
        indent = indent + 1
    sublevel_config = '\n'.join(current_config_contents)
    return sublevel_config

class Cli(CliBase):
    NET_PASSWD_RE = re.compile('[\\r\\n]?password:\\s?$', re.I)
    WARNING_PROMPTS_RE = [re.compile('[\\r\\n]?\\[confirm yes/no\\]:\\s?$'), re.compile('[\\r\\n]?\\[y/n\\]:\\s?$'), re.compile('[\\r\\n]?\\[yes/no\\]:\\s?$')]
    CLI_PROMPTS_RE = [re.compile('[\\r\\n]?[\\w+\\-\\.:\\/\\[\\]]+(?:\\([^\\)]+\\)){,3}(?:>|#) ?$'), re.compile('\\[\\w+\\@[\\w\\-\\.]+(?: [^\\]])\\] ?[>#\\$] ?$')]
    CLI_ERRORS_RE = [re.compile('% ?Error: (?:(?!\\bdoes not exist\\b)(?!\\balready exists\\b)(?!\\bHost not found\\b)(?!\\bnot active\\b).)*$'), re.compile('% ?Bad secret'), re.compile('invalid input', re.I), re.compile('(?:incomplete|ambiguous) command', re.I), re.compile('connection timed out', re.I), re.compile("'[^']' +returned error code: ?\\d+")]

    def connect(self, params, **kwargs):
        super(Cli, self).connect(params, kickstart=False, **kwargs)
        self.shell.send('terminal length 0')

    def authorize(self, params, **kwargs):
        passwd = params['auth_pass']
        self.run_commands(Command('enable', prompt=self.NET_PASSWD_RE, response=passwd))

    def configure(self, commands, **kwargs):
        cmds = ['configure terminal']
        cmdlist = list()
        for c in to_list(commands):
            cmd = Command(c, prompt=self.WARNING_PROMPTS_RE, response='yes')
            cmdlist.append(cmd)
        cmds.extend(cmdlist)
        cmds.append('end')
        responses = self.execute(cmds)
        responses.pop(0)
        return responses

    def get_config(self, **kwargs):
        return self.execute(['show running-config'])

    def load_config(self, commands, **kwargs):
        return self.configure(commands)

    def save_config(self):
        cmdlist = list()
        cmd = 'copy running-config startup-config'
        cmdlist.append(Command(cmd, prompt=self.WARNING_PROMPTS_RE, response='yes'))
        self.execute(cmdlist)
Cli = register_transport('cli', default=True)(Cli)

"""
    Finds and returns the latest bitcoin price

    Usage Examples:
        - "What is the price of bitcoin?"
        - "How much is a bitcoin worth?"
"""
from athena.classes.module import Module
from athena.classes.task import ActiveTask
from athena import brain

class QuitTask(ActiveTask):

    def __init__(self):
        super().__init__(patterns=['\\b(athena )?(quit|stop)\\b.*'])

    def action(self, text):
        brain.inst.quit()

class ListModulesTask(ActiveTask):

    def __init__(self):
        super().__init__(words=['list modules', 'list mods'])

    def action(self, text):
        brain.inst.list_mods()

class ToggleModuleTask(ActiveTask):

    def __init__(self):
        super().__init__(patterns=['.*\\b(enable|add|disable|remove) (.*)'])
        self.groups = {1: 'enable', 2: 'module'}

    def match(self, text):
        return self.match_and_save_groups(text, self.groups)

    def action(self, text):
        mod_name = self.module.lower().strip().replace(' ', '_')
        if 'disable' in self.enable.lower() or 'remove' in self.enable.lower():
            brain.inst.disable_mod(mod_name)
        else:
            brain.inst.enable_mod(mod_name)

class AthenaControl(Module):

    def __init__(self):
        tasks = [QuitTask(), ListModulesTask(), ToggleModuleTask()]
        super().__init__('athena_control', tasks, priority=3)

import random
import string
from django.db import models
from django.utils import six
from django.utils.encoding import python_2_unicode_compatible

@python_2_unicode_compatible
class MyWrapper(object):

    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return '<%s: %s>' % (self.__class__.__name__, self.value)

    def __str__(self):
        return self.value

    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.value == other.value
        return self.value == other

class MyAutoField(six.with_metaclass(models.SubfieldBase, models.CharField)):

    def __init__(self, *args, **kwargs):
        kwargs['max_length'] = 10
        super(MyAutoField, self).__init__(*args, **kwargs)

    def pre_save(self, instance, add):
        value = getattr(instance, self.attname, None)
        if not value:
            value = MyWrapper(''.join(random.sample(string.ascii_lowercase, 10)))
            setattr(instance, self.attname, value)
        return value

    def to_python(self, value):
        if not value:
            return
        if not isinstance(value, MyWrapper):
            value = MyWrapper(value)
        return value

    def get_db_prep_save(self, value, connection):
        if not value:
            return
        if isinstance(value, MyWrapper):
            return six.text_type(value)
        return value

    def get_db_prep_value(self, value, connection, prepared=False):
        if not value:
            return
        if isinstance(value, MyWrapper):
            return six.text_type(value)
        return value

