__all__ = ['HStoreField']

class HStoreField(Field):
    empty_strings_allowed = False
    description = _('Map of strings to strings')
    default_error_messages = {'not_a_string': _('The value of "%(key)s" is not a string.')}

    def db_type(self, connection):
        return 'hstore'

    def get_transform(self, name):
        transform = super(HStoreField, self).get_transform(name)
        if transform:
            return transform
        return KeyTransformFactory(name)

    def validate(self, value, model_instance):
        super(HStoreField, self).validate(value, model_instance)
        for (key, val) in value.items():
            if not isinstance(val, six.string_types):
                raise exceptions.ValidationError(self.error_messages['not_a_string'], code='not_a_string', params={'key': key})

    def to_python(self, value):
        if isinstance(value, six.string_types):
            value = json.loads(value)
        return value

    def value_to_string(self, obj):
        value = self._get_val_from_obj(obj)
        return json.dumps(value)

    def formfield(self, **kwargs):
        defaults = {'form_class': forms.HStoreField}
        defaults.update(kwargs)
        return super(HStoreField, self).formfield(**defaults)
HStoreField.register_lookup(lookups.DataContains)
