def sort_by_name(hgrid_data):
    return_value = hgrid_data
    if hgrid_data is not None:
        return_value = sorted(hgrid_data, key=lambda item: item['name'].lower())
    return return_value

class NodeFileCollector(object):
    """A utility class for creating rubeus formatted node data"""

    def __init__(self, node, auth, **kwargs):
        NodeRelation = apps.get_model('osf.NodeRelation')
        self.node = node.child if isinstance(node, NodeRelation) else node
        self.auth = auth
        self.extra = kwargs
        self.can_view = self.node.can_view(auth)
        self.can_edit = self.node.can_edit(auth) and (not self.node.is_registration)

    def to_hgrid(self):
        """Return the Rubeus.JS representation of the node's file data, including
        addons and components
        """
        root = self._serialize_node(self.node)
        return [root]

    def _collect_components(self, node, visited):
        rv = []
        if not node.can_view(self.auth):
            return rv
        for child in node.get_nodes(is_deleted=False):
            if not child.can_view(self.auth):
                if child.primary:
                    for desc in child.find_readable_descendants(self.auth):
                        visited.append(desc.resolve()._id)
                        rv.append(self._serialize_node(desc, visited=visited, parent=node))
            elif child.resolve()._id not in visited:
                visited.append(child.resolve()._id)
                rv.append(self._serialize_node(child, visited=visited, parent=node))
        return rv

    def _get_node_name(self, node):
        """Input node object, return the project name to be display.
        """
        NodeRelation = apps.get_model('osf.NodeRelation')
        is_node_relation = isinstance(node, NodeRelation)
        node = node.child if is_node_relation else node
        can_view = node.can_view(auth=self.auth)
        if can_view:
            node_name = sanitize.unescape_entities(node.title)
        elif node.is_registration:
            node_name = u'Private Registration'
        elif node.is_fork:
            node_name = u'Private Fork'
        elif is_node_relation:
            node_name = u'Private Link'
        else:
            node_name = u'Private Component'
        return node_name

    def _serialize_node(self, node, visited=None, parent=None):
        """Returns the rubeus representation of a node folder.
        """
        visited = visited or []
        visited.append(node.resolve()._id)
        can_view = node.can_view(auth=self.auth)
        if can_view:
            children = self._collect_addons(node) + self._collect_components(node, visited)
        else:
            children = []
        is_pointer = parent and parent.has_node_link_to(node)
        return {'name': self._get_node_name(node), 'category': node.category, 'kind': FOLDER, 'permissions': {'edit': node.can_edit(self.auth) and (not node.is_registration), 'view': can_view}, 'urls': {'upload': None, 'fetch': None}, 'children': children, 'isPointer': is_pointer, 'isSmartFolder': False, 'nodeType': node.project_or_component, 'nodeID': node.resolve()._id}

    def _collect_addons(self, node):
        rv = []
        for addon in node.get_addons():
            if addon.config.has_hgrid_files:
                try:
                    temp = addon.config.get_hgrid_data(addon, self.auth, **self.extra)
                except Exception as e:
                    logger.warn(getattr(e, 'data', 'Unexpected error when fetching file contents for {0}.'.format(addon.config.full_name)))
                    sentry.log_exception()
                    rv.append({KIND: FOLDER, 'unavailable': True, 'iconUrl': addon.config.icon_url, 'provider': addon.config.short_name, 'addonFullname': addon.config.full_name, 'permissions': {'view': False, 'edit': False}, 'name': '{} is currently unavailable'.format(addon.config.full_name)})
                    continue
                rv.extend(sort_by_name(temp) or [])
        return rv

def collect_addon_assets(node):
    """Return a dictionary containing lists of JS and CSS assets for a node's
    addons.

    :rtype: {'tree_js': <list of JS scripts>, 'tree_css': <list of CSS files>}
    """
    return {'tree_js': list(collect_addon_js(node)), 'tree_css': list(collect_addon_css(node))}

def collect_addon_js(node, visited=None, filename='files.js', config_entry='files'):
    """Collect JavaScript includes for all add-ons implementing HGrid views.

    :return list: List of JavaScript include paths

    """
    js = []
    for addon_config in settings.ADDONS_AVAILABLE_DICT.values():
        js.extend(addon_config.include_js.get(config_entry, []))
        js_path = paths.resolve_addon_path(addon_config, filename)
        if js_path:
            js.append(js_path)
    return js

def collect_addon_css(node, visited=None):
    """Collect CSS includes for all addons-ons implementing Hgrid views.

    :return: List of CSS include paths
    :rtype: list
    """
    css = []
    for addon_config in settings.ADDONS_AVAILABLE_DICT.values():
        css.extend(addon_config.include_css.get('files', []))
    return css

def delta_date(d):
    diff = d - timezone.now()
    s = diff.total_seconds()
    return s

from . import ServiceBase
from ..cache import cachedmethod
from ..language import language_set, Language
from ..subtitles import get_subtitle_path, ResultSubtitle
from ..utils import get_keywords
from ..videos import Episode
from bs4 import BeautifulSoup
import logging
import re
logger = logging.getLogger(__name__)

def match(pattern, string):
    try:
        return re.search(pattern, string).group(1)
    except AttributeError:
        logger.debug(u'Could not match %r on %r' % (pattern, string))
        return None

class TvSubtitles(ServiceBase):
    server_url = 'http://www.tvsubtitles.net'
    api_based = False
    languages = language_set(['ar', 'bg', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'hu', 'it', 'ja', 'ko', 'nl', 'pl', 'pt', 'ro', 'ru', 'sv', 'tr', 'uk', 'zh', 'pt-br'])
    language_map = {'gr': Language('gre'), 'cz': Language('cze'), 'ua': Language('ukr'), 'cn': Language('chi')}
    videos = [Episode]
    require_video = False
    required_features = ['permissive']

    @cachedmethod
    def get_likely_series_id(self, name):
        r = self.session.post('%s/search.php' % self.server_url, data={'q': name})
        soup = BeautifulSoup(r.content, self.required_features)
        maindiv = soup.find('div', 'left')
        results = []
        for elem in maindiv.find_all('li'):
            sid = int(match('tvshow-([0-9]+)\\.html', elem.a['href']))
            show_name = match('(.*) \\(', elem.a.text)
            results.append((show_name, sid))
        result = results[0]
        return result[1]

    @cachedmethod
    def get_episode_id(self, series_id, season, number):
        """Get the TvSubtitles id for the given episode. Raises KeyError if none
        could be found."""
        episode_id = None
        r = self.session.get('%s/tvshow-%d-%d.html' % (self.server_url, series_id, season))
        soup = BeautifulSoup(r.content, self.required_features)
        table = soup.find('table', id='table5')
        for row in table.find_all('tr'):
            cells = row.find_all('td')
            if not cells:
                continue
            episode_number = match('x([0-9]+)', cells[0].text)
            if not episode_number:
                continue
            episode_number = int(episode_number)
            episode_id = int(match('episode-([0-9]+)', cells[1].a['href']))
            self.cache_for(self.get_episode_id, args=(series_id, season, episode_number), result=episode_id)
        return self.cached_value(self.get_episode_id, args=(series_id, season, number))

    def get_sub_ids(self, episode_id):
        subids = []
        r = self.session.get('%s/episode-%d.html' % (self.server_url, episode_id))
        epsoup = BeautifulSoup(r.content, self.required_features)
        for subdiv in epsoup.find_all('a'):
            if 'href' not in subdiv.attrs or not subdiv['href'].startswith('/subtitle'):
                continue
            subid = int(match('([0-9]+)', subdiv['href']))
            lang = self.get_language(match('flags/(.*).gif', subdiv.img['src']))
            result = {'subid': subid, 'language': lang}
            for p in subdiv.find_all('p'):
                if 'alt' in p.attrs and p['alt'] == 'rip':
                    result['rip'] = p.text.strip()
                if 'alt' in p.attrs and p['alt'] == 'release':
                    result['release'] = p.text.strip()
            subids.append(result)
        return subids

    def list_checked(self, video, languages):
        return self.query(video.path or video.release, languages, get_keywords(video.guess), video.series, video.season, video.episode)

    def query(self, filepath, languages, keywords, series, season, episode):
        logger.debug(u'Getting subtitles for %s season %d episode %d with languages %r' % (series, season, episode, languages))
        self.init_cache()
        sid = self.get_likely_series_id(series.lower())
        try:
            ep_id = self.get_episode_id(sid, season, episode)
        except KeyError:
            logger.debug(u'Could not find episode id for %s season %d episode %d' % (series, season, episode))
            return []
        subids = self.get_sub_ids(ep_id)
        subtitles = []
        for subid in subids:
            language = subid['language']
            if language not in languages:
                continue
            path = get_subtitle_path(filepath, language, self.config.multi)
            subtitle = ResultSubtitle(path, language, self.__class__.__name__.lower(), '%s/download-%d.html' % (self.server_url, subid['subid']), keywords=[subid['rip'], subid['release']])
            subtitles.append(subtitle)
        return subtitles

    def download(self, subtitle):
        self.download_zip_file(subtitle.link, subtitle.path)
        return subtitle
Service = TvSubtitles

"""
This module is used to build queries for Postgresql.  You shouldn't really need
to import anything from this file because they can all be built using
dictorm.Table.

Sqlite queries are slightly different, but use these methods as their base.
"""
from copy import copy
from typing import Union
global sort_keys
sort_keys = False
__all__ = ['And', 'Column', 'Comparison', 'Delete', 'Insert', 'Null', 'Operator', 'Or', 'Select', 'set_sort_keys', 'Update']

def set_sort_keys(val):
    """Used only for testing"""
    global sort_keys
    sort_keys = val

class Select(object):
    query = 'SELECT * FROM "{table}"'

    def __init__(self, table, operators_or_comp=None, returning=None):
        self.table = table
        self.operators_or_comp = operators_or_comp or []
        self.returning = returning
        self._order_by = None
        self._limit = None
        self._offset = None

    def __repr__(self):
        return 'Select({0}, {1}, ret:{2}, order:{3}, limit:{4}, offset:{5}'.format(self.table, repr(self.operators_or_comp), self.returning, self._order_by, self._limit, self._offset)

    def _copy(self):
        try:
            ooc = self.operators_or_comp[:]
        except TypeError:
            ooc = self.operators_or_comp._copy()
        new = type(self)(self.table, ooc, copy(self.returning))
        new._order_by = copy(self._order_by)
        new._limit = copy(self._limit)
        new._offset = copy(self._offset)
        return new

    def __str__(self):
        parts = []
        formats = {'table': self.table}
        ooc = self.operators_or_comp
        if isinstance(ooc, Operator) and ooc.operators_or_comp or isinstance(ooc, Comparison):
            parts.append(' WHERE {comp}')
            formats['comp'] = str(ooc)
        if self._order_by:
            parts.append(' ORDER BY {0}'.format(str(self._order_by)))
        if self.returning == '*':
            parts.append(' RETURNING *')
        elif self.returning:
            parts.append(' RETURNING "{0}"'.format(str(self.returning)))
        if self._limit:
            parts.append(' LIMIT {0}'.format(str(self._limit)))
        if self._offset:
            parts.append(' OFFSET {0}'.format(str(self._offset)))
        sql = self.query + ''.join(parts)
        return sql.format(**formats)

    def values(self):
        return list(self.operators_or_comp or [])

    def build(self):
        return (str(self), self.values())

    def order_by(self, order_by):
        self._order_by = order_by
        return self

    def limit(self, limit):
        self._limit = limit
        return self

    def offset(self, offset):
        self._offset = offset
        return self

    def __add__(self, item):
        self.operators_or_comp += item
        return self

class Insert(object):
    query = 'INSERT INTO "{table}" {cvp}'
    cvp = '({0}) VALUES ({1})'
    interpolation_str = '%s'
    append_returning = None
    last_row = 'SELECT {0} FROM "{1}" WHERE "rowid" = last_insert_rowid()'

    def __init__(self, table, **values):
        self.table = table
        self._values = values
        self._returning = None
        self._ordered_keys = values.keys()
        if sort_keys:
            self._ordered_keys = sorted(self._ordered_keys)

    def _build_cvp(self):
        return (', '.join(['"{}"'.format(i) for i in self._ordered_keys]), ', '.join([self.interpolation_str] * len(self._values)))

    def __str__(self):
        sql = self.query
        if self._returning == '*':
            sql += ' RETURNING *'
        elif self._returning:
            sql += ' RETURNING "{0}"'.format(self._returning)
        if not self._values:
            return sql.format(table=self.table, cvp='DEFAULT VALUES')
        return sql.format(table=self.table, cvp=self.cvp.format(*self._build_cvp()))

    def values(self):
        return [self._values[k] for k in self._ordered_keys]

    def build(self):
        (sql, values) = (str(self), self.values())
        if self.append_returning:
            ret = [(sql, values)]
            ret.append((self.last_row.format(self.append_returning, self.table), []))
            return ret
        return (sql, values)

    def returning(self, returning):
        self._returning = returning
        return self

class Update(Insert):
    query = 'UPDATE "{table}" SET {cvp}'
    interpolation_str = '%s'

    def __init__(self, table, **values):
        self.operators_or_comp = None
        super(Update, self).__init__(table, **values)

    def _build_cvp(self):
        return ', '.join(('"{0}"={1}'.format(k, self.interpolation_str) for k in self._ordered_keys))

    def __str__(self):
        parts = []
        formats = {'table': self.table, 'cvp': self._build_cvp()}
        if self.operators_or_comp:
            parts.append(' WHERE {comps}')
            formats['comps'] = str(self.operators_or_comp)
        if self._returning == '*':
            parts.append(' RETURNING *')
        elif self._returning:
            parts.append(' RETURNING "{0}"'.format(self._returning))
        sql = self.query + ''.join(parts)
        return sql.format(**formats)

    def values(self):
        values = super(Update, self).values()
        if self.operators_or_comp:
            values.extend(list(self.operators_or_comp))
        return values

    def where(self, operators_or_comp):
        self.operators_or_comp = operators_or_comp
        return self

class Delete(Update):
    query = 'DELETE FROM "{table}"'
QueryHint = Union[Select, Insert, Update, Delete]

class Comparison(object):
    interpolation_str = '%s'
    many = False

    def __init__(self, column1, column2, kind):
        self.column1 = column1
        self.column2 = column2
        self.kind = kind
        self._substratum = None
        self._aggregate = False
        self._array_exp = False

    def __repr__(self):
        if isinstance(self.column2, Null):
            ret = 'Comparison({0}{1})'.format(self.column1, self.kind)
        ret = 'Comparison{0}({1}{2}{3})'.format('Many' if self.many else '', self.column1, str(self.kind), self.column2)
        if self._substratum:
            ret += '.substratum({0})'.format(self._substratum)
        return ret

    def __str__(self):
        c1 = self.column1.column
        if self._null_kind():
            return '"{0}"{1}'.format(c1, self.kind)
        if self._array_exp:
            return '"{0}"{1}({2})'.format(c1, self.kind, self.interpolation_str)
        return '"{0}"{1}{2}'.format(c1, self.kind, self.interpolation_str)

    def _copy(self):
        new = type(self)(self.column1, self.column2, self.kind)
        new._substratum = self._substratum
        new._aggregate = self._aggregate
        return new

    def value(self):
        return self.column2

    def __iter__(self):
        if self._null_kind():
            return iter([])
        return iter([self.column2])

    def substratum(self, column):
        comp = Comparison(self.column1, self.column2, self.kind)
        comp._substratum = column
        comp.many = self.many
        return comp

    def aggregate(self, column):
        comp = self.substratum(column)
        comp._aggregate = True
        return comp

    def _null_kind(self):
        return isinstance(self.column2, Null)

    def Or(self, comp2):
        return Or(self, comp2)

    def And(self, comp2):
        return And(self, comp2)

class Null:
    pass

class Column(object):
    comparison = Comparison

    def __init__(self, table, column):
        self.table = table
        self.column = column

    def __repr__(self):
        return '{0}.{1}'.format(self.table, self.column)

    def many(self, column):
        c = self.comparison(self, column, '=')
        c.many = True
        return c

    def __eq__(self, column):
        return self.comparison(self, column, '=')

    def __gt__(self, column):
        return self.comparison(self, column, '>')

    def __ge__(self, column):
        return self.comparison(self, column, '>=')

    def __lt__(self, column):
        return self.comparison(self, column, '<')

    def __le__(self, column):
        return self.comparison(self, column, '<=')

    def __ne__(self, column):
        return self.comparison(self, column, '!=')

    def Is(self, column):
        return self.comparison(self, column, ' IS ')

    def IsNot(self, column):
        return self.comparison(self, column, ' IS NOT ')

    def IsDistinct(self, column):
        return self.comparison(self, column, ' IS DISTINCT FROM ')

    def IsNotDistinct(self, column):
        return self.comparison(self, column, ' IS NOT DISTINCT FROM ')

    def IsNull(self):
        return self.comparison(self, Null(), ' IS NULL')

    def IsNotNull(self):
        return self.comparison(self, Null(), ' IS NOT NULL')

    def In(self, tup):
        if isinstance(tup, list):
            tup = tuple(tup)
        return self.comparison(self, tup, ' IN ')

    def Like(self, column):
        return self.comparison(self, column, ' LIKE ')

    def Ilike(self, column):
        return self.comparison(self, column, ' ILIKE ')

    def Any(self, column):
        comp = self.comparison(self, column, ' = ANY ')
        comp._array_exp = True
        return comp

def wrap_ooc(ooc):
    if isinstance(ooc, Comparison):
        return '%s' % str(ooc)
    return '(%s)' % str(ooc)

class Operator(object):

    def __init__(self, kind, operators_or_comp):
        self.kind = kind
        self.operators_or_comp = operators_or_comp

    def __repr__(self):
        return '{0}{1}'.format(self.kind, repr(self.operators_or_comp))

    def __str__(self):
        kind = ' {0} '.format(self.kind)
        return kind.join(map(wrap_ooc, self.operators_or_comp))

    def __iter__(self):
        i = []
        for comp in self.operators_or_comp:
            if isinstance(comp, Operator):
                i.extend(comp)
            elif isinstance(comp, Comparison) and (not comp._null_kind()):
                i.append(comp.value())
        return iter(i)

    def __add__(self, i):
        if isinstance(i, tuple):
            self.operators_or_comp += i
        else:
            self.operators_or_comp += (i,)
        return self

    def _copy(self):
        new = type(self)()
        new.operators_or_comp = tuple((i._copy() for i in self.operators_or_comp))
        return new

class Or(Operator):

    def __init__(self, *operators_or_comp):
        super(Or, self).__init__('OR', operators_or_comp)

class And(Operator):

    def __init__(self, *operators_or_comp):
        super(And, self).__init__('AND', operators_or_comp)

from __future__ import unicode_literals
import frappe
from frappe.utils import cint
from frappe.model import default_fields

def execute():
    for table in frappe.db.get_tables():
        doctype = table[3:]
        if frappe.db.exists('DocType', doctype):
            fieldnames = [df['fieldname'] for df in frappe.get_all('DocField', fields=['fieldname'], filters={'parent': doctype})]
            custom_fieldnames = [df['fieldname'] for df in frappe.get_all('Custom Field', fields=['fieldname'], filters={'dt': doctype})]
        else:
            fieldnames = custom_fieldnames = []
        for column in frappe.db.sql('desc `{0}`'.format(table), as_dict=True):
            if column['Type'] == 'int(1)':
                fieldname = column['Field']
                if not (fieldname in default_fields or fieldname in fieldnames or fieldname in custom_fieldnames):
                    continue
                frappe.db.sql('update `{table}` set `{column}`=0 where `{column}` is null'.format(table=table, column=fieldname))
                frappe.db.commit()
                frappe.db.sql_ddl('alter table `{table}`\n\t\t\t\t\tmodify `{column}` int(1) not null default {default}'.format(table=table, column=fieldname, default=cint(column['Default'])))

