class Node(object):

    def __init__(self, node, datacenter):
        self.node = node
        self.datacenter = datacenter
        self.partitions = set()

    @property
    def hostname(self):
        return self.node['hostname']

    @property
    def port(self):
        return self.node['port']

    @property
    def rack_id(self):
