            hraf_link = ''
        environmentals = society.get_environmental_data()
        cultural_traits = society.get_cultural_trait_data()
        references = society.get_data_references()
        language_classification = None
        if society.language:
            language_classification = models.LanguageFamily.objects.filter(name=society.language.family.name)
        return Response({'society': society, 'hraf_link': hraf_link[0:len(hraf_link) - 1], 'xd_id': xd_id, 'location': location, 'language_classification': language_classification, 'environmentals': dict(environmentals), 'cultural_traits': dict(cultural_traits), 'references': references}, template_name='society.html')

