import codecs
encode = codecs.utf_16_be_encode

def decode(input, errors='strict'):
    return codecs.utf_16_be_decode(input, errors, True)

class IncrementalEncoder(codecs.IncrementalEncoder):

    def encode(self, input, final=False):
        return codecs.utf_16_be_encode(input, self.errors)[0]

class IncrementalDecoder(codecs.BufferedIncrementalDecoder):
    _buffer_decode = codecs.utf_16_be_decode

class StreamWriter(codecs.StreamWriter):
    encode = codecs.utf_16_be_encode

class StreamReader(codecs.StreamReader):
    decode = codecs.utf_16_be_decode

def getregentry():
    return codecs.CodecInfo(name='utf-16-be', encode=encode, decode=decode, incrementalencoder=IncrementalEncoder, incrementaldecoder=IncrementalDecoder, streamreader=StreamReader, streamwriter=StreamWriter)

import os

class Cert(object):

    def __init__(self, name, buff):
        self.name = name
        self.len = len(buff)
        self.buff = buff
        pass

    def __str__(self):
        out_str = ['\x00'] * 32
        for i in range(len(self.name)):
            out_str[i] = self.name[i]
        out_str = ''.join(out_str)
        out_str += str(chr(self.len & 255))
        out_str += str(chr((self.len & 65280) >> 8))
        out_str += self.buff
        return out_str
        pass

def main():
    cert_list = []
    file_list = os.listdir(os.getcwd())
    cert_file_list = []
    for _file in file_list:
        pos = _file.find('.key_1024')
        if pos != -1:
            cert_file_list.append(_file[:pos])
        pos = _file.find('.cer')
        if pos != -1:
            cert_file_list.append(_file[:pos])
    for cert_file in cert_file_list:
        if cert_file == 'private_key':
            with open(cert_file + '.key_1024', 'rb') as f:
                buff = f.read()
            cert_list.append(Cert(cert_file, buff))
        if cert_file == 'certificate':
            with open(cert_file + '.cer', 'rb') as f:
                buff = f.read()
            cert_list.append(Cert(cert_file, buff))
    with open('esp_cert_private_key.bin', 'wb+') as f:
        for _cert in cert_list:
            f.write('%s' % _cert)
    pass
if __name__ == '__main__':
    main()

"""Email backend that writes messages to a file."""
import datetime
import os
from django.conf import settings
from django.core.exceptions import ImproperlyConfigured
from django.core.mail.backends.console import EmailBackend as ConsoleEmailBackend
from django.utils import six

class EmailBackend(ConsoleEmailBackend):

    def __init__(self, *args, **kwargs):
        self._fname = None
        if 'file_path' in kwargs:
            self.file_path = kwargs.pop('file_path')
        else:
            self.file_path = getattr(settings, 'EMAIL_FILE_PATH', None)
        if not isinstance(self.file_path, six.string_types):
            raise ImproperlyConfigured('Path for saving emails is invalid: %r' % self.file_path)
        self.file_path = os.path.abspath(self.file_path)
        if os.path.exists(self.file_path) and (not os.path.isdir(self.file_path)):
            raise ImproperlyConfigured('Path for saving email messages exists, but is not a directory: %s' % self.file_path)
        elif not os.path.exists(self.file_path):
            try:
                os.makedirs(self.file_path)
            except OSError as err:
                raise ImproperlyConfigured('Could not create directory for saving email messages: %s (%s)' % (self.file_path, err))
        if not os.access(self.file_path, os.W_OK):
            raise ImproperlyConfigured('Could not write to directory: %s' % self.file_path)
        kwargs['stream'] = None
        super(EmailBackend, self).__init__(*args, **kwargs)

    def write_message(self, message):
        self.stream.write(message.message().as_bytes() + b'\n')
        self.stream.write(b'-' * 79)
        self.stream.write(b'\n')

    def _get_filename(self):
        """Return a unique file name."""
        if self._fname is None:
            timestamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S')
            fname = '%s-%s.log' % (timestamp, abs(id(self)))
            self._fname = os.path.join(self.file_path, fname)
        return self._fname

    def open(self):
        if self.stream is None:
            self.stream = open(self._get_filename(), 'ab')
            return True
        return False

    def close(self):
        try:
            if self.stream is not None:
                self.stream.close()
        finally:
            self.stream = None

