    title = re.sub('(&#[0-9]+)([^;^0-9]+)', '\\1;\\2', title)
    title = title.replace('&quot;', '"').replace('&amp;', '&')
    title = re.sub('\n|([[].+?[]])|([(].+?[)])|\\s(vs|v[.])\\s|(:|;|-|"|,|\'|\\_|\\.|\\?)|\\s', '', title)
