    def _real_extract(self, url):
        video_id = self._match_id(url)
        webpage = self._download_webpage(url, video_id)
        video_url = self._html_search_regex('<embed name="Video".*?src="([^"]+)"', webpage, 'QuickTime embed', default=None)
        if video_url is None:
            flash_vars_s = self._html_search_regex('<param name="flashVars" value="([^"]+)"', webpage, 'flash vars', default=None)
            if not flash_vars_s:
                flash_vars_s = self._html_search_regex('<param name="initParams" value="([^"]+)"', webpage, 'flash vars', default=None)
                if flash_vars_s:
                    flash_vars_s = flash_vars_s.replace(',', '&')
            if flash_vars_s:
                flash_vars = compat_parse_qs(flash_vars_s)
                video_url_raw = compat_urllib_request.quote(flash_vars['content'][0])
                video_url = video_url_raw.replace('http%3A', 'http:')
        if video_url is None:
            video_meta = self._html_search_meta('og:video', webpage, default=None)
            if video_meta:
                video_url = self._search_regex('src=(.*?)(?:$|&)', video_meta, 'meta tag video URL', default=None)
        if video_url is None:
            raise ExtractorError('Cannot find video')
        title = self._og_search_title(webpage, default=None)
        if title is None:
            title = self._html_search_regex(['<b>Title:</b> ([^<]*)</div>', 'class="tabSeperator">></span><span class="tabText">(.*?)<'], webpage, 'title')
        thumbnail = self._og_search_thumbnail(webpage)
        description = self._og_search_description(webpage, default=None)
        if description is None:
            description = self._html_search_meta('description', webpage)
        return {'id': video_id, 'url': video_url, 'title': title, 'description': description, 'thumbnail': thumbnail}

from xml.sax.saxutils import escape, quoteattr
from param import *
from emit import Emit

class XmlEmit(Emit):

    def __init__(self):
        wiki_fname = 'apm.pdef.xml'
        self.f = open(wiki_fname, mode='w')
        preamble = '<?xml version="1.0" encoding="utf-8"?>\n        <!-- Dynamically generated list of documented parameters (generated by param_parse.py) -->    \n        <paramfile>\n        <vehicles>\n        '
        self.f.write(preamble)

    def close(self):
        self.f.write('</libraries>')
        self.f.write('</paramfile>\n')
        self.f.close

    def emit_comment(self, s):
        self.f.write('<!-- ' + s + ' -->')

    def start_libraries(self):
        self.f.write('</vehicles>')
        self.f.write('<libraries>')

    def emit(self, g, f):
        t = '<parameters name=%s>\n' % quoteattr(g.name)
        for param in g.params:
            if hasattr(param, 'DisplayName'):
                t += '<param humanName=%s name=%s' % (quoteattr(param.DisplayName), quoteattr(param.name))
            else:
                t += '<param name=%s' % quoteattr(param.name)
            if hasattr(param, 'Description'):
                t += ' documentation=%s' % quoteattr(param.Description)
            if hasattr(param, 'User'):
                t += ' user=%s' % quoteattr(param.User)
            t += '>\n'
            for field in param.__dict__.keys():
                if field not in ['name', 'DisplayName', 'Description', 'User'] and field in known_param_fields:
                    if field == 'Values' and Emit.prog_values_field.match(param.__dict__[field]):
                        t += '<values>\n'
                        values = param.__dict__[field].split(',')
                        for value in values:
                            v = value.split(':')
                            t += '<value code=%s>%s</value>\n' % (quoteattr(v[0]), escape(v[1]))
                        t += '</values>\n'
                    else:
                        t += '<field name=%s>%s</field>\n' % (quoteattr(field), escape(param.__dict__[field]))
            t += '</param>\n'
        t += '</parameters>\n'
        self.f.write(t)

