from oscar.apps.payment.models import SourceType
from oscar.apps.order.models import BillingAddress
from .forms import BillingAddressForm

class PaymentDetailsView(views.PaymentDetailsView):

    def check_payment_data_is_captured(self, request):
        if request.method != 'POST':
            raise exceptions.FailedPreCondition(url=reverse('checkout:payment-details'), message=_('Please enter your payment details'))

    def get_context_data(self, **kwargs):
        ctx = super(PaymentDetailsView, self).get_context_data(**kwargs)
        if 'bankcard_form' not in kwargs:
            ctx['bankcard_form'] = BankcardForm()
        if 'billing_address_form' not in kwargs:
            ctx['billing_address_form'] = self.get_billing_address_form(ctx['shipping_address'])
        elif kwargs['billing_address_form'].is_valid():
            ctx['billing_address'] = kwargs['billing_address_form'].save(commit=False)
        return ctx

    def get_billing_address_form(self, shipping_address):
        """
        Return an instantiated billing address form
        """
        addr = self.get_default_billing_address()
        if not addr:
            return BillingAddressForm(shipping_address=shipping_address)
        billing_addr = BillingAddress()
        addr.populate_alternative_model(billing_addr)
        return BillingAddressForm(shipping_address=shipping_address, instance=billing_addr)

    def handle_payment_details_submission(self, request):
        bankcard_form = BankcardForm(request.POST)
        shipping_address = self.get_shipping_address(self.request.basket)
        address_form = BillingAddressForm(shipping_address, request.POST)
        if address_form.is_valid() and bankcard_form.is_valid():
            return self.render_preview(request, bankcard_form=bankcard_form, billing_address_form=address_form)
        return self.render_payment_details(request, bankcard_form=bankcard_form, billing_address_form=address_form)

    def handle_place_order_submission(self, request):
        bankcard_form = BankcardForm(request.POST)
        shipping_address = self.get_shipping_address(self.request.basket)
        address_form = BillingAddressForm(shipping_address, request.POST)
        if address_form.is_valid() and bankcard_form.is_valid():
            submission = self.build_submission(order_kwargs={'billing_address': address_form.save(commit=False)}, payment_kwargs={'bankcard_form': bankcard_form, 'billing_address_form': address_form})
            return self.submit(**submission)
        messages.error(request, _('Invalid submission'))
        return http.HttpResponseRedirect(reverse('checkout:payment-details'))

    def handle_payment(self, order_number, total, **kwargs):
        facade = Facade()
        bankcard = kwargs['bankcard_form'].bankcard
        datacash_ref = facade.pre_authorise(order_number, total.incl_tax, bankcard)
        (source_type, _) = SourceType.objects.get_or_create(name='Datacash')
        source = source_type.sources.model(source_type=source_type, currency=total.currency, amount_allocated=total.incl_tax, reference=datacash_ref)
        self.add_payment_source(source)
        self.add_payment_event('pre-auth', total.incl_tax, reference=datacash_ref)

"""
Base class for Scrapy spiders

See documentation in docs/topics/spiders.rst
"""
from scrapy import log
from scrapy.http import Request
from scrapy.utils.trackref import object_ref
from scrapy.utils.url import url_is_from_spider
from scrapy.utils.deprecate import create_deprecated_class

class Spider(object_ref):
    """Base class for scrapy spiders. All spiders must inherit from this
    class.
    """
    name = None

    def __init__(self, name=None, **kwargs):
        if name is not None:
            self.name = name
        elif not getattr(self, 'name', None):
            raise ValueError('%s must have a name' % type(self).__name__)
        self.__dict__.update(kwargs)
        if not hasattr(self, 'start_urls'):
            self.start_urls = []

    def log(self, message, level=log.DEBUG, **kw):
        """Log the given messages at the given log level. Always use this
        method to send log messages from your spider
        """
        log.msg(message, spider=self, level=level, **kw)

    def set_crawler(self, crawler):
        assert not hasattr(self, '_crawler'), 'Spider already bounded to %s' % crawler
        self._crawler = crawler

    @property
    def crawler(self):
        assert hasattr(self, '_crawler'), 'Spider not bounded to any crawler'
        return self._crawler

    @property
    def settings(self):
        return self.crawler.settings

    def start_requests(self):
        for url in self.start_urls:
            yield self.make_requests_from_url(url)

    def make_requests_from_url(self, url):
        return Request(url, dont_filter=True)

    def parse(self, response):
        raise NotImplementedError

    @classmethod
    def handles_request(cls, request):
        return url_is_from_spider(request.url, cls)

    def __str__(self):
        return '<%s %r at 0x%0x>' % (type(self).__name__, self.name, id(self))
    __repr__ = __str__
BaseSpider = create_deprecated_class('BaseSpider', Spider)

class ObsoleteClass(object):

    def __init__(self, message):
        self.message = message

    def __getattr__(self, name):
        raise AttributeError(self.message)
spiders = ObsoleteClass('\n"from scrapy.spider import spiders" no longer works - use "from scrapy.project import crawler" and then access crawler.spiders attribute"\n')

