def get_system(module):
    """Return System Object or Fail"""
    user_agent = '%(base)s %(class)s/%(version)s (%(platform)s)' % {'base': USER_AGENT_BASE, 'class': __name__, 'version': VERSION, 'platform': platform.platform()}
    array_name = module.params['fa_url']
    api = module.params['api_token']
    if array_name and api:
        system = purestorage.FlashArray(array_name, api_token=api, user_agent=user_agent)
    elif environ.get('PUREFA_URL') and environ.get('PUREFA_API'):
        system = purestorage.FlashArray(environ.get('PUREFA_URL'), api_token=environ.get('PUREFA_API'), user_agent=user_agent)
    else:
        module.fail_json(msg='You must set PUREFA_URL and PUREFA_API environment variables or the fa_url and api_token module arguments')
    try:
        system.get()
    except Exception:
        module.fail_json(msg='Pure Storage FlashArray authentication failed. Check your credentials')
    return system

def purefa_argument_spec():
    """Return standard base dictionary used for the argument_spec argument in AnsibleModule"""
    return dict(fa_url=dict(), api_token=dict(no_log=True))

from odoo import models, fields, api

class AccountInvoice(models.Model):
    _inherit = 'account.invoice'
    payment_mode_id = fields.Many2one(comodel_name='account.payment.mode', string='Payment Mode', ondelete='restrict', readonly=True, states={'draft': [('readonly', False)]})
    bank_account_required = fields.Boolean(related='payment_mode_id.payment_method_id.bank_account_required', readonly=True)
    partner_bank_id = fields.Many2one(ondelete='restrict')

    @api.onchange('partner_id', 'company_id')
    def _onchange_partner_id(self):
        res = super(AccountInvoice, self)._onchange_partner_id()
        if self.partner_id:
            if self.type == 'in_invoice':
                pay_mode = self.partner_id.supplier_payment_mode_id
                self.payment_mode_id = pay_mode
                if pay_mode and pay_mode.payment_type == 'outbound' and pay_mode.payment_method_id.bank_account_required and self.commercial_partner_id.bank_ids:
                    self.partner_bank_id = self.commercial_partner_id.bank_ids[0]
            elif self.type == 'out_invoice':
                self.payment_mode_id = self.partner_id.customer_payment_mode_id
        else:
            self.payment_mode_id = False
            if self.type == 'in_invoice':
                self.partner_bank_id = False
        return res

    @api.model
    def create(self, vals):
        """Fill the payment_mode_id from the partner if none is provided on
        creation, using same method as upstream."""
        onchanges = {'_onchange_partner_id': ['payment_mode_id']}
        for (onchange_method, changed_fields) in onchanges.items():
            if any((f not in vals for f in changed_fields)):
                invoice = self.new(vals)
                getattr(invoice, onchange_method)()
                for field in changed_fields:
                    if field not in vals and invoice[field]:
                        vals[field] = invoice._fields[field].convert_to_write(invoice[field], invoice)
        return super(AccountInvoice, self).create(vals)

    @api.onchange('payment_mode_id')
    def payment_mode_id_change(self):
        if self.payment_mode_id and self.payment_mode_id.payment_type == 'outbound' and (not self.payment_mode_id.payment_method_id.bank_account_required):
            self.partner_bank_id = False
        elif not self.payment_mode_id:
            self.partner_bank_id = False

    @api.model
    def line_get_convert(self, line, part):
        """Copy payment mode from invoice to account move line"""
        res = super(AccountInvoice, self).line_get_convert(line, part)
        if line.get('type') == 'dest' and line.get('invoice_id'):
            invoice = self.browse(line['invoice_id'])
            res['payment_mode_id'] = invoice.payment_mode_id.id or False
        return res

    @api.model
    def _prepare_refund(self, invoice, date_invoice=None, date=None, description=None, journal_id=None):
        vals = super(AccountInvoice, self)._prepare_refund(invoice, date_invoice=date_invoice, date=date, description=description, journal_id=journal_id)
        vals['payment_mode_id'] = invoice.payment_mode_id.id
        if invoice.type == 'in_invoice':
            vals['partner_bank_id'] = invoice.partner_bank_id.id
        return vals

    def partner_banks_to_show(self):
        self.ensure_one()
        if self.partner_bank_id:
            return self.partner_bank_id
        if self.payment_mode_id.show_bank_account_from_journal:
            if self.payment_mode_id.bank_account_link == 'fixed':
                return self.payment_mode_id.fixed_journal_id.bank_account_id
            else:
                return self.payment_mode_id.variable_journal_ids.mapped('bank_account_id')
        if self.payment_mode_id.payment_method_id.code == 'sepa_direct_debit':
            return self.mandate_id.partner_bank_id or self.partner_id.valid_mandate_id.partner_bank_id
        return self.partner_bank_id

