from __future__ import unicode_literals
import os
from django.contrib.staticfiles import finders
from django.core.management.base import LabelCommand
from django.utils.encoding import force_text

class Command(LabelCommand):
    help = 'Finds the absolute paths for the given static file(s).'
    label = 'static file'

    def add_arguments(self, parser):
        super(Command, self).add_arguments(parser)
        parser.add_argument('--first', action='store_false', dest='all', default=True, help='Only return the first match for each static file.')

    def handle_label(self, path, **options):
        verbosity = options['verbosity']
        result = finders.find(path, all=options['all'])
        path = force_text(path)
        if verbosity >= 2:
            searched_locations = 'Looking in the following locations:\n  %s' % '\n  '.join((force_text(location) for location in finders.searched_locations))
        else:
            searched_locations = ''
        if result:
            if not isinstance(result, (list, tuple)):
                result = [result]
            result = (force_text(os.path.realpath(path)) for path in result)
            if verbosity >= 1:
                file_list = '\n  '.join(result)
                return "Found '%s' here:\n  %s\n%s" % (path, file_list, searched_locations)
            else:
                return '\n'.join(result)
        else:
            message = ["No matching file found for '%s'." % path]
            if verbosity >= 2:
                message.append(searched_locations)
            if verbosity >= 1:
                self.stderr.write('\n'.join(message))

__all__ = ['Client', 'Listener', 'Pipe']
from queue import Queue
families = [None]

class Listener(object):

    def __init__(self, address=None, family=None, backlog=1):
        self._backlog_queue = Queue(backlog)

    def accept(self):
        return Connection(*self._backlog_queue.get())

    def close(self):
        self._backlog_queue = None
    address = property(lambda self: self._backlog_queue)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, exc_tb):
        self.close()

def Client(address):
    (_in, _out) = (Queue(), Queue())
    address.put((_out, _in))
    return Connection(_in, _out)

def Pipe(duplex=True):
    (a, b) = (Queue(), Queue())
    return (Connection(a, b), Connection(b, a))

class Connection(object):

    def __init__(self, _in, _out):
        self._out = _out
        self._in = _in
        self.send = self.send_bytes = _out.put
        self.recv = self.recv_bytes = _in.get

    def poll(self, timeout=0.0):
        if self._in.qsize() > 0:
            return True
        if timeout <= 0.0:
            return False
        self._in.not_empty.acquire()
        self._in.not_empty.wait(timeout)
        self._in.not_empty.release()
        return self._in.qsize() > 0

    def close(self):
        pass

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, exc_tb):
        self.close()

import re
xpath_tokenizer_re = re.compile('(\'[^\']*\'|"[^"]*"|::|//?|\\.\\.|\\(\\)|[/.*:\\[\\]\\(\\)@=])|((?:\\{[^}]+\\})?[^/\\[\\]\\(\\)@=\\s]+)|\\s+')

def xpath_tokenizer(pattern, namespaces=None):
    for token in xpath_tokenizer_re.findall(pattern):
        tag = token[1]
        if tag and tag[0] != '{' and (':' in tag):
            try:
                (prefix, uri) = tag.split(':', 1)
                if not namespaces:
                    raise KeyError
                yield (token[0], '{%s}%s' % (namespaces[prefix], uri))
            except KeyError:
                raise SyntaxError('prefix %r not found in prefix map' % prefix)
        else:
            yield token

def get_parent_map(context):
    parent_map = context.parent_map
    if parent_map is None:
        context.parent_map = parent_map = {}
        for p in context.root.iter():
            for e in p:
                parent_map[e] = p
    return parent_map

def prepare_child(next, token):
    tag = token[1]

    def select(context, result):
        for elem in result:
            for e in elem:
                if e.tag == tag:
                    yield e
    return select

def prepare_star(next, token):

    def select(context, result):
        for elem in result:
            for e in elem:
                yield e
    return select

def prepare_self(next, token):

    def select(context, result):
        for elem in result:
            yield elem
    return select

def prepare_descendant(next, token):
    token = next()
    if token[0] == '*':
        tag = '*'
    elif not token[0]:
        tag = token[1]
    else:
        raise SyntaxError('invalid descendant')

    def select(context, result):
        for elem in result:
            for e in elem.iter(tag):
                if e is not elem:
                    yield e
    return select

def prepare_parent(next, token):

    def select(context, result):
        parent_map = get_parent_map(context)
        result_map = {}
        for elem in result:
            if elem in parent_map:
                parent = parent_map[elem]
                if parent not in result_map:
                    result_map[parent] = None
                    yield parent
    return select

def prepare_predicate(next, token):
    signature = []
    predicate = []
    while 1:
        token = next()
        if token[0] == ']':
            break
        if token[0] and token[0][:1] in '\'"':
            token = ("'", token[0][1:-1])
        signature.append(token[0] or '-')
        predicate.append(token[1])
    signature = ''.join(signature)
    if signature == '@-':
        key = predicate[1]

        def select(context, result):
            for elem in result:
                if elem.get(key) is not None:
                    yield elem
        return select
    if signature == "@-='":
        key = predicate[1]
        value = predicate[-1]

        def select(context, result):
            for elem in result:
                if elem.get(key) == value:
                    yield elem
        return select
    if signature == '-' and (not re.match('\\d+$', predicate[0])):
        tag = predicate[0]

        def select(context, result):
            for elem in result:
                if elem.find(tag) is not None:
                    yield elem
        return select
    if signature == "-='" and (not re.match('\\d+$', predicate[0])):
        tag = predicate[0]
        value = predicate[-1]

        def select(context, result):
            for elem in result:
                for e in elem.findall(tag):
                    if ''.join(e.itertext()) == value:
                        yield elem
                        break
        return select
    if signature == '-' or signature == '-()' or signature == '-()-':
        if signature == '-':
            index = int(predicate[0]) - 1
        else:
            if predicate[0] != 'last':
                raise SyntaxError('unsupported function')
            if signature == '-()-':
                try:
                    index = int(predicate[2]) - 1
                except ValueError:
                    raise SyntaxError('unsupported expression')
            else:
                index = -1

        def select(context, result):
            parent_map = get_parent_map(context)
            for elem in result:
                try:
                    parent = parent_map[elem]
                    elems = list(parent.findall(elem.tag))
                    if elems[index] is elem:
                        yield elem
                except (IndexError, KeyError):
                    pass
        return select
    raise SyntaxError('invalid predicate')
ops = {'': prepare_child, '*': prepare_star, '.': prepare_self, '..': prepare_parent, '//': prepare_descendant, '[': prepare_predicate}
_cache = {}

class _SelectorContext:
    parent_map = None

    def __init__(self, root):
        self.root = root

def iterfind(elem, path, namespaces=None):
    if path[-1:] == '/':
        path = path + '*'
    try:
        selector = _cache[path]
    except KeyError:
        if len(_cache) > 100:
            _cache.clear()
        if path[:1] == '/':
            raise SyntaxError('cannot use absolute path on element')
        next = iter(xpath_tokenizer(path, namespaces)).__next__
        token = next()
        selector = []
        while 1:
            try:
                selector.append(ops[token[0]](next, token))
            except StopIteration:
                raise SyntaxError('invalid path')
            try:
                token = next()
                if token[0] == '/':
                    token = next()
            except StopIteration:
                break
        _cache[path] = selector
    result = [elem]
    context = _SelectorContext(elem)
    for select in selector:
        result = select(context, result)
    return result

def find(elem, path, namespaces=None):
    try:
        return next(iterfind(elem, path, namespaces))
    except StopIteration:
        return None

def findall(elem, path, namespaces=None):
    return list(iterfind(elem, path, namespaces))

def findtext(elem, path, default=None, namespaces=None):
    try:
        elem = next(iterfind(elem, path, namespaces))
        return elem.text or ''
    except StopIteration:
        return default

import sys
import time
from django.conf import settings
from django.db.backends.base.creation import BaseDatabaseCreation
from django.db.utils import DatabaseError
from django.utils.functional import cached_property
from django.utils.six.moves import input
TEST_DATABASE_PREFIX = 'test_'
PASSWORD = 'Im_a_lumberjack'

class DatabaseCreation(BaseDatabaseCreation):

    @cached_property
    def _maindb_connection(self):
        """
        This is analogous to other backends' `_nodb_connection` property,
        which allows access to an "administrative" connection which can
        be used to manage the test databases.
        For Oracle, the only connection that can be used for that purpose
        is the main (non-test) connection.
        """
        settings_dict = settings.DATABASES[self.connection.alias]
        user = settings_dict.get('SAVED_USER') or settings_dict['USER']
        password = settings_dict.get('SAVED_PASSWORD') or settings_dict['PASSWORD']
        settings_dict = settings_dict.copy()
        settings_dict.update(USER=user, PASSWORD=password)
        DatabaseWrapper = type(self.connection)
        return DatabaseWrapper(settings_dict, alias=self.connection.alias)

    def _create_test_db(self, verbosity=1, autoclobber=False, keepdb=False):
        parameters = self._get_test_db_params()
        cursor = self._maindb_connection.cursor()
        if self._test_database_create():
            try:
                self._execute_test_db_creation(cursor, parameters, verbosity, keepdb)
            except Exception as e:
                if keepdb:
                    return
                sys.stderr.write('Got an error creating the test database: %s\n' % e)
                if not autoclobber:
                    confirm = input("It appears the test database, %s, already exists. Type 'yes' to delete it, or 'no' to cancel: " % parameters['user'])
                if autoclobber or confirm == 'yes':
                    if verbosity >= 1:
                        print("Destroying old test database for alias '%s'..." % self.connection.alias)
                    try:
                        self._execute_test_db_destruction(cursor, parameters, verbosity)
                    except DatabaseError as e:
                        if 'ORA-29857' in str(e):
                            self._handle_objects_preventing_db_destruction(cursor, parameters, verbosity, autoclobber)
                        else:
                            sys.stderr.write('Got an error destroying the old test database: %s\n' % e)
                            sys.exit(2)
                    except Exception as e:
                        sys.stderr.write('Got an error destroying the old test database: %s\n' % e)
                        sys.exit(2)
                    try:
                        self._execute_test_db_creation(cursor, parameters, verbosity, keepdb)
                    except Exception as e:
                        sys.stderr.write('Got an error recreating the test database: %s\n' % e)
                        sys.exit(2)
                else:
                    print('Tests cancelled.')
                    sys.exit(1)
        if self._test_user_create():
            if verbosity >= 1:
                print('Creating test user...')
            try:
                self._create_test_user(cursor, parameters, verbosity, keepdb)
            except Exception as e:
                if keepdb:
                    return
                sys.stderr.write('Got an error creating the test user: %s\n' % e)
                if not autoclobber:
                    confirm = input("It appears the test user, %s, already exists. Type 'yes' to delete it, or 'no' to cancel: " % parameters['user'])
                if autoclobber or confirm == 'yes':
                    try:
                        if verbosity >= 1:
                            print('Destroying old test user...')
                        self._destroy_test_user(cursor, parameters, verbosity)
                        if verbosity >= 1:
                            print('Creating test user...')
                        self._create_test_user(cursor, parameters, verbosity, keepdb)
                    except Exception as e:
                        sys.stderr.write('Got an error recreating the test user: %s\n' % e)
                        sys.exit(2)
                else:
                    print('Tests cancelled.')
                    sys.exit(1)
        self._maindb_connection.close()
        self._switch_to_test_user(parameters)
        return self.connection.settings_dict['NAME']

    def _switch_to_test_user(self, parameters):
        """
        Oracle doesn't have the concept of separate databases under the same user.
        Thus, we use a separate user (see _create_test_db). This method is used
        to switch to that user. We will need the main user again for clean-up when
        we end testing, so we keep its credentials in SAVED_USER/SAVED_PASSWORD
        entries in the settings dict.
        """
        real_settings = settings.DATABASES[self.connection.alias]
        real_settings['SAVED_USER'] = self.connection.settings_dict['SAVED_USER'] = self.connection.settings_dict['USER']
        real_settings['SAVED_PASSWORD'] = self.connection.settings_dict['SAVED_PASSWORD'] = self.connection.settings_dict['PASSWORD']
        real_test_settings = real_settings['TEST']
        test_settings = self.connection.settings_dict['TEST']
        real_test_settings['USER'] = real_settings['USER'] = test_settings['USER'] = self.connection.settings_dict['USER'] = parameters['user']
        real_settings['PASSWORD'] = self.connection.settings_dict['PASSWORD'] = parameters['password']

    def set_as_test_mirror(self, primary_settings_dict):
        """
        Set this database up to be used in testing as a mirror of a primary database
        whose settings are given
        """
        self.connection.settings_dict['USER'] = primary_settings_dict['USER']
        self.connection.settings_dict['PASSWORD'] = primary_settings_dict['PASSWORD']

    def _handle_objects_preventing_db_destruction(self, cursor, parameters, verbosity, autoclobber):
        print('There are objects in the old test database which prevent its destruction.')
        print('If they belong to the test user, deleting the user will allow the test database to be recreated.')
        print('Otherwise, you will need to find and remove each of these objects, or use a different tablespace.\n')
        if self._test_user_create():
            if not autoclobber:
                confirm = input("Type 'yes' to delete user %s: " % parameters['user'])
            if autoclobber or confirm == 'yes':
                try:
                    if verbosity >= 1:
                        print('Destroying old test user...')
                    self._destroy_test_user(cursor, parameters, verbosity)
                except Exception as e:
                    sys.stderr.write('Got an error destroying the test user: %s\n' % e)
                    sys.exit(2)
                try:
                    if verbosity >= 1:
                        print("Destroying old test database for alias '%s'..." % self.connection.alias)
                    self._execute_test_db_destruction(cursor, parameters, verbosity)
                except Exception as e:
                    sys.stderr.write('Got an error destroying the test database: %s\n' % e)
                    sys.exit(2)
            else:
                print('Tests cancelled -- test database cannot be recreated.')
                sys.exit(1)
        else:
            print("Django is configured to use pre-existing test user '%s', and will not attempt to delete it.\n" % parameters['user'])
            print('Tests cancelled -- test database cannot be recreated.')
            sys.exit(1)

    def _destroy_test_db(self, test_database_name, verbosity=1):
        """
        Destroy a test database, prompting the user for confirmation if the
        database already exists. Returns the name of the test database created.
        """
        self.connection.settings_dict['USER'] = self.connection.settings_dict['SAVED_USER']
        self.connection.settings_dict['PASSWORD'] = self.connection.settings_dict['SAVED_PASSWORD']
        self.connection.close()
        parameters = self._get_test_db_params()
        cursor = self._maindb_connection.cursor()
        time.sleep(1)
        if self._test_user_create():
            if verbosity >= 1:
                print('Destroying test user...')
            self._destroy_test_user(cursor, parameters, verbosity)
        if self._test_database_create():
            if verbosity >= 1:
                print('Destroying test database tables...')
            self._execute_test_db_destruction(cursor, parameters, verbosity)
        self._maindb_connection.close()

    def _execute_test_db_creation(self, cursor, parameters, verbosity, keepdb=False):
        if verbosity >= 2:
            print('_create_test_db(): dbname = %s' % parameters['user'])
        statements = ["CREATE TABLESPACE %(tblspace)s\n               DATAFILE '%(datafile)s' SIZE 20M\n               REUSE AUTOEXTEND ON NEXT 10M MAXSIZE %(maxsize)s\n            ", "CREATE TEMPORARY TABLESPACE %(tblspace_temp)s\n               TEMPFILE '%(datafile_tmp)s' SIZE 20M\n               REUSE AUTOEXTEND ON NEXT 10M MAXSIZE %(maxsize_tmp)s\n            "]
        acceptable_ora_err = 'ORA-01543' if keepdb else None
        self._execute_allow_fail_statements(cursor, statements, parameters, verbosity, acceptable_ora_err)

    def _create_test_user(self, cursor, parameters, verbosity, keepdb=False):
        if verbosity >= 2:
            print('_create_test_user(): username = %s' % parameters['user'])
        statements = ['CREATE USER %(user)s\n               IDENTIFIED BY %(password)s\n               DEFAULT TABLESPACE %(tblspace)s\n               TEMPORARY TABLESPACE %(tblspace_temp)s\n               QUOTA UNLIMITED ON %(tblspace)s\n            ', 'GRANT CREATE SESSION,\n                     CREATE TABLE,\n                     CREATE SEQUENCE,\n                     CREATE PROCEDURE,\n                     CREATE TRIGGER\n               TO %(user)s']
        acceptable_ora_err = 'ORA-01920' if keepdb else None
        self._execute_allow_fail_statements(cursor, statements, parameters, verbosity, acceptable_ora_err)
        extra = 'GRANT CREATE VIEW TO %(user)s'
        success = self._execute_allow_fail_statements(cursor, [extra], parameters, verbosity, 'ORA-01031')
        if not success and verbosity >= 2:
            print('Failed to grant CREATE VIEW permission to test user. This may be ok.')

    def _execute_test_db_destruction(self, cursor, parameters, verbosity):
        if verbosity >= 2:
            print('_execute_test_db_destruction(): dbname=%s' % parameters['user'])
        statements = ['DROP TABLESPACE %(tblspace)s INCLUDING CONTENTS AND DATAFILES CASCADE CONSTRAINTS', 'DROP TABLESPACE %(tblspace_temp)s INCLUDING CONTENTS AND DATAFILES CASCADE CONSTRAINTS']
        self._execute_statements(cursor, statements, parameters, verbosity)

    def _destroy_test_user(self, cursor, parameters, verbosity):
        if verbosity >= 2:
            print('_destroy_test_user(): user=%s' % parameters['user'])
            print('Be patient.  This can take some time...')
        statements = ['DROP USER %(user)s CASCADE']
        self._execute_statements(cursor, statements, parameters, verbosity)

    def _execute_statements(self, cursor, statements, parameters, verbosity, allow_quiet_fail=False):
        for template in statements:
            stmt = template % parameters
            if verbosity >= 2:
                print(stmt)
            try:
                cursor.execute(stmt)
            except Exception as err:
                if not allow_quiet_fail or verbosity >= 2:
                    sys.stderr.write('Failed (%s)\n' % err)
                raise

    def _execute_allow_fail_statements(self, cursor, statements, parameters, verbosity, acceptable_ora_err):
        """
        Execute statements which are allowed to fail silently if the Oracle
        error code given by `acceptable_ora_err` is raised. Return True if the
        statements execute without an exception, or False otherwise.
        """
        try:
            allow_quiet_fail = acceptable_ora_err is not None and len(acceptable_ora_err) > 0
            self._execute_statements(cursor, statements, parameters, verbosity, allow_quiet_fail=allow_quiet_fail)
            return True
        except DatabaseError as err:
            description = str(err)
            if acceptable_ora_err is None or acceptable_ora_err not in description:
                raise
            return False

    def _get_test_db_params(self):
        return {'dbname': self._test_database_name(), 'user': self._test_database_user(), 'password': self._test_database_passwd(), 'tblspace': self._test_database_tblspace(), 'tblspace_temp': self._test_database_tblspace_tmp(), 'datafile': self._test_database_tblspace_datafile(), 'datafile_tmp': self._test_database_tblspace_tmp_datafile(), 'maxsize': self._test_database_tblspace_size(), 'maxsize_tmp': self._test_database_tblspace_tmp_size()}

    def _test_settings_get(self, key, default=None, prefixed=None):
        """
        Return a value from the test settings dict,
        or a given default,
        or a prefixed entry from the main settings dict
        """
        settings_dict = self.connection.settings_dict
        val = settings_dict['TEST'].get(key, default)
        if val is None:
            val = TEST_DATABASE_PREFIX + settings_dict[prefixed]
        return val

    def _test_database_name(self):
        return self._test_settings_get('NAME', prefixed='NAME')

    def _test_database_create(self):
        return self._test_settings_get('CREATE_DB', default=True)

    def _test_user_create(self):
        return self._test_settings_get('CREATE_USER', default=True)

    def _test_database_user(self):
        return self._test_settings_get('USER', prefixed='USER')

    def _test_database_passwd(self):
        return self._test_settings_get('PASSWORD', default=PASSWORD)

    def _test_database_tblspace(self):
        return self._test_settings_get('TBLSPACE', prefixed='USER')

    def _test_database_tblspace_tmp(self):
        settings_dict = self.connection.settings_dict
        return settings_dict['TEST'].get('TBLSPACE_TMP', TEST_DATABASE_PREFIX + settings_dict['USER'] + '_temp')

    def _test_database_tblspace_datafile(self):
        tblspace = '%s.dbf' % self._test_database_tblspace()
        return self._test_settings_get('DATAFILE', default=tblspace)

    def _test_database_tblspace_tmp_datafile(self):
        tblspace = '%s.dbf' % self._test_database_tblspace_tmp()
        return self._test_settings_get('DATAFILE_TMP', default=tblspace)

    def _test_database_tblspace_size(self):
        return self._test_settings_get('DATAFILE_MAXSIZE', default='500M')

    def _test_database_tblspace_tmp_size(self):
        return self._test_settings_get('DATAFILE_TMP_MAXSIZE', default='500M')

    def _get_test_db_name(self):
        """
        We need to return the 'production' DB name to get the test DB creation
        machinery to work. This isn't a great deal in this case because DB
        names as handled by Django haven't real counterparts in Oracle.
        """
        return self.connection.settings_dict['NAME']

    def test_db_signature(self):
        settings_dict = self.connection.settings_dict
        return (settings_dict['HOST'], settings_dict['PORT'], settings_dict['ENGINE'], settings_dict['NAME'], self._test_database_user())

from datetime import date
from oslo_log import log as logging
from trove.common import cfg
from trove.common.i18n import _
from trove.common import stream_codecs
from trove.common import utils
from trove.guestagent.common import operating_system
from trove.guestagent.module.drivers import module_driver
LOG = logging.getLogger(__name__)
CONF = cfg.CONF
NR_ADD_LICENSE_CMD = ['nrsysmond-config', '--set', 'license_key=%s']
NR_SRV_CONTROL_CMD = ['/etc/init.d/newrelic-sysmond']

class NewRelicLicenseDriver(module_driver.ModuleDriver):
    """Module to set up the license for the NewRelic service."""

    def get_description(self):
        return 'New Relic License Module Driver'

    def get_updated(self):
        return date(2016, 4, 12)

    @module_driver.output(log_message=_('Installing New Relic license key'), success_message=_('New Relic license key installed'), fail_message=_('New Relic license key not installed'))
    def apply(self, name, datastore, ds_version, data_file, admin_module):
        license_key = None
        data = operating_system.read_file(data_file, codec=stream_codecs.KeyValueCodec())
        for (key, value) in data.items():
            if 'license_key' == key.lower():
                license_key = value
                break
        if license_key:
            self._add_license_key(license_key)
            self._server_control('start')
        else:
            return (False, "'license_key' not found in contents file")

    def _add_license_key(self, license_key):
        try:
            exec_args = {'timeout': 10, 'run_as_root': True, 'root_helper': 'sudo'}
            cmd = list(NR_ADD_LICENSE_CMD)
            cmd[-1] = cmd[-1] % license_key
            utils.execute_with_timeout(*cmd, **exec_args)
        except Exception:
            LOG.exception(_("Could not install license key '%s'") % license_key)
            raise

    def _server_control(self, command):
        try:
            exec_args = {'timeout': 10, 'run_as_root': True, 'root_helper': 'sudo'}
            cmd = list(NR_SRV_CONTROL_CMD)
            cmd.append(command)
            utils.execute_with_timeout(*cmd, **exec_args)
        except Exception:
            LOG.exception(_('Could not %s New Relic server') % command)
            raise

    @module_driver.output(log_message=_('Removing New Relic license key'), success_message=_('New Relic license key removed'), fail_message=_('New Relic license key not removed'))
    def remove(self, name, datastore, ds_version, data_file):
        self._add_license_key('bad_key')
        self._server_control('stop')

"""Tricks that depend on a certain DNS provider.

Tricks that require inheritence by nameserver.py must go here, otherwise,
see providers.py for externally available functions.
"""
__author__ = 'tstromberg@google.com (Thomas Stromberg)'

class NameServerProvider(object):
    """Inherited by nameserver."""

    def GetMyResolverIpWithDuration(self):
        return self.GetIpFromNameWithDuration('self.myresolver.info.')

    def GetMyResolverHostNameWithDuration(self):
        return self.GetNameFromNameWithDuration('self.myresolver.info.')

    def GetOpenDnsNodeWithDuration(self):
        return self.GetTxtRecordWithDuration('which.opendns.com.')[0:2]

    def GetOpenDnsInterceptionStateWithDuration(self):
        """Check if our packets are actually getting to the correct servers."""
        (node_id, duration) = self.GetOpenDnsNodeWithDuration()
        if node_id and 'I am not an OpenDNS resolver' in node_id:
            return (True, duration)
        return (False, duration)

    def GetUltraDnsNodeWithDuration(self):
        return self.GetNameFromNameWithDuration('whoareyou.ultradns.net.')

import logging
import traceback
from netman import regex
import re

class SubShell(object):
    debug = False

    def __init__(self, ssh, enter, exit_cmd, validate=None):
        self.ssh = ssh
        self.enter = enter
        self.exit = exit_cmd
        self.validate = validate or (lambda x: None)

    def __enter__(self):
        if isinstance(self.enter, list):
            [self.validate(self.ssh.do(cmd)) for cmd in self.enter]
        else:
            self.validate(self.ssh.do(self.enter))
        return self.ssh

    def __exit__(self, eType, eValue, eTrace):
        if self.debug and eType is not None:
            logging.error('Subshell exception {}: {}\n{}'.format(eType.__name__, eValue, ''.join(traceback.format_tb(eTrace))))
        self.ssh.do(self.exit)

def no_output(exc, *args):

    def m(welcome_msg):
        if len(welcome_msg) > 0:
            raise exc(*args)
    return m

def split_on_bang(data):
    current_chunk = []
    for line in data:
        if re.match('^!.*', line):
            if len(current_chunk) > 0:
                yield current_chunk
                current_chunk = []
        else:
            current_chunk.append(line)

def split_on_dedent(data):
    current_chunk = []
    for line in data:
        if re.match('^[^\\s].*', line) and len(current_chunk) > 0:
            yield current_chunk
            current_chunk = [line]
        else:
            current_chunk.append(line)
    yield current_chunk

class ResultChecker(object):

    def __init__(self, result=None):
        self.result = result

    def on_any_result(self, exception, *args, **kwargs):
        if self.result and len(self.result) > 0:
            raise exception(*args, **kwargs)
        return self

    def on_result_matching(self, matcher, exception, *args, **kwargs):
        if regex.match(matcher, '\n'.join(self.result), flags=re.DOTALL):
            raise exception(*args, **kwargs)
        return self

class PageReader(object):

    def __init__(self, read_while, and_press, unless_prompt):
        self.next_page_indicator = read_while
        self.continue_key = and_press
        self.prompt = unless_prompt

    def do(self, shell, command):
        result = shell.do(command, wait_for=(self.next_page_indicator, self.prompt), include_last_line=True)
        while len(result) > 0 and self.next_page_indicator in result[-1]:
            result = result[:-1] + shell.send_key(self.continue_key, wait_for=(self.next_page_indicator, self.prompt), include_last_line=True)
        return result[:-1]

from openerp import SUPERUSER_ID
from openerp.osv import osv
from openerp.tools.translate import _

class mail_mail(osv.Model):
    """ Update of mail_mail class, to add the signin URL to notifications. """
    _inherit = 'mail.mail'

    def _get_partner_access_link(self, cr, uid, mail, partner=None, context=None):
        """ Generate URLs for links in mails:
            - partner is not an user: signup_url
            - partner is an user: fallback on classic URL
        """
        if context is None:
            context = {}
        partner_obj = self.pool.get('res.partner')
        if partner and (not partner.user_ids):
            contex_signup = dict(context, signup_valid=True)
            signup_url = partner_obj._get_signup_url_for_action(cr, SUPERUSER_ID, [partner.id], action='mail.action_mail_redirect', model=mail.model, res_id=mail.res_id, context=contex_signup)[partner.id]
            return ", <span class='oe_mail_footer_access'><small>%(access_msg)s <a style='color:inherit' href='%(portal_link)s'>%(portal_msg)s</a></small></span>" % {'access_msg': _('access directly to'), 'portal_link': signup_url, 'portal_msg': '%s %s' % (context.get('model_name', ''), mail.record_name) if mail.record_name else _('your messages ')}
        else:
            return super(mail_mail, self)._get_partner_access_link(cr, uid, mail, partner=partner, context=context)

