class TestStemmer(InvenioTestCase):
    """Test stemmer."""

    def test_stemmer_none(self):
        """bibindex engine - no stemmer"""
        self.assertEqual('information', bibindex_engine_stemmer.stem('information', None))

    def test_stemmer_english(self):
        """bibindex engine - English stemmer"""
        english_test_cases = [['information', 'inform'], ['experiment', 'experi'], ['experiments', 'experi'], ['experimented', 'experi'], ['experimenting', 'experi'], ['experimental', 'experiment'], ['experimentally', 'experiment'], ['experimentation', 'experiment'], ['experimentalism', 'experiment'], ['experimenter', 'experiment'], ['experimentalise', 'experimentalis'], ['experimentalist', 'experimentalist'], ['experimentalists', 'experimentalist'], ['GeV', 'GeV'], ['$\\Omega$', '$\\Omega$'], ['e^-', 'e^-'], ['C#', 'C#'], ['C++', 'C++']]
        for (test_word, expected_result) in english_test_cases:
            self.assertEqual(expected_result, bibindex_engine_stemmer.stem(test_word, 'en'))

