class Aerospike(AgentCheck):

    def create_timeboard(self, api_key, api_application_key, instance_name, node_address, ns_list):
        response = aerospike_dashboards.draw_node_dashboard(api_key, api_application_key, instance_name, node_address)
        if response is None:
            self.log.error('Unable to Create Node Dashboard due to error' + ' while importing Dogapi and/or Datadog')
        if ns_list in ERROR_CODES:
            self.log.error('Namespace List is Empty, cannot create namespace Dashboards.')
