        for ns in ns_list:
            response = aerospike_dashboards.draw_namespace_dashboard(api_key, api_application_key, instance_name, node_address, ns)
            if response is None:
                self.log.error('Unable to Create Namespace: ' + str(ns) + ' Dashboard due to error while' + ' importing Dogapi and/or Datadog')

    def check(self, instance):
        global bcrypt_flag
        ip = str(instance['ip'])
        port = str(instance['port'])
        user = instance['user']
        password = str(instance['password'])
        cls_mode = instance['cluster_mode']
        debug_mode = instance['debug_mode']
        instance_name = str(instance['cluster_name'])
        api_key = str(instance['api_key'])
        api_application_key = str(instance['api_application_key'])
        if cls_mode:
            log.print_log(self, 'Using Aerospike Datadog Coneector in clustered mode...')
        else:
            log.print_log(self, 'Using Aerospike Datadog Coneector in non-clustered mode...')
        if user != 'n/s':
            if bcrypt_flag:
                valid_pwd = interface.is_valid_password(password, HASH_KEY)
                if valid_pwd:
