UNMASKED_DIGITS_TO_SHOW = 6
mask_password = lambda p: '%s%s' % (p[:UNMASKED_DIGITS_TO_SHOW], '*' * max(len(p) - UNMASKED_DIGITS_TO_SHOW, 0))

class ReadOnlyPasswordHashWidget(forms.Widget):

    def render(self, name, value, attrs):
        encoded = value
        final_attrs = self.build_attrs(attrs)
        if encoded == '' or encoded == UNUSABLE_PASSWORD:
            summary = mark_safe('<strong>%s</strong>' % ugettext('No password set.'))
        else:
            try:
                hasher = identify_hasher(encoded)
            except ValueError:
                summary = mark_safe('<strong>%s</strong>' % ugettext('Invalid password format or unknown hashing algorithm.'))
            else:
                summary = format_html_join('', '<strong>{0}</strong>: {1} ', ((ugettext(key), value) for (key, value) in hasher.safe_summary(encoded).items()))
        return format_html('<div{0}>{1}</div>', flatatt(final_attrs), summary)

