    pid = -1
    from os import path as ospath
    if ospath.isfile(pidfname):
        pidfile = open(pidfname)
        pid = pidfile.readline().strip('\n')
        pidfile.close()
    return int(pid)

def pidfile_release(pidfname):
    from os import path as ospath
