from ansible.errors import AnsibleConnectionFailure
from ansible.module_utils._text import to_text, to_bytes
from ansible.plugins.terminal import TerminalBase

class TerminalModule(TerminalBase):
    terminal_stdout_re = [re.compile(b'[\\r\\n]?[\\w+\\-\\.:\\/\\[\\]]+(?:\\([^\\)]+\\)){,3}(?:>|#) ?$'), re.compile(b'\\[\\w+\\@[\\w\\-\\.]+(?: [^\\]])\\] ?[>#\\$] ?$'), re.compile(b'>[\\r\\n]?')]
    terminal_stderr_re = [re.compile(b'% ?Error'), re.compile(b'% ?Bad secret'), re.compile(b'invalid input', re.I), re.compile(b'(?:incomplete|ambiguous) command', re.I), re.compile(b'connection timed out', re.I), re.compile(b'[^\\r\\n]+ not found'), re.compile(b"'[^']' +returned error code: ?\\d+")]

    def on_open_shell(self):
        try:
            for cmd in (b'\n', b'terminal-length 0\n'):
                self._exec_cli_command(cmd)
        except AnsibleConnectionFailure:
            raise AnsibleConnectionFailure('unable to set terminal parameters')

    def on_become(self, passwd=None):
        if self._get_prompt().endswith(b'#'):
            return
        cmd = {u'command': u'enable'}
        if passwd:
            cmd[u'prompt'] = to_text('[\\r\\n]?password: $', errors='surrogate_or_strict')
            cmd[u'answer'] = passwd
        try:
            self._exec_cli_command(to_bytes(json.dumps(cmd), errors='surrogate_or_strict'))
        except AnsibleConnectionFailure:
            msg = 'unable to elevate privilege to enable mode'
            raise AnsibleConnectionFailure(msg)

    def on_unbecome(self):
        prompt = self._get_prompt()
        if prompt is None:
            return
        if b'(config' in prompt:
            self._exec_cli_command(b'end')
            self._exec_cli_command(b'disable')
        elif prompt.endswith(b'#'):
            self._exec_cli_command(b'disable')

