import traceback
import sys, os, time, errno
from test.script_helper import assert_python_ok, spawn_python
try:
    import threading
except ImportError:
    threading = None

class HandlerBCalled(Exception):
    pass

def exit_subprocess():
    """Use os._exit(0) to exit the current subprocess.

    Otherwise, the test catches the SystemExit and continues executing
    in parallel with the original test, so you wind up with an
    exponential number of tests running concurrently.
    """
    os._exit(0)

def ignoring_eintr(__func, *args, **kwargs):
    try:
        return __func(*args, **kwargs)
    except OSError as e:
        if e.errno != errno.EINTR:
            raise
        return None

@unittest.skipIf(sys.platform == 'win32', 'Not valid on Windows')
class InterProcessSignalTests(unittest.TestCase):
    MAX_DURATION = 20

    def setUp(self):
        self.using_gc = gc.isenabled()
        gc.disable()

    def tearDown(self):
        if self.using_gc:
            gc.enable()

    def format_frame(self, frame, limit=None):
        return ''.join(traceback.format_stack(frame, limit=limit))

    def handlerA(self, signum, frame):
        self.a_called = True

    def handlerB(self, signum, frame):
        self.b_called = True
        raise HandlerBCalled(signum, self.format_frame(frame))

    def wait(self, child):
        """Wait for child to finish, ignoring EINTR."""
        while True:
            try:
                child.wait()
                return
            except OSError as e:
                if e.errno != errno.EINTR:
                    raise

    def run_test(self):
        signal.signal(signal.SIGHUP, self.handlerA)
        signal.signal(signal.SIGUSR1, self.handlerB)
        signal.signal(signal.SIGUSR2, signal.SIG_IGN)
        signal.signal(signal.SIGALRM, signal.default_int_handler)
        self.a_called = False
        self.b_called = False
        pid = os.getpid()
        child = ignoring_eintr(subprocess.Popen, ['kill', '-HUP', str(pid)])
        if child:
            self.wait(child)
            if not self.a_called:
                time.sleep(1)
        self.assertTrue(self.a_called)
        self.assertFalse(self.b_called)
        self.a_called = False
        del child
        try:
            child = subprocess.Popen(['kill', '-USR1', str(pid)])
            self.wait(child)
            time.sleep(1)
            self.fail('HandlerBCalled exception not raised')
        except HandlerBCalled:
            self.assertTrue(self.b_called)
            self.assertFalse(self.a_called)
        child = ignoring_eintr(subprocess.Popen, ['kill', '-USR2', str(pid)])
        if child:
            self.wait(child)
        try:
            signal.alarm(1)
            signal.pause()
            time.sleep(1)
        except KeyboardInterrupt:
            pass
        except:
            self.fail('Some other exception woke us from pause: %s' % traceback.format_exc())
        else:
            self.fail("pause returned of its own accord, and the signal didn't arrive after another second.")

    @unittest.skipIf(sys.platform == 'freebsd6', 'inter process signals not reliable (do not mix well with threading) on freebsd6')
    def test_main(self):
        (os_done_r, os_done_w) = os.pipe()
        with closing(os.fdopen(os_done_r, 'rb')) as done_r, closing(os.fdopen(os_done_w, 'wb')) as done_w:
            child = os.fork()
            if child == 0:
                try:
                    done_r.close()
                    with closing(done_w):
                        try:
                            self.run_test()
                        except:
                            pickle.dump(traceback.format_exc(), done_w)
                        else:
                            pickle.dump(None, done_w)
                except:
                    print('Uh oh, raised from pickle.')
                    traceback.print_exc()
                finally:
                    exit_subprocess()
            done_w.close()
            (r, w, x) = select.select([done_r], [], [], self.MAX_DURATION)
            if done_r in r:
                tb = pickle.load(done_r)
                if tb:
                    self.fail(tb)
            else:
                os.kill(child, signal.SIGKILL)
                self.fail('Test deadlocked after %d seconds.' % self.MAX_DURATION)

