        assert_python_ok('-c', code)

    def test_wakeup_fd_early(self):
        self.check_wakeup('def test():\n            import select\n            import time\n\n            TIMEOUT_FULL = 10\n            TIMEOUT_HALF = 5\n\n            signal.alarm(1)\n            before_time = time.time()\n            # We attempt to get a signal during the sleep,\n            # before select is called\n            time.sleep(TIMEOUT_FULL)\n            mid_time = time.time()\n            dt = mid_time - before_time\n            if dt >= TIMEOUT_HALF:\n                raise Exception("%s >= %s" % (dt, TIMEOUT_HALF))\n            select.select([read], [], [], TIMEOUT_FULL)\n            after_time = time.time()\n            dt = after_time - mid_time\n            if dt >= TIMEOUT_HALF:\n                raise Exception("%s >= %s" % (dt, TIMEOUT_HALF))\n        ', signal.SIGALRM)

    def test_wakeup_fd_during(self):
        self.check_wakeup('def test():\n            import select\n            import time\n\n            TIMEOUT_FULL = 10\n            TIMEOUT_HALF = 5\n\n            signal.alarm(1)\n            before_time = time.time()\n            # We attempt to get a signal during the select call\n            try:\n                select.select([read], [], [], TIMEOUT_FULL)\n            except OSError:\n                pass\n            else:\n                raise Exception("OSError not raised")\n            after_time = time.time()\n            dt = after_time - before_time\n            if dt >= TIMEOUT_HALF:\n                raise Exception("%s >= %s" % (dt, TIMEOUT_HALF))\n        ', signal.SIGALRM)

    def test_signum(self):
        self.check_wakeup('def test():\n            signal.signal(signal.SIGUSR1, handler)\n            os.kill(os.getpid(), signal.SIGUSR1)\n            os.kill(os.getpid(), signal.SIGALRM)\n        ', signal.SIGUSR1, signal.SIGALRM)

    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    def test_pending(self):
        self.check_wakeup('def test():\n            signum1 = signal.SIGUSR1\n            signum2 = signal.SIGUSR2\n\n            signal.signal(signum1, handler)\n            signal.signal(signum2, handler)\n\n            signal.pthread_sigmask(signal.SIG_BLOCK, (signum1, signum2))\n            os.kill(os.getpid(), signum1)\n            os.kill(os.getpid(), signum2)\n            # Unblocking the 2 signals calls the C signal handler twice\n            signal.pthread_sigmask(signal.SIG_UNBLOCK, (signum1, signum2))\n        ', signal.SIGUSR1, signal.SIGUSR2, ordered=False)

@unittest.skipIf(sys.platform == 'win32', 'Not valid on Windows')
class SiginterruptTest(unittest.TestCase):

    def readpipe_interrupted(self, interrupt):
        """Perform a read during which a signal will arrive.  Return True if the
        read is interrupted by the signal and raises an exception.  Return False
        if it returns normally.
        """
        code = 'if 1:\n            import errno\n            import os\n            import signal\n            import sys\n\n            interrupt = %r\n            r, w = os.pipe()\n\n            def handler(signum, frame):\n                pass\n\n            signal.signal(signal.SIGALRM, handler)\n            if interrupt is not None:\n                signal.siginterrupt(signal.SIGALRM, interrupt)\n\n            print("ready")\n            sys.stdout.flush()\n\n            # run the test twice\n            for loop in range(2):\n                # send a SIGALRM in a second (during the read)\n                signal.alarm(1)\n                try:\n                    # blocking call: read from a pipe without data\n                    os.read(r, 1)\n                except OSError as err:\n                    if err.errno != errno.EINTR:\n                        raise\n                else:\n                    sys.exit(2)\n            sys.exit(3)\n        ' % (interrupt,)
        with spawn_python('-c', code) as process:
            try:
                first_line = process.stdout.readline()
                (stdout, stderr) = process.communicate(timeout=5.0)
            except subprocess.TimeoutExpired:
                process.kill()
                return False
            else:
                stdout = first_line + stdout
                exitcode = process.wait()
                if exitcode not in (2, 3):
                    raise Exception('Child error (exit code %s): %r' % (exitcode, stdout))
                return exitcode == 3

    def test_without_siginterrupt(self):
        interrupted = self.readpipe_interrupted(None)
        self.assertTrue(interrupted)

    def test_siginterrupt_on(self):
        interrupted = self.readpipe_interrupted(True)
        self.assertTrue(interrupted)

    def test_siginterrupt_off(self):
        interrupted = self.readpipe_interrupted(False)
        self.assertFalse(interrupted)

@unittest.skipIf(sys.platform == 'win32', 'Not valid on Windows')
class ItimerTest(unittest.TestCase):

    def setUp(self):
        self.hndl_called = False
        self.hndl_count = 0
        self.itimer = None
        self.old_alarm = signal.signal(signal.SIGALRM, self.sig_alrm)

    def tearDown(self):
        signal.signal(signal.SIGALRM, self.old_alarm)
        if self.itimer is not None:
            signal.setitimer(self.itimer, 0)

    def sig_alrm(self, *args):
        self.hndl_called = True

    def sig_vtalrm(self, *args):
        self.hndl_called = True
        if self.hndl_count > 3:
            raise signal.ItimerError("setitimer didn't disable ITIMER_VIRTUAL timer.")
        elif self.hndl_count == 3:
            signal.setitimer(signal.ITIMER_VIRTUAL, 0)
        self.hndl_count += 1

    def sig_prof(self, *args):
        self.hndl_called = True
        signal.setitimer(signal.ITIMER_PROF, 0)

    def test_itimer_exc(self):
        self.assertRaises(signal.ItimerError, signal.setitimer, -1, 0)
        if 0:
            self.assertRaises(signal.ItimerError, signal.setitimer, signal.ITIMER_REAL, -1)

    def test_itimer_real(self):
        self.itimer = signal.ITIMER_REAL
        signal.setitimer(self.itimer, 1.0)
        signal.pause()
        self.assertEqual(self.hndl_called, True)

    @unittest.skipIf(sys.platform in ('freebsd6', 'netbsd5'), 'itimer not reliable (does not mix well with threading) on some BSDs.')
    def test_itimer_virtual(self):
        self.itimer = signal.ITIMER_VIRTUAL
        signal.signal(signal.SIGVTALRM, self.sig_vtalrm)
        signal.setitimer(self.itimer, 0.3, 0.2)
        start_time = time.time()
        while time.time() - start_time < 60.0:
            _ = pow(12345, 67890, 10000019)
            if signal.getitimer(self.itimer) == (0.0, 0.0):
                break
        else:
            self.skipTest('timeout: likely cause: machine too slow or load too high')
        self.assertEqual(signal.getitimer(self.itimer), (0.0, 0.0))
        self.assertEqual(self.hndl_called, True)

    @unittest.skipIf(sys.platform == 'freebsd6', 'itimer not reliable (does not mix well with threading) on freebsd6')
    def test_itimer_prof(self):
        self.itimer = signal.ITIMER_PROF
        signal.signal(signal.SIGPROF, self.sig_prof)
        signal.setitimer(self.itimer, 0.2, 0.2)
        start_time = time.time()
        while time.time() - start_time < 60.0:
            _ = pow(12345, 67890, 10000019)
            if signal.getitimer(self.itimer) == (0.0, 0.0):
                break
        else:
            self.skipTest('timeout: likely cause: machine too slow or load too high')
        self.assertEqual(signal.getitimer(self.itimer), (0.0, 0.0))
        self.assertEqual(self.hndl_called, True)

class PendingSignalsTests(unittest.TestCase):
    """
    Test pthread_sigmask(), pthread_kill(), sigpending() and sigwait()
    functions.
    """

    @unittest.skipUnless(hasattr(signal, 'sigpending'), 'need signal.sigpending()')
    def test_sigpending_empty(self):
        self.assertEqual(signal.sigpending(), set())

    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    @unittest.skipUnless(hasattr(signal, 'sigpending'), 'need signal.sigpending()')
    def test_sigpending(self):
        code = 'if 1:\n            import os\n            import signal\n\n            def handler(signum, frame):\n                1/0\n\n            signum = signal.SIGUSR1\n            signal.signal(signum, handler)\n\n            signal.pthread_sigmask(signal.SIG_BLOCK, [signum])\n            os.kill(os.getpid(), signum)\n            pending = signal.sigpending()\n            if pending != {signum}:\n                raise Exception(\'%s != {%s}\' % (pending, signum))\n            try:\n                signal.pthread_sigmask(signal.SIG_UNBLOCK, [signum])\n            except ZeroDivisionError:\n                pass\n            else:\n                raise Exception("ZeroDivisionError not raised")\n        '
        assert_python_ok('-c', code)

    @unittest.skipUnless(hasattr(signal, 'pthread_kill'), 'need signal.pthread_kill()')
    def test_pthread_kill(self):
        code = 'if 1:\n            import signal\n            import threading\n            import sys\n\n            signum = signal.SIGUSR1\n\n            def handler(signum, frame):\n                1/0\n\n            signal.signal(signum, handler)\n\n            if sys.platform == \'freebsd6\':\n                # Issue #12392 and #12469: send a signal to the main thread\n                # doesn\'t work before the creation of the first thread on\n                # FreeBSD 6\n                def noop():\n                    pass\n                thread = threading.Thread(target=noop)\n                thread.start()\n                thread.join()\n\n            tid = threading.get_ident()\n            try:\n                signal.pthread_kill(tid, signum)\n            except ZeroDivisionError:\n                pass\n            else:\n                raise Exception("ZeroDivisionError not raised")\n        '
        assert_python_ok('-c', code)

    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    def wait_helper(self, blocked, test):
        """
        test: body of the "def test(signum):" function.
        blocked: number of the blocked signal
        """
        code = 'if 1:\n        import signal\n        import sys\n\n        def handler(signum, frame):\n            1/0\n\n        %s\n\n        blocked = %s\n        signum = signal.SIGALRM\n\n        # child: block and wait the signal\n        try:\n            signal.signal(signum, handler)\n            signal.pthread_sigmask(signal.SIG_BLOCK, [blocked])\n\n            # Do the tests\n            test(signum)\n\n            # The handler must not be called on unblock\n            try:\n                signal.pthread_sigmask(signal.SIG_UNBLOCK, [blocked])\n            except ZeroDivisionError:\n                print("the signal handler has been called",\n                      file=sys.stderr)\n                sys.exit(1)\n        except BaseException as err:\n            print("error: {}".format(err), file=sys.stderr)\n            sys.stderr.flush()\n            sys.exit(1)\n        ' % (test.strip(), blocked)
        assert_python_ok('-c', code)

    @unittest.skipUnless(hasattr(signal, 'sigwait'), 'need signal.sigwait()')
    def test_sigwait(self):
        self.wait_helper(signal.SIGALRM, "\n        def test(signum):\n            signal.alarm(1)\n            received = signal.sigwait([signum])\n            if received != signum:\n                raise Exception('received %s, not %s' % (received, signum))\n        ")

    @unittest.skipUnless(hasattr(signal, 'sigwaitinfo'), 'need signal.sigwaitinfo()')
    def test_sigwaitinfo(self):
        self.wait_helper(signal.SIGALRM, '\n        def test(signum):\n            signal.alarm(1)\n            info = signal.sigwaitinfo([signum])\n            if info.si_signo != signum:\n                raise Exception("info.si_signo != %s" % signum)\n        ')

    @unittest.skipUnless(hasattr(signal, 'sigtimedwait'), 'need signal.sigtimedwait()')
    def test_sigtimedwait(self):
        self.wait_helper(signal.SIGALRM, "\n        def test(signum):\n            signal.alarm(1)\n            info = signal.sigtimedwait([signum], 10.1000)\n            if info.si_signo != signum:\n                raise Exception('info.si_signo != %s' % signum)\n        ")

    @unittest.skipUnless(hasattr(signal, 'sigtimedwait'), 'need signal.sigtimedwait()')
    def test_sigtimedwait_poll(self):
        self.wait_helper(signal.SIGALRM, "\n        def test(signum):\n            import os\n            os.kill(os.getpid(), signum)\n            info = signal.sigtimedwait([signum], 0)\n            if info.si_signo != signum:\n                raise Exception('info.si_signo != %s' % signum)\n        ")

    @unittest.skipUnless(hasattr(signal, 'sigtimedwait'), 'need signal.sigtimedwait()')
    def test_sigtimedwait_timeout(self):
        self.wait_helper(signal.SIGALRM, '\n        def test(signum):\n            received = signal.sigtimedwait([signum], 1.0)\n            if received is not None:\n                raise Exception("received=%r" % (received,))\n        ')

    @unittest.skipUnless(hasattr(signal, 'sigtimedwait'), 'need signal.sigtimedwait()')
    def test_sigtimedwait_negative_timeout(self):
        signum = signal.SIGALRM
        self.assertRaises(ValueError, signal.sigtimedwait, [signum], -1.0)

    @unittest.skipUnless(hasattr(signal, 'sigwaitinfo'), 'need signal.sigwaitinfo()')
    @unittest.skipIf(sys.platform.startswith('aix'), 'signal.sigwaitinfo() cannot be interrupted on AIX')
    def test_sigwaitinfo_interrupted(self):
        self.wait_helper(signal.SIGUSR1, '\n        def test(signum):\n            import errno\n\n            hndl_called = True\n            def alarm_handler(signum, frame):\n                hndl_called = False\n\n            signal.signal(signal.SIGALRM, alarm_handler)\n            signal.alarm(1)\n            try:\n                signal.sigwaitinfo([signal.SIGUSR1])\n            except OSError as e:\n                if e.errno == errno.EINTR:\n                    if not hndl_called:\n                        raise Exception("SIGALRM handler not called")\n                else:\n                    raise Exception("Expected EINTR to be raised by sigwaitinfo")\n            else:\n                raise Exception("Expected EINTR to be raised by sigwaitinfo")\n        ')

    @unittest.skipUnless(hasattr(signal, 'sigwait'), 'need signal.sigwait()')
    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    @unittest.skipIf(threading is None, 'test needs threading module')
    def test_sigwait_thread(self):
        assert_python_ok('-c', 'if True:\n            import os, threading, sys, time, signal\n\n            # the default handler terminates the process\n            signum = signal.SIGUSR1\n\n            def kill_later():\n                # wait until the main thread is waiting in sigwait()\n                time.sleep(1)\n                os.kill(os.getpid(), signum)\n\n            # the signal must be blocked by all the threads\n            signal.pthread_sigmask(signal.SIG_BLOCK, [signum])\n            killer = threading.Thread(target=kill_later)\n            killer.start()\n            received = signal.sigwait([signum])\n            if received != signum:\n                print("sigwait() received %s, not %s" % (received, signum),\n                      file=sys.stderr)\n                sys.exit(1)\n            killer.join()\n            # unblock the signal, which should have been cleared by sigwait()\n            signal.pthread_sigmask(signal.SIG_UNBLOCK, [signum])\n        ')

    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    def test_pthread_sigmask_arguments(self):
        self.assertRaises(TypeError, signal.pthread_sigmask)
        self.assertRaises(TypeError, signal.pthread_sigmask, 1)
        self.assertRaises(TypeError, signal.pthread_sigmask, 1, 2, 3)
        self.assertRaises(OSError, signal.pthread_sigmask, 1700, [])

    @unittest.skipUnless(hasattr(signal, 'pthread_sigmask'), 'need signal.pthread_sigmask()')
    def test_pthread_sigmask(self):
        code = 'if 1:\n        import signal\n        import os; import threading\n\n        def handler(signum, frame):\n            1/0\n\n        def kill(signum):\n            os.kill(os.getpid(), signum)\n\n        def read_sigmask():\n            return signal.pthread_sigmask(signal.SIG_BLOCK, [])\n\n        signum = signal.SIGUSR1\n\n        # Install our signal handler\n        old_handler = signal.signal(signum, handler)\n\n        # Unblock SIGUSR1 (and copy the old mask) to test our signal handler\n        old_mask = signal.pthread_sigmask(signal.SIG_UNBLOCK, [signum])\n        try:\n            kill(signum)\n        except ZeroDivisionError:\n            pass\n        else:\n            raise Exception("ZeroDivisionError not raised")\n\n        # Block and then raise SIGUSR1. The signal is blocked: the signal\n        # handler is not called, and the signal is now pending\n        signal.pthread_sigmask(signal.SIG_BLOCK, [signum])\n        kill(signum)\n\n        # Check the new mask\n        blocked = read_sigmask()\n        if signum not in blocked:\n            raise Exception("%s not in %s" % (signum, blocked))\n        if old_mask ^ blocked != {signum}:\n            raise Exception("%s ^ %s != {%s}" % (old_mask, blocked, signum))\n\n        # Unblock SIGUSR1\n        try:\n            # unblock the pending signal calls immediately the signal handler\n            signal.pthread_sigmask(signal.SIG_UNBLOCK, [signum])\n        except ZeroDivisionError:\n            pass\n        else:\n            raise Exception("ZeroDivisionError not raised")\n        try:\n            kill(signum)\n        except ZeroDivisionError:\n            pass\n        else:\n            raise Exception("ZeroDivisionError not raised")\n\n        # Check the new mask\n        unblocked = read_sigmask()\n        if signum in unblocked:\n            raise Exception("%s in %s" % (signum, unblocked))\n        if blocked ^ unblocked != {signum}:\n            raise Exception("%s ^ %s != {%s}" % (blocked, unblocked, signum))\n        if old_mask != unblocked:\n            raise Exception("%s != %s" % (old_mask, unblocked))\n        '
        assert_python_ok('-c', code)

    @unittest.skipIf(sys.platform == 'freebsd6', "issue #12392: send a signal to the main thread doesn't work before the creation of the first thread on FreeBSD 6")
    @unittest.skipUnless(hasattr(signal, 'pthread_kill'), 'need signal.pthread_kill()')
    def test_pthread_kill_main_thread(self):
        code = 'if True:\n            import threading\n            import signal\n            import sys\n\n            def handler(signum, frame):\n                sys.exit(3)\n\n            signal.signal(signal.SIGUSR1, handler)\n            signal.pthread_kill(threading.get_ident(), signal.SIGUSR1)\n            sys.exit(2)\n        '
        with spawn_python('-c', code) as process:
            (stdout, stderr) = process.communicate()
            exitcode = process.wait()
            if exitcode != 3:
                raise Exception('Child error (exit code %s): %s' % (exitcode, stdout))

def test_main():
    try:
        support.run_unittest(PosixTests, InterProcessSignalTests, WakeupFDTests, WakeupSignalTests, SiginterruptTest, ItimerTest, WindowsSignalTests, PendingSignalsTests)
    finally:
        support.reap_children()
if __name__ == '__main__':
    test_main()
